  const getCurrentMonth = () => MONTH_NAMES[new Date().getMonth()];
  const getInitialMonth = () => {
    try {
      const saved = typeof localStorage !== 'undefined' ? localStorage.getItem(STATUTORY_MONTH_FILTER_KEY) : null;
      if (saved && String(saved).trim() !== '') return String(saved).trim();
    } catch (_) {}
    return getCurrentMonth();
  };
  const [selectedMonth, setSelectedMonth] = useState(getInitialMonth);
  const [tableSearch, setTableSearch] = useState('');
  const [selectedFormFilter, setSelectedFormFilter] = useState('all');
  const [selectedStatusFilter, setSelectedStatusFilter] = useState('all');
  const [currentPage, setCurrentPage] = useState(1);
  const PAGE_SIZE = 10;
  useEffect(() => {
    formTableDataRef.current = Array.isArray(formTableData) ? formTableData : [];
  }, [formTableData]);
  const persistMonthFilter = (month) => {
    try {
      if (typeof localStorage !== 'undefined' && month) localStorage.setItem(STATUTORY_MONTH_FILTER_KEY, month);
    } catch (_) {}
  };

  // Monthly / day-of-month due dates: show as "7-Jun" or "15-Jun" using UI month filter
  const formatMonthlyBasisDate = (dueDate, monthFallback = '') => {
    if (!dueDate) return '';

    const dueDateStr = String(dueDate).trim();
    const dueDateLower = dueDateStr.toLowerCase();
    if (/^\d{1,2}-[a-z]{3}/i.test(dueDateStr)) return dueDateStr;

    const monthSource =
      (selectedMonth && String(selectedMonth).trim()) ||
      (monthFallback && String(monthFallback).trim()) ||
      '';
    const fullMonth = monthSource ? resolveToFullMonthName(monthSource) : null;
    let monthAbbr = null;
    if (fullMonth) {
      const idx = MONTH_NAMES.indexOf(fullMonth);
      if (idx >= 0) monthAbbr = MONTH_ABBR[idx];
    } else if (monthSource) {
      const monthIndex = MONTH_NAMES.findIndex((m) =>
        m.toLowerCase().startsWith(monthSource.toLowerCase())
      );
      if (monthIndex !== -1) monthAbbr = MONTH_ABBR[monthIndex];
      else monthAbbr = monthSource.substring(0, 3);
    }

    if (dueDateLower.includes('monthly basis') && monthAbbr) {
      return `15-${monthAbbr}`;
    }

    const day = extractDayOfMonthFromDueDate(dueDate);
    if (day != null && monthAbbr) {
      return `${day}-${monthAbbr}`;
    }

    return dueDateStr;
  };

  // Collapse checklist bulk placeholders vs Statutory DB rows after save (canonical month + site + numeric ROW priority).
  const removeDuplicateStatutoryRecords = (mergedRows, resolveSiteFn, uiMonthFallback) => {
    if (!mergedRows || mergedRows.length === 0) {
      return mergedRows;
    }

    const duplicateMap = new Map();

    mergedRows.forEach((item) => {
      const normalizedFormName = squashStatutoryKeyPart(item.formName || item.FormName);
      const normalizedAct = squashStatutoryKeyPart(item.act || item.Act);
      const normalizedDescription = squashStatutoryKeyPart(item.description || item.Description);
      const normalizedSector = squashStatutoryKeyPart(item.sector || item.Sector) || 'nosector';
      const normalizedState = squashStatutoryKeyPart(item.state || item.State) || 'nostate';
      const monthNorm = statutoryDedupeMonthNorm(item, uiMonthFallback);
      const siteKey = statutoryCollapseSiteKey(item, mergedRows, resolveSiteFn);
      const key = `${normalizedFormName}_${normalizedAct}_${normalizedDescription}_${monthNorm}_${normalizedSector || 'nosector'}_${normalizedState || 'nostate'}_${siteKey}`;

      if (!duplicateMap.has(key)) {
        duplicateMap.set(key, []);
      }
      duplicateMap.get(key).push(item);
    });

    const deduplicated = [];

    duplicateMap.forEach((group) => {
      if (group.length === 1) {
        deduplicated.push(group[0]);
        return;
      }
      const best = [...group].sort((a, b) => {
        const sc = statutoryRowRichnessScore(b) - statutoryRowRichnessScore(a);
        if (sc !== 0) return sc;
        return String(b.id || '').localeCompare(String(a.id || ''));
      })[0];
      deduplicated.push(best);
      console.log(`🔍 Removed ${group.length - 1} duplicate(s) for "${group[0].formName}" — kept record ID ${best.id}`);
    });

    return deduplicated;
  };

  // Convert Formmaster template list to statutory row shape; include formFile/formFileName so Form File column shows link
  const formmasterTemplatesToRows = (templates) => {
    if (!templates || !Array.isArray(templates)) return [];
    const timestamp = Date.now();
    return templates.map((t, index) => {
      const rawName = (t.templateFileName || t.name || t.file_name || '').trim();
      const formName =
        (t.formName || '').trim() ||
        rawName.replace(/\.xlsx$/i, '').trim() ||
        rawName;
      const fileId = t.id != null ? String(t.id) : null;
      const fileName = rawName || 'template.xlsx';
      return {
        id: `formmaster_${t.recordId || fileId || timestamp}_${index}`,
        formName,
        sector: t.sector || '',
        state: t.state || '',
        act: t.act || '',
        dueDate: '',
        description: t.description || '',
        concernedGovtDepartment: '',
        formFile: fileId,
        formFileName: fileName,
        autofill: '',
        draft: '',
        proofSubmissionFile: null,
        proofSubmissionFileName: null,
        isFromFormmaster: true,
        formmasterMatchKey: t.matchKey || buildFormmasterMatchKey({ formName, act: t.act, description: t.description, sector: t.sector, state: t.state })
      };
    });
  };

  // Function to merge ChecklistBulk data with Statutory data
  // All ChecklistBulk rows are displayed in Statutory (no filtering by form name)
  const mergeBulkDataWithStatutory = (statutoryData, bulkData) => {
    if (!bulkData || bulkData.length === 0) {
      return statutoryData;
    }

    // Convert all bulk data to statutory format – every ChecklistBulk row is included
    const timestamp = Date.now();
    const convertedBulkData = bulkData.map((bulkItem, index) => ({
      id: `bulk_${bulkItem.id ?? timestamp}_${index}`,
      formName: bulkItem.formName || '',
      sector: bulkItem.sector || bulkItem.Sector || '',
      state: bulkItem.state || bulkItem.State || '',
      act: bulkItem.act || '',
      dueDate: bulkItem.dueDate || '',
      description: bulkItem.description || '',
      concernedGovtDepartment: bulkItem.concernedGovtDepartment || '',
      formFile: bulkItem.formFile || bulkItem.FormFile || null,
      formFileName: bulkItem.formFileName || bulkItem.FormFileName || null,
      autofill: '',
      draft: '',
      proofSubmissionFile: null,
      proofSubmissionFileName: null,
      isBulkImported: true
    }));

    // Merge: statutory data first, then ALL ChecklistBulk rows so every bulk record is displayed
    const merged = [...statutoryData, ...convertedBulkData];
    console.log(`✅ mergeBulkDataWithStatutory: ${merged.length} total entries (${statutoryData.length} statutory + ${convertedBulkData.length} from ChecklistBulk – all bulk data shown)`);
    return merged;
  };

  // Fill missing meta fields (act/description/dueDate) from bulk entries
  const enrichWithBulkMetadata = (data, bulkData) => {
    if (!bulkData || bulkData.length === 0) return data;

    const bulkMap = new Map();
    bulkData.forEach((bulkItem) => {
      const fn = String(bulkItem.formName || '').toLowerCase().trim();
      if (!fn) return;
      const sec = String(bulkItem.sector || '').trim().toLowerCase();
      const st = String(bulkItem.state || bulkItem.State || '').trim().toLowerCase();
      bulkMap.set(`${fn}|${sec}|${st}`, bulkItem);
    });

    const pick = (primary, fallback) => {
      const primaryTrimmed = String(primary || '').trim();
      if (primaryTrimmed) return primary;
      const fallbackTrimmed = String(fallback || '').trim();
      return fallbackTrimmed ? fallback : primary;
    };

    return data.map((item) => {
      const fn = String(item.formName || '').toLowerCase().trim();
      if (!fn) return item;
      const sec = String(item.sector || item.Sector || '').trim().toLowerCase();
      const st = String(item.state || item.State || '').trim().toLowerCase();
      let bulkItem = bulkMap.get(`${fn}|${sec}|${st}`);
      if (!bulkItem && !st) {
        bulkItem = bulkData.find(
          (b) =>
            String(b.formName || '').toLowerCase().trim() === fn &&
            String(b.sector || '').trim().toLowerCase() === sec &&
            !String(b.state || b.State || '').trim()
        );
      }
      if (!bulkItem) return item;

      return {
        ...item,
        act: pick(item.act ?? item.Act, bulkItem.act),
        description: pick(item.description ?? item.Description, bulkItem.description),
        dueDate: pick(item.dueDate ?? item.DueDate, bulkItem.dueDate),
        sector: pick(item.sector ?? item.Sector, bulkItem.sector ?? bulkItem.Sector),
        state: pick(item.state ?? item.State, bulkItem.state ?? bulkItem.State)
      };
    });
  };

  // Fetch statutory data
  const fetchStatutoryData = async (options = {}) => {
    const { useCacheFirst = false, silentRefresh = false, force = false } = options;

    if (isFetchingStatutoryRef.current && !force) {
      console.log('⏭️ Skipping duplicate statutory fetch (already in progress)');
      return;
    }
    isFetchingStatutoryRef.current = true;

    if (useCacheFirst) {
      try {
        const cached = localStorage.getItem('statutoryData');
        if (cached) {
          const parsed = JSON.parse(cached);
          if (Array.isArray(parsed) && parsed.length > 0) {
            setStatutoryData(parsed);
          }
        }
      } catch (_) {}
    }

    if (!silentRefresh) {
      setLoading(true);
      setError('');
      setSuccess('');
    }
    try {
      const siteScopePromise = fetchAllowedActCategoriesFromSites(userEmail)
        .then((sc) => sc)
        .catch((scopeErr) => {
          console.warn('Could not load statutory scope from Site Management:', scopeErr);
          return null;
        });
      const siteNamesPromise = (async () => {
        const loginResolved = normalizeEmail(await resolveLoginEmailString(userEmail));
        try {
          const resp = await fetch('/server/sitemanagement_function/sitemanagement', { cache: 'no-store' });
          if (!resp.ok)
            return {
              byCategory: {},
              allowedNames: null,
              inchargeStates: null,
              inchargeSites: [],
              organizationSites: [],
              siteDetails: []
            };
          const json = await resp.json().catch(() => ({}));
          const details = Array.isArray(json?.data?.siteDetails) ? json.data.siteDetails : [];
          const buckets = {
            factories: new Set(),
            shops_and_establishment: new Set(),
            clra: new Set()
          };
          const allowedNames = new Set();
          const inchargeStates = new Set();
          const inchargeSites = [];
          const organizationSites = [];
          details.forEach((s) => {
            const industry = String(s?.industry ?? s?.Industry ?? '').trim();
            const siteName = String(s?.siteName ?? s?.SiteName ?? '').trim();
            const st = String(s?.siteState ?? s?.SiteState ?? s?.state ?? s?.State ?? '').trim();
            if (siteName && st) {
              organizationSites.push({
                siteName,
                siteState: st,
                industry,
                actCategory: industryLabelToActCategory(industry)
              });
            }
            const inchargeEmail = normalizeEmail(
              String(s?.inchargeEmail ?? s?.InchargeEmail ?? s?.incharge_email ?? '')
            );
            if (!inchargeEmail || inchargeEmail !== loginResolved) return;
            if (siteName) allowedNames.add(siteName);
            if (st) inchargeStates.add(st);
            if (siteName) {
              inchargeSites.push({
                siteName,
                siteState: st,
                industry,
                actCategory: industryLabelToActCategory(industry)
              });
            }
            if (!industry || !siteName) return;
            const cat = industryLabelToActCategory(industry);
            if (!cat || !buckets[cat]) return;
            buckets[cat].add(siteName);
          });
          return {
            byCategory: {
              factories: Array.from(buckets.factories),
              shops_and_establishment: Array.from(buckets.shops_and_establishment),
              clra: Array.from(buckets.clra)
            },
            allowedNames: allowedNames.size > 0 ? Array.from(allowedNames) : null,
            inchargeStates: inchargeStates.size > 0 ? Array.from(inchargeStates) : null,
            inchargeSites,
            organizationSites,
            siteDetails: details
          };
        } catch {
          return {
            byCategory: {},
            allowedNames: null,
            inchargeStates: null,
            inchargeSites: [],
            organizationSites: [],
            siteDetails: []
          };
        }
      })();

      const response = await fetch(
        `/server/statutoryreg_function/statutory?_=${Date.now()}`,
        {
          cache: 'no-store',
          headers: {
            'Cache-Control': 'no-cache, no-store, must-revalidate',
            Pragma: 'no-cache'
          }
        }
      );
      let baseStatutoryData = [];
      let parsedBulkDataCache = null;
      let siteScopeCategories = null;

      if (response.ok) {
        const data = await response.json();
        const siteMeta = await siteNamesPromise;
        setSiteNamesByActCategory(siteMeta?.byCategory || {});
        setAllowedSiteNameList(siteMeta?.allowedNames || null);
        setInchargeSitesMeta(Array.isArray(siteMeta?.inchargeSites) ? siteMeta.inchargeSites : []);
        setOrganizationSitesMeta(Array.isArray(siteMeta?.organizationSites) ? siteMeta.organizationSites : []);
        setSiteDetailsList(Array.isArray(siteMeta?.siteDetails) ? siteMeta.siteDetails : []);
        if (Array.isArray(siteMeta?.siteDetails) && siteMeta.siteDetails.length > 0) {
          writeSiteDetailsCache(siteMeta.siteDetails);
        }
        setAllowedInchargeStateLabels(siteMeta?.inchargeStates ?? null);
        if (data.status === 'success' && data.data && data.data.statutoryData) {
          baseStatutoryData = data.data.statutoryData;
          // Normalize field names to handle both camelCase and PascalCase
          baseStatutoryData = baseStatutoryData.map(item => ({
            ...item,
            formFile: item.formFile || item.FormFile || null,
            formFileName: item.formFileName || item.FormFileName || null,
            sampleFile: item.sampleFile || item.SampleFile || item.formFile || item.FormFile || null,
            sampleFileName: item.sampleFileName || item.SampleFileName || item.formFileName || item.FormFileName || null,
            formName: item.formName || item.FormName || '',
            act: item.act || item.Act || '',
            sector: item.sector || item.Sector || '',
            state: item.state || item.State || '',
            site: item.site || item.Site || item.siteName || item.SiteName || '',
            description: item.description || item.Description || '',
            dueDate: item.dueDate || item.DueDate || '',
            monthFilter: item.monthFilter || item.MonthFilter || item.monthfilter || null,
            autofill: item.autofill || item.Autofill || '',
            draft: item.draft || item.Draft || '',
            proofSubmissionFile: item.proofSubmissionFile || item.ProofSubmissionFile || null,
            proofSubmissionFileName: item.proofSubmissionFileName || item.ProofSubmissionFileName || null,
            draftFile: item.draftFile || item.DraftFile || null,
            draftFileName: item.draftFileName || item.DraftFileName || null,
            approval: item.approval || item.Approval || '',
            status: item.status != null && item.status !== '' ? item.status : item.Status != null ? item.Status : '',
            sendForApproval: item.sendForApproval || item.SendForApproval || '',
            remarks: item.remarks || item.Remarks || '',
            submittedDate:
              item.submittedDate || item.SubmittedDate || item.draftDate || item.DraftDate || '',
            approvedDate:
              item.approvedDate || item.ApprovedDate || item.approvalDate || item.ApprovalDate || ''
          }));

          // Keep rendering consistent: avoid partial first paint; show final merged dataset once ready.
          siteScopeCategories = await siteScopePromise;
          setAllowedActCategoryList(siteScopeCategories);
         
          // Log entries with files
          const entriesWithFiles = baseStatutoryData.filter(item =>
            item.formFile && item.formFile !== 'null' && String(item.formFile).trim() !== ''
          );
          console.log(`📋 Fetched ${baseStatutoryData.length} statutory items from backend`);
          console.log(`📁 ${entriesWithFiles.length} entries have form files:`, entriesWithFiles.map(item => ({
            id: item.id,
            formName: item.formName,
            formFile: item.formFile,
            formFileName: item.formFileName
          })));
         
          // Specifically check for Form U
          const formUFromDB = baseStatutoryData.filter(item => {
            const formName = (item.formName || '').toLowerCase();
            return formName.includes('form u') || formName === 'form u';
          });
          if (formUFromDB.length > 0) {
            console.log(`🔍 Form U entries from database:`, formUFromDB.map(item => ({
              id: item.id,
              formName: item.formName,
              formFile: item.formFile,
              formFileName: item.formFileName,
              hasFile: !!(item.formFile && item.formFile !== 'null' && String(item.formFile).trim() !== '')
            })));
          }
        } else {
          const localData = localStorage.getItem('statutoryData');
          if (localData) {
            baseStatutoryData = JSON.parse(localData);
          }
        }
      } else {
        throw new Error('Failed to fetch statutory data');
      }

      // Fetch Checklist data (where SEMaster saves files)
      let checklistDataWithFiles = [];
      try {
        const checklistResponse = await fetch('/server/checklist_function/checklist', {
          cache: 'no-store'
        });
        if (checklistResponse.ok) {
          const checklistResult = await checklistResponse.json();
          if (checklistResult.status === 'success' && checklistResult.data && checklistResult.data.checklistData) {
            checklistDataWithFiles = checklistResult.data.checklistData;
            console.log(`📋 Fetched ${checklistDataWithFiles.length} items from Checklist`);
           
            // Filter to only items with form files
            const checklistItemsWithFiles = checklistDataWithFiles.filter(item =>
              item.formFile &&
              item.formFile !== 'null' &&
              item.formFile !== null &&
              String(item.formFile).trim() !== '' &&
              !String(item.formFile).startsWith('STATUTORY_MASTER_FORM:') // Exclude StatutoryMaster markers
            );
            console.log(`📁 ${checklistItemsWithFiles.length} Checklist items have form files`);
           
            // Specifically log Form I entries from Checklist
            const checklistFormIEntries = checklistItemsWithFiles.filter(item => {
              const formName = String(item.formName || '').toLowerCase().trim();
              return formName === 'form i';
            });
            console.log(`📋 Found ${checklistFormIEntries.length} Form I entries in Checklist with files:`, checklistFormIEntries.map(item => ({
              id: item.id,
              formName: item.formName,
              formFile: item.formFile,
              formFileName: item.formFileName,
              act: item.act,
              description: item.description
            })));
           
            console.log(`📁 All Checklist items with files:`, checklistItemsWithFiles.map(item => ({
              id: item.id,
              formName: item.formName,
              formFile: item.formFile,
              formFileName: item.formFileName
            })));
           
            // Merge Checklist items with files into statutory data
            // Create a map of statutory data by form name for quick lookup
            // Note: This map only stores ONE entry per form name for lookup purposes
            // but ALL entries remain in baseStatutoryData
            const normalizeFormName = (name) => {
              return String(name || '')
                .toLowerCase()
                .replace(/\s*-\s*/g, ' ')
                .replace(/\s+/g, ' ')
                .trim();
            };

            const extractFormId = (name) => {
              return normalizeFormName(name).replace(/^form\s*/i, '').trim();
            };
            /** Base form id for matching (e.g. "Form U" and "Form U - Register" both -> "u") */
            const getBaseFormId = (name) => {
              const id = extractFormId(name);
              const first = (id || '').split(/\s+/)[0];
              return (first || id || '').toLowerCase();
            };

            const statutoryByFormName = new Map();
            baseStatutoryData.forEach(item => {
              const normalizedName = normalizeFormName(item.formName);
              if (normalizedName && !statutoryByFormName.has(normalizedName)) {
                // Only set if not already in map (first entry wins for lookup)
                statutoryByFormName.set(normalizedName, item);
              }
            });
           
            console.log(`📊 Before Checklist merge: ${baseStatutoryData.length} entries in baseStatutoryData`);

            const hasValidFormFile = (item) => {
              const formFile = item?.formFile;
              return !!(formFile && formFile !== 'null' && String(formFile).trim() !== '');
            };
           
            // Add all Checklist entries with files to statutory data
            // Each Checklist entry becomes a separate row, even if they have the same form name (e.g., 3 Form I entries)
            // This ensures that if SEMaster imports Form I 3 times, all 3 will display as separate rows
            checklistItemsWithFiles.forEach(checklistItem => {
              const normalizedFormName = normalizeFormName(checklistItem.formName);
              if (!normalizedFormName) return;
             
              // Check if this exact Checklist entry already exists in statutory data (by checklistId)
              const existingChecklistEntry = baseStatutoryData.find(
                item => item.checklistId === checklistItem.id && item.isFromChecklist
              );
             
              if (existingChecklistEntry) {
                // Update existing Checklist entry if it's already there
                existingChecklistEntry.formFile = checklistItem.formFile;
                existingChecklistEntry.formFileName = checklistItem.formFileName;
                existingChecklistEntry.act = checklistItem.act || existingChecklistEntry.act || '';
                existingChecklistEntry.description = checklistItem.description || existingChecklistEntry.description || '';
                existingChecklistEntry.dueDate = checklistItem.dueDate || existingChecklistEntry.dueDate || '';
                existingChecklistEntry.sector = checklistItem.sector || existingChecklistEntry.sector || '';
                existingChecklistEntry.state = checklistItem.state || existingChecklistEntry.state || '';
                existingChecklistEntry.isFromChecklist = true;
                existingChecklistEntry.checklistId = checklistItem.id;
                console.log(`✅ Updated existing Checklist entry "${checklistItem.formName}" (ID: ${checklistItem.id})`);
                return;
              } else {
                // If a base statutory row exists with the same form name (or same base form e.g. "Form U" vs "Form U - Register"), always update that same row with the checklist file (do not add a new row).
                // This prevents duplicate rows when user imports e.g. Form U in SEMaster: Statutory already has Form U; show the imported file in that same row.
                let baseStatutoryMatch = statutoryByFormName.get(normalizedFormName);
                if (!baseStatutoryMatch) {
                  const checklistFormId = extractFormId(checklistItem.formName);
                  const checklistBaseId = getBaseFormId(checklistItem.formName);
                  if (checklistFormId) {
                    baseStatutoryMatch = baseStatutoryData.find(item => {
                      const itemFormId = extractFormId(item.formName);
                      if (itemFormId && itemFormId === checklistFormId) return true;
                      // Match by base form id so "Form U" matches "Form U - Register" (both base "u")
                      return checklistBaseId && getBaseFormId(item.formName) === checklistBaseId;
                    });
                  }
                }
                if (baseStatutoryMatch) {
                  baseStatutoryMatch.formFile = checklistItem.formFile;
                  baseStatutoryMatch.formFileName = checklistItem.formFileName;
                  baseStatutoryMatch.act = checklistItem.act || baseStatutoryMatch.act || '';
                  baseStatutoryMatch.description = checklistItem.description || baseStatutoryMatch.description || '';
                  baseStatutoryMatch.dueDate = checklistItem.dueDate || baseStatutoryMatch.dueDate || '';
                  baseStatutoryMatch.sector = checklistItem.sector || baseStatutoryMatch.sector || '';
                  baseStatutoryMatch.state = checklistItem.state || baseStatutoryMatch.state || '';
                  baseStatutoryMatch.isFromChecklist = true;
                  baseStatutoryMatch.checklistId = checklistItem.id;
                  console.log(`🔗 Updated existing statutory row "${baseStatutoryMatch.formName}" with Checklist file (Checklist ID: ${checklistItem.id}) - no duplicate row`);
                  return;
                }

                // Only add a new row when there is no existing statutory row for this form name (e.g. form exists only in Checklist)
                // Otherwise add Checklist entries as new separate rows
                // This ensures all Checklist entries with files are preserved, even if they share the same form name
                // Each Checklist entry gets its own row (e.g., 3 Form I entries = 3 rows)
                const newEntry = {
                  id: `checklist_${checklistItem.id}`,
                  formName: checklistItem.formName || '',
                  act: checklistItem.act || '',
                  description: checklistItem.description || '',
                  dueDate: checklistItem.dueDate || '',
                  formFile: checklistItem.formFile,
                  formFileName: checklistItem.formFileName,
                  autofill: '',
                  draft: '',
                  proofSubmissionFile: checklistItem.proofSubmissionFile || null,
                  proofSubmissionFileName: checklistItem.proofSubmissionFileName || null,
                  sector: checklistItem.sector || '',
                  state: checklistItem.state || '',
                  isFromChecklist: true,
                  checklistId: checklistItem.id // Store original Checklist ID for file download
                };
                baseStatutoryData.push(newEntry);
                // Only set in map if it's the first entry with this form name (for lookup purposes only, doesn't prevent duplicates)
                if (!statutoryByFormName.has(normalizedFormName)) {
                  statutoryByFormName.set(normalizedFormName, newEntry);
                }
                console.log(`➕ Added new Checklist entry "${checklistItem.formName}" with file (ID: ${checklistItem.id})`);
              }
            });
           
            // Log Form I entries after merge for debugging
            const formIEntries = baseStatutoryData.filter(item => {
              const formName = String(item.formName || '').toLowerCase().trim();
              return formName === 'form i';
            });
            if (formIEntries.length > 0) {
              console.log(`📋 Found ${formIEntries.length} Form I entry/entries after Checklist merge:`, formIEntries.map(item => ({
                id: item.id,
                checklistId: item.checklistId,
                formName: item.formName,
                formFileName: item.formFileName,
                isFromChecklist: item.isFromChecklist || false,
                act: item.act,
                description: item.description
              })));
            }
           
            // Log total count after Checklist merge
            console.log(`📊 Total entries after Checklist merge: ${baseStatutoryData.length}`);
          }
        }
      } catch (checklistError) {
        console.error('Error fetching Checklist data:', checklistError);
      }

      // Load form names from Formmaster (not ChecklistBulk/SEMaster) – one row per template
      let mergedData = [...baseStatutoryData];
      console.log(`📊 Before Formmaster merge: ${mergedData.length} entries`);

      let formmasterTemplates = [];
      try {
        const fmRes = await fetch(FORMMASTER_TEMPLATES_API, { cache: 'no-store' });
        if (fmRes.ok) {
          const fmData = await fmRes.json();
          if (fmData.status === 'success' && Array.isArray(fmData.data)) {
            formmasterTemplates = fmData.data;
            console.log(`📋 Fetched ${formmasterTemplates.length} templates from Formmaster`);
          }
        }
      } catch (fmErr) {
        console.error('Error fetching Formmaster templates:', fmErr);
      }

      if (formmasterTemplates.length >= 0) {
        setFormmasterTemplates(formmasterTemplates || []);
      }
      if (formmasterTemplates.length > 0) {
        const existingFormmasterKeys = new Set(
          baseStatutoryData.map((item) => buildFormmasterMatchKey(item)).filter(Boolean)
        );
        const formmasterRows = formmasterTemplatesToRows(formmasterTemplates).filter(
          (row) => !existingFormmasterKeys.has(buildFormmasterMatchKey(row))
        );
        if (formmasterRows.length > 0) {
          mergedData = [...baseStatutoryData, ...formmasterRows];
          console.log(`✅ Merged ${mergedData.length} total statutory items (${baseStatutoryData.length} statutory + ${formmasterRows.length} from Formmaster with form file links)`);
        }
      }

      // Fetch ChecklistBulk (all bulk records – e.g. 13 Shops and Establishment)
      let bulkFromApi = null;
      try {
        const bulkResponse = await fetch('/server/checklistbulk_function/checklistbulk?action=getAll', { cache: 'no-store' });
        if (bulkResponse.ok) {
          const bulkResult = await bulkResponse.json();
          if (bulkResult.status === 'success' && bulkResult.data && Array.isArray(bulkResult.data)) {
            bulkFromApi = bulkResult.data;
            localStorage.setItem('checklistBulkData', JSON.stringify(bulkFromApi));
          }
        }
      } catch (bulkError) {
        console.error('Error fetching ChecklistBulk data:', bulkError);
      }
      const bulkToMerge = bulkFromApi ?? (() => {
        try {
          const stored = localStorage.getItem('checklistBulkData');
          return stored ? JSON.parse(stored) : null;
        } catch {
          return null;
        }
      })();
      if (bulkToMerge && bulkToMerge.length > 0) {
        parsedBulkDataCache = bulkToMerge;
        // Merge ALL ChecklistBulk rows so every bulk record is displayed (e.g. 13 Shops and Establishment forms)
        mergedData = mergeBulkDataWithStatutory(mergedData, bulkToMerge);
      }

      // Email-based sector filtering (Shops & Establishment only) for specific users
      // IMPORTANT: apply this AFTER bulk metadata enrichment so that `sector` is populated
      // for checklist-derived entries (e.g., Form D).

      // Note: Checklist entries are now also filtered by sector/act to ensure proper categorization
      // Forms from one sector should not appear in another sector's section

      // Safety net: ensure Form U entries from backend are not lost after merge/filter
      const backendFormUEntries = (baseStatutoryData || []).filter(item => {
        const formName = String(item.formName || '').toLowerCase().trim();
        return formName === 'form u' || formName.includes('form u');
      });
      const mergedHasFormU = (mergedData || []).some(item => {
        const formName = String(item.formName || '').toLowerCase().trim();
        return formName === 'form u' || formName.includes('form u');
      });
      if (backendFormUEntries.length > 0 && !mergedHasFormU) {
        console.warn('⚠️ Form U present in backend data but missing after merge. Reinserting from backend copy.');
        mergedData = [...mergedData, ...backendFormUEntries];
      }

      // Enrich missing Act/Description/DueDate/Sector/State using bulk metadata (keeps Form U fully populated)
      mergedData = enrichWithBulkMetadata(mergedData, parsedBulkDataCache);

      // Statutory merges DB rows + SEMaster Checklist + Formmaster + appended bulk rows — count can exceed ChecklistBulk.
      // Business rule: when ChecklistBulk master data exists, Statutory must mirror it 1:1.
      // Keep exactly one displayed row per ChecklistBulk line and only overlay file/draft metadata from merged sources.
      if (parsedBulkDataCache && parsedBulkDataCache.length > 0) {
        const beforeAlign = mergedData.length;
        const canonicalBulkRows = mergeBulkDataWithStatutory([], parsedBulkDataCache);
        const formmasterFileByMatchKey = new Map();
        (formmasterTemplates || []).forEach((t) => {
          const fileId = t.id != null ? String(t.id) : null;
          if (!fileId) return;
          const lineRow = {
            formName: t.formName,
            act: t.act,
            description: t.description,
            sector: t.sector,
            state: t.state
          };
          const keys = new Set([
            t.matchKey,
            buildFormmasterMatchKey(lineRow),
            checklistBulkRowIdentityKey(lineRow)
          ].filter(Boolean));
          const payload = {
            formFile: fileId,
            formFileName: t.templateFileName || t.name || 'template.xlsx',
            storageFileName: t.name || null,
            isFromFormmaster: true
          };
          keys.forEach((key) => formmasterFileByMatchKey.set(key, payload));
        });
        const byIdentity = new Map();
        const byFormName = new Map();
        mergedData.forEach((item) => {
          const identityKey = checklistBulkRowIdentityKey(item);
          if (identityKey) {
            const list = byIdentity.get(identityKey) || [];
            list.push(item);
            byIdentity.set(identityKey, list);
          }
          const formNameKey = baseFormNameKey(item.formName || item.FormName);
          if (formNameKey) {
            const list = byFormName.get(formNameKey) || [];
            list.push(item);
            byFormName.set(formNameKey, list);
          }
        });
        const donorScore = (row) => {
          let score = 0;
          if (hasStatutoryDraftFileRef(row)) score += 1000;
          if (row?.formFile && String(row.formFile).trim() !== '') score += 100;
          const sfa = String(row?.sendForApproval ?? row?.SendForApproval ?? '').trim().toLowerCase();
          if (sfa === 'sent') score += 500;
          if (resolveStatutorySubmittedDateStored(row)) score += 80;
          const approval = String(row?.approval ?? row?.Approval ?? '').trim().toLowerCase();
          if (approval === 'approved' || approval === 'rejected' || approval === 'approve' || approval === 'reject') score += 30;
          if (approval === 'approved' || approval === 'approve') score += 200;
          if (resolveStatutoryApprovedDateStored(row)) score += 120;
          if (isNumericStatutoryBackendId(row?.id)) score += 10;
          return score;
        };
        mergedData = canonicalBulkRows.map((bulkRow) => {
          const identityKey = checklistBulkRowIdentityKey(bulkRow);
          const formNameKey = baseFormNameKey(bulkRow.formName || bulkRow.FormName);
          const identityMatches = byIdentity.get(identityKey) || [];
          const formMatches = byFormName.get(formNameKey) || [];
          // Keep draft/proof/approval metadata strict to the same statutory line.
          // Allow a second-level fallback by (form + act + description) only, because
          // bulk rows can have slight sector/state differences across sources.
          const norm = (v) => String(v ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
          const formActDescMatches = formMatches.filter((row) => statutoryLineMetadataMatches(bulkRow, row));
          const strictDonorCandidates = [...identityMatches, ...formActDescMatches];
          const formFileDonorCandidates = [...identityMatches, ...formMatches];
          const bulkMonthNorm = statutoryDedupeMonthNorm(bulkRow, selectedMonth);
          const uiMonthNormForAlign = statutoryDedupeMonthNorm(
            { monthFilter: selectedMonth, MonthFilter: selectedMonth },
            selectedMonth
          );
          const sameMonthDonors = strictDonorCandidates.filter((row) => {
            const rowMonth = statutoryDedupeMonthNorm(row, selectedMonth);
            if (rowMonth === bulkMonthNorm) return true;
            return statutoryMonthMatchesUiFilter(row, uiMonthNormForAlign, selectedMonth);
          });
          const scoredSameMonth = [...sameMonthDonors].sort((a, b) => donorScore(b) - donorScore(a));
          let monthDonor = scoredSameMonth[0] || null;
          if (!monthDonor) {
            const draftDonorPool = [...strictDonorCandidates, ...formActDescMatches, ...formMatches]
              .filter((row, idx, arr) => arr.indexOf(row) === idx)
              .filter((row) => hasStatutoryDraftFileRef(row) && statutoryLineMetadataMatches(bulkRow, row));
            monthDonor =
              [...draftDonorPool].sort((a, b) => donorScore(b) - donorScore(a))[0] || null;
          }
          const strictFormFileDonorCandidates = formFileDonorCandidates.filter((row) =>
            statutoryLineMetadataMatches(bulkRow, row)
          );
          const scoredAllForFormFile = [...strictFormFileDonorCandidates].sort(
            (a, b) => donorScore(b) - donorScore(a)
          );
          const hasFormRef = (r) => {
            const fid = r?.formFile ?? r?.FormFile;
            return fid != null && String(fid).trim() !== '' && String(fid).trim() !== 'null';
          };
          // Template Form File may exist on another month's statutory row — ok to reuse for Autofill.
          // Draft / proof / send-for-approval / stored MonthFilter must NEVER bleed across months.
          let formDonor = monthDonor;
          if (!formDonor || !hasFormRef(formDonor)) {
            formDonor = scoredAllForFormFile.find(hasFormRef) || formDonor;
          }
          const uiMonthOnlyLabel =
            resolveToFullMonthName(String(selectedMonth || '').trim()) ||
            String(selectedMonth || '').trim() ||
            null;
          if (!monthDonor) {
            const draftOnlyDonor = [...strictDonorCandidates, ...formActDescMatches, ...formMatches]
              .filter((row, idx, arr) => arr.indexOf(row) === idx)
              .filter((row) => hasStatutoryDraftFileRef(row) && statutoryLineMetadataMatches(bulkRow, row))
              .sort((a, b) => donorScore(b) - donorScore(a))[0] || null;
            const fmExactNoDonor =
              formmasterFileByMatchKey.get(buildFormmasterMatchKey(bulkRow)) ||
              formmasterFileByMatchKey.get(checklistBulkRowIdentityKey(bulkRow));
            return {
              ...bulkRow,
              id: bulkRow.id,
              formFile: fmExactNoDonor?.formFile ?? formDonor?.formFile ?? formDonor?.FormFile ?? bulkRow.formFile ?? null,
              formFileName: fmExactNoDonor?.formFileName ?? formDonor?.formFileName ?? formDonor?.FormFileName ?? bulkRow.formFileName ?? null,
              isFromFormmaster: !!fmExactNoDonor,
              draftFile: draftOnlyDonor?.draftFile ?? draftOnlyDonor?.DraftFile ?? null,
              draftFileName: draftOnlyDonor?.draftFileName ?? draftOnlyDonor?.DraftFileName ?? null,
              draft: draftOnlyDonor?.draft ?? draftOnlyDonor?.Draft ?? '',
              proofSubmissionFile: null,
              proofSubmissionFileName: null,
              sendForApproval: '',
              SendForApproval: '',
              approval: '',
              Approval: '',
              status: '',
              Status: '',
              remarks: '',
              Remarks: '',
              submittedDate: '',
              SubmittedDate: '',
              approvedDate: '',
              ApprovedDate: '',
              monthFilter: uiMonthOnlyLabel,
              MonthFilter: uiMonthOnlyLabel,
              monthfilter: uiMonthOnlyLabel,
              draftStatutoryRowIdForFile: isNumericStatutoryBackendId(draftOnlyDonor?.id)
                ? String(draftOnlyDonor.id)
                : null,
              checklistId: bulkRow.checklistId ?? formDonor?.checklistId ?? null,
              isFromChecklist: !!formDonor?.isFromChecklist && !!monthDonor
            };
          }
          const donor = monthDonor;
          const fmExact =
            formmasterFileByMatchKey.get(buildFormmasterMatchKey(bulkRow)) ||
            formmasterFileByMatchKey.get(checklistBulkRowIdentityKey(bulkRow));
          return {
            ...bulkRow,
            // Keep canonical bulk id so each ChecklistBulk row remains distinct in UI grouping/deduping.
            id: bulkRow.id,
            checklistId: donor?.checklistId ?? bulkRow.checklistId ?? null,
            isFromChecklist: donor?.isFromChecklist ?? false,
            formFile: fmExact?.formFile ?? formDonor?.formFile ?? formDonor?.FormFile ?? bulkRow.formFile,
            formFileName: fmExact?.formFileName ?? formDonor?.formFileName ?? formDonor?.FormFileName ?? bulkRow.formFileName,
            isFromFormmaster: !!fmExact || !!formDonor?.isFromFormmaster,
            draftFile: donor?.draftFile ?? donor?.DraftFile ?? bulkRow.draftFile,
            draftFileName: donor?.draftFileName ?? donor?.DraftFileName ?? bulkRow.draftFileName,
            draft: donor?.draft ?? donor?.Draft ?? bulkRow.draft,
            proofSubmissionFile: donor?.proofSubmissionFile ?? donor?.ProofSubmissionFile ?? bulkRow.proofSubmissionFile ?? null,
            proofSubmissionFileName: donor?.proofSubmissionFileName ?? donor?.ProofSubmissionFileName ?? bulkRow.proofSubmissionFileName ?? null,
            sendForApproval: donor?.sendForApproval ?? donor?.SendForApproval ?? bulkRow.sendForApproval ?? '',
            SendForApproval: donor?.sendForApproval ?? donor?.SendForApproval ?? bulkRow.SendForApproval ?? '',
            approval: donor?.approval ?? donor?.Approval ?? bulkRow.approval ?? '',
            Approval: donor?.approval ?? donor?.Approval ?? bulkRow.Approval ?? '',
            status: donor?.status ?? donor?.Status ?? bulkRow.status ?? '',
            Status: donor?.status ?? donor?.Status ?? bulkRow.Status ?? '',
            remarks: donor?.remarks ?? donor?.Remarks ?? bulkRow.remarks ?? '',
            Remarks: donor?.remarks ?? donor?.Remarks ?? bulkRow.Remarks ?? '',
            submittedDate:
              resolveStatutorySubmittedDateStored(donor) ||
              resolveStatutorySubmittedDateStored(bulkRow) ||
              '',
            SubmittedDate:
              resolveStatutorySubmittedDateStored(donor) ||
              resolveStatutorySubmittedDateStored(bulkRow) ||
              '',
            modifiedTime: donor?.modifiedTime ?? donor?.MODIFIEDTIME ?? bulkRow.modifiedTime ?? bulkRow.MODIFIEDTIME ?? '',
            MODIFIEDTIME: donor?.modifiedTime ?? donor?.MODIFIEDTIME ?? bulkRow.modifiedTime ?? bulkRow.MODIFIEDTIME ?? '',
            approvedDate:
              donor?.approvedDate ??
              donor?.ApprovedDate ??
              donor?.approvalDate ??
              donor?.ApprovalDate ??
              bulkRow.approvedDate ??
              bulkRow.ApprovedDate ??
              bulkRow.approvalDate ??
              bulkRow.ApprovalDate ??
              '',
            ApprovedDate:
              donor?.approvedDate ??
              donor?.ApprovedDate ??
              donor?.approvalDate ??
              donor?.ApprovalDate ??
              bulkRow.approvedDate ??
              bulkRow.ApprovedDate ??
              bulkRow.approvalDate ??
              bulkRow.ApprovalDate ??
              '',
            // Preserve backend-saved month mapping so month filter shows the record only in its stored month.
            monthFilter: donor?.monthFilter ?? donor?.MonthFilter ?? donor?.monthfilter ?? bulkRow.monthFilter ?? null,
            MonthFilter: donor?.monthFilter ?? donor?.MonthFilter ?? donor?.monthfilter ?? bulkRow.MonthFilter ?? null,
            monthfilter: donor?.monthFilter ?? donor?.MonthFilter ?? donor?.monthfilter ?? bulkRow.monthfilter ?? null,
            draftStatutoryRowIdForFile: donor?.id ?? null
          };
        });
        console.log(
          `📌 Statutory aligned 1:1 with ChecklistBulk (${parsedBulkDataCache.length} master rows): ${beforeAlign} -> ${mergedData.length} displayed rows`
        );
      }

      // Filter by Site Management: Incharge email = login → Industry → act category (Factories / Shops / CLRA)
      if (siteScopeCategories == null) {
        siteScopeCategories = await siteScopePromise;
        setAllowedActCategoryList(siteScopeCategories);
      }
      if (siteScopeCategories && siteScopeCategories.length > 0 && mergedData.length > 0) {
        const allow = new Set(siteScopeCategories);
        const beforeFilter = mergedData.length;
        mergedData = mergedData.filter((item) => {
          const cat = getActCategoryWithFormFallback(item, mergedData);
          return allow.has(cat) || (cat === 'other' && hasComplianceFiles(item));
        });
        console.log(
          `🔍 Statutory filtered by Site Incharge industry scope [${siteScopeCategories.join(', ')}]: ${beforeFilter} -> ${mergedData.length}`
        );
      }

      // Deduplicate only when ChecklistBulk master data is not present.
      // When bulk exists, keep strict 1:1 count with ChecklistBulk rows.
      if (parsedBulkDataCache && parsedBulkDataCache.length > 0) {
        console.log(`⏭️ Skipping deduplication to preserve 1:1 ChecklistBulk row count (${mergedData.length} items)`);
      } else {
        console.log(`🔄 Before deduplication: ${mergedData.length} items`);
        mergedData = removeDuplicateStatutoryRecords(mergedData, resolveSiteDisplayName, selectedMonth);
        console.log(`🔄 After deduplication: ${mergedData.length} items`);
      }

      // Sort so rows with a form file appear first
      const hasFormFile = (item) => {
        const formFile = item?.formFile;
        return !!(formFile && formFile !== 'null' && String(formFile).trim() !== '');
      };
      const mergedWithOrder = mergedData.map((item, idx) => ({ ...item, __order: idx }));
      mergedWithOrder.sort((a, b) => {
        const aHas = hasFormFile(a);
        const bHas = hasFormFile(b);
        if (aHas !== bHas) return bHas - aHas; // true first
        return a.__order - b.__order; // keep stable order otherwise
      });
      mergedData = mergedWithOrder.map(({ __order, ...rest }) => rest);

      // Log Form U entries for debugging
      const formUEntries = mergedData.filter(item => {
        const formName = String(item.formName || '').toLowerCase();
        return formName.includes('form u') || formName === 'form u';
      });
      if (formUEntries.length > 0) {
        console.log(`📋 Found ${formUEntries.length} Form U entry/entries:`, formUEntries.map(item => ({
          id: item.id,
          formName: item.formName,
          act: item.act,
          formFile: item.formFile,
          formFileName: item.formFileName,
          formFileType: typeof item.formFile,
          formFileValue: String(item.formFile),
          hasFormFile: !!(item.formFile && item.formFile !== 'null' && String(item.formFile).trim() !== ''),
          willDisplay: !!(item.formFile && item.formFile !== 'null' && String(item.formFile).trim() !== '')
        })));
      } else {
        console.log('⚠️ No Form U entries found in statutory data');
        // Log all form names to help debug
        console.log('Available form names:', mergedData.map(item => item.formName || 'NO NAME').slice(0, 20));
      }
     
      // Log all forms with their file status
      console.log(`📊 Total statutory items before final processing: ${mergedData.length}`);
      console.log(`📊 Detailed statutory items:`, mergedData.map(item => ({
        id: item.id,
        formName: item.formName,
        hasFormFile: !!(item.formFile && item.formFile !== 'null' && String(item.formFile).trim() !== ''),
        formFileName: item.formFileName,
        formFile: item.formFile,
        isFromChecklist: item.isFromChecklist || false,
        checklistId: item.checklistId || null
      })));
     
      // Specifically check for Form I
      const formIEntries = mergedData.filter(item => {
        const formName = String(item.formName || '').toLowerCase().trim();
        return formName === 'form i';
      });
      if (formIEntries.length > 0) {
        console.log(`📋 Found ${formIEntries.length} Form I entry/entries:`, formIEntries.map(item => ({
          id: item.id,
          checklistId: item.checklistId,
          formName: item.formName,
          act: item.act,
          formFile: item.formFile,
          formFileName: item.formFileName,
          isFromChecklist: item.isFromChecklist || false,
          hasFormFile: !!(item.formFile && item.formFile !== 'null' && String(item.formFile).trim() !== '')
        })));
      } else {
        console.warn('⚠️ No Form I entries found in statutory data after all merges');
        console.log('Available form names:', mergedData.map(item => item.formName || 'NO NAME'));
      }
     
      // Final count summary
      console.log(`📊 FINAL COUNT: ${mergedData.length} total statutory entries will be displayed`);
      const byFormName = {};
      mergedData.forEach(item => {
        const name = String(item.formName || '').toLowerCase().trim();
        if (!byFormName[name]) byFormName[name] = 0;
        byFormName[name]++;
      });
      console.log(`📊 Entries by form name:`, byFormName);
     
      setStatutoryData((prev) => {
        const withPreservedSubmitted = preserveStatutorySubmittedDatesAfterFetch(prev, mergedData);
        const withPreservedDates = preserveStatutoryApprovedDatesAfterFetch(prev, withPreservedSubmitted);
        localStorage.setItem('statutoryData', JSON.stringify(withPreservedDates));
        return withPreservedDates;
      });
      setLastSyncedAt(new Date());
    } catch (err) {
      console.error('Error fetching statutory data:', err);
      if (silentRefresh) {
        return;
      }
      const localData = localStorage.getItem('statutoryData');
      if (localData) {
        try {
          const parsed = JSON.parse(localData);
          const sc = await fetchAllowedActCategoriesFromSites(userEmail);
          if (Array.isArray(parsed) && parsed.length > 0 && sc?.length) {
            const allow = new Set(sc);
            setStatutoryData(parsed.filter((item) => {
              const cat = getActCategoryWithFormFallback(item, parsed);
              return allow.has(cat) || (cat === 'other' && hasComplianceFiles(item));
            }));
          } else if (Array.isArray(parsed)) {
            setStatutoryData(parsed);
          } else {
            setStatutoryData([]);
          }
        } catch (_) {
          setStatutoryData([]);
        }
      } else {
        // When statutory API fails, still try to show ChecklistBulk data so page is not empty
        const applySiteScopeFilter = async (data) => {
          if (!data || data.length === 0) return data;
          const sc = await fetchAllowedActCategoriesFromSites(userEmail);
          if (!sc?.length) return data;
          const allow = new Set(sc);
          return data.filter((item) => {
            const cat = getActCategoryWithFormFallback(item, data);
            return allow.has(cat) || (cat === 'other' && hasComplianceFiles(item));
          });
        };
        try {
          const bulkResponse = await fetch('/server/checklistbulk_function/checklistbulk?action=getAll');
          if (bulkResponse.ok) {
            const bulkResult = await bulkResponse.json();
            if (bulkResult.status === 'success' && bulkResult.data && Array.isArray(bulkResult.data) && bulkResult.data.length > 0) {
              const merged = mergeBulkDataWithStatutory([], bulkResult.data);
              setStatutoryData(await applySiteScopeFilter(merged));
              localStorage.setItem('checklistBulkData', JSON.stringify(bulkResult.data));
              return;
            }
          }
        } catch (bulkErr) {
          console.error('Error fetching ChecklistBulk fallback:', bulkErr);
        }
        const fallbackBulk = localStorage.getItem('checklistBulkData');
        if (fallbackBulk) {
          try {
            const parsed = JSON.parse(fallbackBulk);
            if (Array.isArray(parsed) && parsed.length > 0) {
              const merged = mergeBulkDataWithStatutory([], parsed);
              setStatutoryData(await applySiteScopeFilter(merged));
              return;
            }
          } catch (_) {}
        }
        setError('Failed to fetch statutory data. Please try again.');
      }
    } finally {
      if (!silentRefresh) setLoading(false);
      isFetchingStatutoryRef.current = false;
      setTransactionSiteMetaReady(true);
    }
  };

  fetchStatutoryDataRef.current = fetchStatutoryData;

  const silentRefreshStatutoryTable = (options = {}) => {
    return fetchStatutoryData({ silentRefresh: true, force: true, ...options });
  };

  useEffect(() => {
    // On re-entering Statutory, show cached data immediately and refresh in background.
    fetchStatutoryData({ useCacheFirst: true, silentRefresh: true });
    prefetchStatutoryAutofillData();
  }, [userEmail]);

  // Live sync: poll + cross-tab signals (no full page reload). Works for admin + site on same or different tabs.
  useEffect(() => {
    const runSilentRefresh = (reason, { urgent = false } = {}) => {
      const now = Date.now();
      const minGap = urgent ? 0 : STATUTORY_LIVE_POLL_MS - 50;
      if (!urgent && now - lastStatutorySilentRefreshRef.current < minGap) return;
      lastStatutorySilentRefreshRef.current = now;
      console.log('📋 Statutory silent refresh:', reason);
      fetchStatutoryDataRef.current?.({ silentRefresh: true, force: true });
    };

    const handleStorageChange = (e) => {
      if (e.key === 'checklistBulkData' || e.key === STATUTORY_DATA_REVISION_KEY) {
        runSilentRefresh(`storage:${e.key}`, { urgent: true });
      }
    };

    window.addEventListener('storage', handleStorageChange);

    const handleBulkDataCleared = () => {
      runSilentRefresh('checklistBulkDataCleared', { urgent: true });
    };

    window.addEventListener('checklistBulkDataCleared', handleBulkDataCleared);

    const handleStatutoryDataUpdated = (e) => {
      runSilentRefresh(`statutoryDataUpdated:${e?.detail?.source || 'event'}`, { urgent: true });
    };

    window.addEventListener('statutoryDataUpdated', handleStatutoryDataUpdated);

    const handleBroadcastMessage = () => {
      runSilentRefresh('broadcastChannel', { urgent: true });
    };

    statutoryBroadcastChannel?.addEventListener('message', handleBroadcastMessage);

    const handleWindowFocus = () => {
      runSilentRefresh('window-focus', { urgent: true });
    };

    window.addEventListener('focus', handleWindowFocus);

    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        runSilentRefresh('visibility-visible', { urgent: true });
      }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);

    runSilentRefresh('mount', { urgent: true });
    const intervalId = window.setInterval(() => {
      runSilentRefresh('interval');
    }, STATUTORY_LIVE_POLL_MS);

    return () => {
      window.removeEventListener('storage', handleStorageChange);
      window.removeEventListener('checklistBulkDataCleared', handleBulkDataCleared);
      window.removeEventListener('statutoryDataUpdated', handleStatutoryDataUpdated);
      window.removeEventListener('focus', handleWindowFocus);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      statutoryBroadcastChannel?.removeEventListener('message', handleBroadcastMessage);
      window.clearInterval(intervalId);
    };
  }, []);

  const onChange = (e) => {
    const { name, value, files } = e.target;

    if (name === 'formFile' && files && files[0]) {
      const file = files[0];

      // Validate file size (max 5MB)
      if (file.size > 5 * 1024 * 1024) {
        setError('File size must be less than 5MB');
        return;
      }

      // Store the file and filename for upload
      setForm(prev => ({
        ...prev,
        [name]: file,
        formFileName: file.name
      }));
      setError('');
    } else if (name === 'proofSubmissionFile' && files && files[0]) {
      const file = files[0];

      // Validate file size (max 5MB)
      if (file.size > 5 * 1024 * 1024) {
        setError('File size must be less than 5MB');
        return;
      }
      if (!isProofSubmissionDocumentFileName(file.name)) {
        setError('Proof submission must be a PDF or image file.');
        return;
      }

      // Store the file and filename for upload
      setForm(prev => ({
        ...prev,
        [name]: file,
        proofSubmissionFileName: file.name
      }));
      setError('');
    } else if (name === 'draftFile' && files && files[0]) {
      const file = files[0];

      // Validate file size (max 5MB)
      if (file.size > 5 * 1024 * 1024) {
        setError('File size must be less than 5MB');
        return;
      }

      // Store the file and filename for upload
      setForm(prev => ({
        ...prev,
        [name]: file,
        draftFileName: file.name
      }));
      setError('');
    } else {
      setForm(prev => ({ ...prev, [name]: value }));
    }
    setError('');
    setSuccess('');
  };

  const onSubmit = async (e) => {
    e.preventDefault();

    // Prevent duplicate submissions
    if (submitting) {
      return;
    }

    // Validate required fields
    if (!form.formName.trim()) {
      setError('Form Name is required');
      return;
    }

    setSubmitting(true);

    try {
      setError('');
      setSuccess('');

      // Proof Submission is never filled from Draft; only from an uploaded PDF/image.

      // Upload files first if present
      let formFileId = null;
      let formFileName = null;

      // Check if formFile is a File object (new upload) or already a file ID (existing)
      const isNewFormFile = form.formFile instanceof File;

      // Upload form file if present and it's a new file
      if (isNewFormFile) {
        try {
          const formData = new FormData();
          formData.append('file', form.formFile);

          const uploadResp = await fetch('/server/statutoryreg_function/statutory/upload/Form', {
            method: 'POST',
            body: formData
          });

          let uploadData;
          const contentType = uploadResp.headers.get('content-type') || '';

          const responseClone = uploadResp.clone();

          if (contentType.includes('application/json')) {
            try {
              uploadData = await uploadResp.json();
            } catch (jsonErr) {
              const textResponse = await responseClone.text();
              console.error('Failed to parse JSON response:', textResponse);
              setError(`Form file upload failed: ${textResponse || 'Invalid server response'}`);
              setSubmitting(false);
              return;
            }
          } else {
            const textResponse = await uploadResp.text();
            console.error('Non-JSON response received:', textResponse);
            setError(`Form file upload failed: ${textResponse || 'Server error occurred'}`);
            setSubmitting(false);
            return;
          }

          if (uploadResp.ok && uploadData.status === 'success') {
            formFileId = uploadData.fileId;
            formFileName = uploadData.fileName || form.formFileName;
            console.log('Form file uploaded successfully:', formFileId);
          } else {
            const errorMessage = uploadData.message || 'Form file upload failed';
            console.error('Form file upload error:', errorMessage);
            setError(errorMessage);
            setSubmitting(false);
            return;
          }
        } catch (uploadErr) {
          console.error('Error uploading form file:', uploadErr);
          setError(`Form file upload failed: ${uploadErr.message}`);
          setSubmitting(false);
          return;
        }
      } else {
        // Use existing file ID
        formFileId = form.formFile;
        formFileName = form.formFileName;
      }

      // Upload proof submission file if present and it's a new file
      let proofSubmissionFileId = null;
      let proofSubmissionFileName = null;
      const isNewProofFile = form.proofSubmissionFile instanceof File;

      if (isNewProofFile) {
        if (!isProofSubmissionDocumentFileName(form.proofSubmissionFile?.name)) {
          setError('Proof submission must be a PDF or image file.');
          setSubmitting(false);
          return;
        }
        try {
          const proofFormData = new FormData();
          proofFormData.append('file', form.proofSubmissionFile);

          const proofUploadResp = await fetch('/server/statutoryreg_function/statutory/upload/ProofSubmission', {
            method: 'POST',
            body: proofFormData
          });

          let proofUploadData;
          const proofContentType = proofUploadResp.headers.get('content-type') || '';

          const proofResponseClone = proofUploadResp.clone();

          if (proofContentType.includes('application/json')) {
            try {
              proofUploadData = await proofUploadResp.json();
            } catch (jsonErr) {
              const textResponse = await proofResponseClone.text();
              console.error('Failed to parse JSON response:', textResponse);
              setError(`Proof submission file upload failed: ${textResponse || 'Invalid server response'}`);
              setSubmitting(false);
              return;
            }
          } else {
            const textResponse = await proofUploadResp.text();
            console.error('Non-JSON response received:', textResponse);
            setError(`Proof submission file upload failed: ${textResponse || 'Server error occurred'}`);
            setSubmitting(false);
            return;
          }

          if (proofUploadResp.ok && proofUploadData.status === 'success') {
            const uploadedProofId = proofUploadData.fileId ?? proofUploadData.data?.fileId ?? proofUploadData.data?.file_id;
            const uploadedProofName = proofUploadData.fileName ?? proofUploadData.data?.fileName ?? form.proofSubmissionFileName;
            if (uploadedProofId != null && String(uploadedProofId).trim() !== '') {
              proofSubmissionFileId = String(uploadedProofId).trim();
              proofSubmissionFileName = (uploadedProofName != null && String(uploadedProofName).trim() !== '') ? String(uploadedProofName).trim() : (form.proofSubmissionFileName || 'proof');
              console.log('Proof submission file uploaded successfully:', proofSubmissionFileId, proofSubmissionFileName);
            } else {
              console.error('Proof upload response missing fileId:', proofUploadData);
              setError('Proof submission upload succeeded but server did not return file ID.');
              setSubmitting(false);
              return;
            }
          } else {
            const errorMessage = proofUploadData.message || 'Proof submission file upload failed';
            console.error('Proof submission file upload error:', errorMessage);
            setError(errorMessage);
            setSubmitting(false);
            return;
          }
        } catch (uploadErr) {
          console.error('Error uploading proof submission file:', uploadErr);
          setError(`Proof submission file upload failed: ${uploadErr.message}`);
          setSubmitting(false);
          return;
        }
      } else {
        const existingProofId = form.proofSubmissionFile || null;
        const existingProofName = form.proofSubmissionFileName || null;
        const keepExisting =
          isProofSubmissionDocumentFileName(existingProofName) &&
          existingProofId != null &&
          String(existingProofId).trim() !== '' &&
          String(existingProofId).trim() !== 'null' &&
          String(existingProofId).trim() !== 'undefined';
        proofSubmissionFileId = keepExisting ? String(existingProofId).trim() : null;
        proofSubmissionFileName = keepExisting &&
          existingProofName != null &&
          String(existingProofName).trim() !== '' &&
          String(existingProofName).trim() !== 'null' &&
          String(existingProofName).trim() !== 'undefined'
          ? String(existingProofName).trim()
          : null;
      }

      // Upload draft file if present and it's a new file
      let draftFileId = null;
      let draftFileName = null;
      const isNewDraftFile = form.draftFile instanceof File;

      if (isNewDraftFile) {
        try {
          const draftFormData = new FormData();
          draftFormData.append('file', form.draftFile);

          const draftUploadResp = await fetch('/server/statutoryreg_function/statutory/upload/Draft', {
            method: 'POST',
            body: draftFormData
          });

          let draftUploadData;
          const draftContentType = draftUploadResp.headers.get('content-type') || '';

          const draftResponseClone = draftUploadResp.clone();

          if (draftContentType.includes('application/json')) {
            try {
              draftUploadData = await draftUploadResp.json();
            } catch (jsonErr) {
              const textResponse = await draftResponseClone.text();
              console.error('Failed to parse JSON response:', textResponse);
              setError(`Draft file upload failed: ${textResponse || 'Invalid server response'}`);
              setSubmitting(false);
              return;
            }
          } else {
            const textResponse = await draftUploadResp.text();
            console.error('Non-JSON response received:', textResponse);
            setError(`Draft file upload failed: ${textResponse || 'Server error occurred'}`);
            setSubmitting(false);
            return;
          }

          if (draftUploadResp.ok && draftUploadData.status === 'success') {
            draftFileId = draftUploadData.fileId;
            draftFileName = draftUploadData.fileName || form.draftFileName;
            console.log('Draft file uploaded successfully:', draftFileId);
          } else {
            const errorMessage = draftUploadData.message || 'Draft file upload failed';
            console.error('Draft file upload error:', errorMessage);
            setError(errorMessage);
            setSubmitting(false);
            return;
          }
        } catch (uploadErr) {
          console.error('Error uploading draft file:', uploadErr);
          setError(`Draft file upload failed: ${uploadErr.message}`);
          setSubmitting(false);
          return;
        }
      } else {
        // Use existing file ID
        draftFileId = form.draftFile;
        draftFileName = form.draftFileName;
      }

      // Prepare the payload (month filter saved so it displays in backend – e.g. Proof Submission save)
      const monthFilterValue = resolveMonthFilterForSave(form.dueDate, selectedMonth, form.originalMonthFilter);
      const proofFileForPayload = (proofSubmissionFileId != null && String(proofSubmissionFileId).trim() !== '' && String(proofSubmissionFileId).trim() !== 'null' && String(proofSubmissionFileId).trim() !== 'undefined') ? String(proofSubmissionFileId).trim() : null;
      const proofNameForPayload = (proofSubmissionFileName != null && String(proofSubmissionFileName).trim() !== '' && String(proofSubmissionFileName).trim() !== 'null' && String(proofSubmissionFileName).trim() !== 'undefined') ? String(proofSubmissionFileName).trim() : null;
      const payload = {
        act: form.act || null,
        description: form.description || null,
        sector: form.sector || null,
        state: form.state || null,
        site: form.site || siteFromUrl || null,
        formFile: formFileId != null ? String(formFileId) : null,
        formFileName: formFileName || null,
        formName: form.formName.trim(),
        dueDate: form.dueDate || null,
        monthFilter: monthFilterValue,
        MonthFilter: monthFilterValue,
        monthfilter: monthFilterValue,
        autofill: form.autofill || null,
        draft: form.draft || null,
        proofSubmissionFile: proofFileForPayload,
        proofSubmissionFileName: proofNameForPayload,
        draftFile: draftFileId != null ? String(draftFileId) : null,
        draftFileName: draftFileName || null,
        approval: form.approval != null && String(form.approval).trim() !== '' ? String(form.approval).trim() : null,
        status: form.status != null && String(form.status).trim() !== '' ? String(form.status).trim() : null,
        sendForApproval:
          form.sendForApproval != null && String(form.sendForApproval).trim() !== ''
            ? String(form.sendForApproval).trim()
            : null,
        remarks: form.remarks != null && String(form.remarks).trim() !== '' ? String(form.remarks).trim() : null
      };

      const existingMonthNorm = (form.originalMonthFilter || '').trim().toLowerCase().substring(0, 3);
      const savingMonthNorm = (monthFilterValue || '').trim().toLowerCase().substring(0, 3);
      const sameMonth = existingMonthNorm && savingMonthNorm && existingMonthNorm === savingMonthNorm;
      const createNewForMonth = editingStatutoryId && !sameMonth;
      const isPlaceholderEdit = editingStatutoryId && String(editingStatutoryId).startsWith('placeholder_');

      let response;
      if (editingStatutoryId && sameMonth && !isPlaceholderEdit) {
        response = await fetch(`/server/statutoryreg_function/statutory/${editingStatutoryId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
      } else if (createNewForMonth || isPlaceholderEdit) {
        response = await fetch('/server/statutoryreg_function/statutory', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
      } else {
        response = await fetch('/server/statutoryreg_function/statutory', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
      }

      const data = await response.json();
      const didUpdate = editingStatutoryId && sameMonth && !isPlaceholderEdit;

      if (response.ok && data.status === 'success') {
        setSuccess(didUpdate ? 'Statutory updated successfully!' : 'Statutory created successfully!');
        setForm(initialForm);
        setEditingStatutoryId(null);
        setIsFormOpen(false);
        if (monthFilterValue) {
          const savedMonth = resolveToFullMonthName(monthFilterValue) || monthFilterValue;
          setSelectedMonth(savedMonth);
          persistMonthFilter(savedMonth);
        }
        // When a new file was imported, clear old ChecklistBulk data automatically (like checklistbulk clear)
        if (isNewFormFile) {
          try {
            const bulkDeleteResp = await fetch('/server/checklistbulk_function/checklistbulk?action=bulkDelete', { method: 'DELETE' });
            const bulkDeleteData = await bulkDeleteResp.json().catch(() => ({}));
            if (bulkDeleteResp.ok && (bulkDeleteData.status === 'success' || bulkDeleteData.status === 'partial')) {
              localStorage.removeItem('checklistBulkData');
              window.dispatchEvent(new Event('checklistBulkDataCleared'));
            }
          } catch (bulkErr) {
            console.warn('Could not clear ChecklistBulk after import:', bulkErr);
          }
        }
        fetchStatutoryData();
        setTimeout(() => setSuccess(''), 3000);
      } else {
        const errorMessage = data.message || (didUpdate ? 'Failed to update statutory' : 'Failed to create statutory');
        setError(errorMessage);
      }
    } catch (err) {
      console.error('Error submitting statutory:', err);
      setError(`Failed to ${editingStatutoryId ? 'update' : 'create'} statutory: ${err.message}`);
    } finally {
      setSubmitting(false);
    }
  };

  const onReset = () => {
    setForm(initialForm);
    setEditingStatutoryId(null);
    setError('');
    setSuccess('');
  };

  const handleClose = () => {
    setIsFormOpen(false);
    setForm(initialForm);
    setEditingStatutoryId(null);
    setSubmitting(false);
    setError('');
    setSuccess('');
    // Optionally clear selected rows when closing form
    // setSelectedRows(new Set());
  };

  const handleEditStatutory = (statutoryId, rowItem) => {
    const statutoryItem = statutoryData.find(r => r.id === statutoryId);
    const source = statutoryItem || rowItem;
    if (source) {
      if (isRowStatusApproved(source)) {
        setError('Approved rows are locked and cannot be edited.');
        setTimeout(() => setError(''), 5000);
        return;
      }
      const rowMonth = source.monthFilter || source.MonthFilter || source.monthfilter || '';
      const rawProofId = source.proofSubmissionFile ?? source.ProofSubmissionFile ?? null;
      const rawProofName = source.proofSubmissionFileName ?? source.ProofSubmissionFileName ?? null;
      const proofOk = isProofSubmissionDocumentFileName(rawProofName);
      setForm({
        act: source.act || '',
        description: source.description || '',
        sector: source.sector || '',
        state: source.state || '',
        site: source.site || source.Site || source.siteName || source.SiteName || '',
        formFile: source.formFile ?? source.FormFile ?? null,
        formFileName: source.formFileName ?? source.FormFileName ?? null,
        formName: source.formName ?? source.FormName ?? '',
        dueDate: source.dueDate || '',
        autofill: source.autofill || '',
        draft: source.draft || '',
        proofSubmissionFile: proofOk ? rawProofId : null,
        proofSubmissionFileName: proofOk ? rawProofName : null,
        draftFile: source.draftFile ?? source.DraftFile ?? null,
        draftFileName: source.draftFileName ?? source.DraftFileName ?? null,
        approval: source.approval ?? source.Approval ?? '',
        status: source.status != null && source.status !== '' ? source.status : source.Status != null ? source.Status : '',
        sendForApproval: source.sendForApproval ?? source.SendForApproval ?? '',
        remarks: source.remarks ?? source.Remarks ?? '',
        originalMonthFilter: rowMonth || null
      });
      setEditingStatutoryId(source.id);
      setIsFormOpen(true);
    }
  };

  const handleDeleteStatutory = async (statutoryId) => {
    if (!window.confirm('Are you sure you want to delete this statutory record?')) {
      return;
    }

    try {
      setLoading(true);
      const response = await fetch(`/server/statutoryreg_function/statutory/${statutoryId}`, {
        method: 'DELETE'
      });

      const data = await response.json();

      if (response.ok && data.status === 'success') {
        setSuccess('Statutory deleted successfully!');
        // Remove from selected rows if it was selected
        setSelectedRows(prev => {
          const newSet = new Set(prev);
          newSet.delete(statutoryId);
          return newSet;
        });
        fetchStatutoryData();
        setTimeout(() => setSuccess(''), 3000);
      } else {
        setError(data.message || 'Failed to delete statutory');
      }
    } catch (err) {
      console.error('Error deleting statutory:', err);
      setError(`Failed to delete statutory: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleCheckboxChange = (statutoryId) => {
    setSelectedRows(prev => {
      const newSet = new Set(prev);
      if (newSet.has(statutoryId)) {
        newSet.delete(statutoryId);
      } else {
        newSet.add(statutoryId);
      }
      return newSet;
    });
  };

  const proofRowDedupKey = (row) => {
    const form = statutoryFormDedupeKey(row);
    const act = (row.act || row.Act || '').trim().toLowerCase();
    const desc = (row.description || row.Description || '').trim().toLowerCase();
    const sector = String(row.sector || row.Sector || '').trim().toLowerCase();
    const monthNorm = (
      row.monthFilter ||
      row.MonthFilter ||
      row.monthfilter ||
      getMonthFromDueDate(row.dueDate) ||
      selectedMonth ||
      ''
    )
      .toString()
      .trim()
      .toLowerCase()
      .substring(0, 3) || 'nomonth';
    const state = String(row.state || row.State || '').trim().toLowerCase();
    return `${form}_${act}_${desc}_${monthNorm}_${sector || 'nosector'}_${state || 'nostate'}`;
  };

  const resolveNumericStatutoryIdForProofRow = (item, options = {}) => {
    const preferSiteSubmittedDraft = options?.preferSiteSubmittedDraft === true;
    if (preferSiteSubmittedDraft && item) {
      const approverDonor = findStatutoryDraftDonorForApproverView(
        item,
        statutoryData || [],
        resolveSiteDisplayName,
        null
      );
      if (approverDonor?.id) return String(approverDonor.id);
      const linkedId = item?.draftStatutoryRowIdForFile;
      if (/^\d+$/.test(String(linkedId ?? ''))) return String(linkedId);
    }
    if (/^\d+$/.test(String(item.id ?? ''))) {
      if (preferSiteSubmittedDraft) {
        const approverDonor = findStatutoryDraftDonorForApproverView(
          item,
          statutoryData || [],
          resolveSiteDisplayName,
          null
        );
        if (approverDonor && String(approverDonor.id) !== String(item.id)) {
          return String(approverDonor.id);
        }
      }
      return String(item.id);
    }
    const hintedId = /^\d+$/.test(String(item?.draftStatutoryRowIdForFile ?? ''))
      ? String(item.draftStatutoryRowIdForFile)
      : null;
    const hintedRow = hintedId
      ? ((statutoryData || []).find((r) => String(r?.id ?? '') === hintedId) || null)
      : null;
    const key = proofRowDedupKey(item);
    if (!key || key.startsWith('_')) return null;
    const match = (statutoryData || [])
      .filter((r) => /^\d+$/.test(String(r.id)) && proofRowDedupKey(r) === key)
      .reduce((best, row) => (isPreferredStatutoryRow(row, best) ? row : best), null);
    if (match && hintedRow) {
      return String((isPreferredStatutoryRow(match, hintedRow) ? match : hintedRow).id);
    }
    if (match) return String(match.id);
    if (hintedRow) return String(hintedRow.id);

    // Fallback: strict key can fail when description/act text differs between bulk placeholder and saved statutory row.
    // Match by base form + month + sector/state and prefer rows that already have saved files.
    const monthNorm = String(
      item?.monthFilter ||
      item?.MonthFilter ||
      item?.monthfilter ||
      getMonthFromDueDate(item?.dueDate) ||
      selectedMonth ||
      ''
    )
      .trim()
      .toLowerCase()
      .substring(0, 3);
    const formNorm = baseFormNameKey(item?.formName || item?.FormName);
    const sectorNorm = String(item?.sector || item?.Sector || '').trim().toLowerCase();
    const stateNorm = String(item?.state || item?.State || '').trim().toLowerCase();
    const candidates = (statutoryData || []).filter((r) => {
      if (!/^\d+$/.test(String(r?.id ?? ''))) return false;
      const rMonthNorm = String(
        r?.monthFilter ||
        r?.MonthFilter ||
        r?.monthfilter ||
        getMonthFromDueDate(r?.dueDate) ||
        selectedMonth ||
        ''
      )
        .trim()
        .toLowerCase()
        .substring(0, 3);
      if (monthNorm && !statutoryMonthMatchesUiFilter(r, monthNorm, selectedMonth)) return false;
      if (baseFormNameKey(r?.formName || r?.FormName) !== formNorm) return false;
      return statutoryLineMetadataMatches(item, r);
    });
    if (candidates.length === 0) return null;
    const bestCandidate = candidates.reduce((best, row) => (isPreferredStatutoryRow(row, best) ? row : best), hintedRow);
    return bestCandidate ? String(bestCandidate.id) : null;
  };

  const resolveStatutorySampleDataFetchId = (item, options = {}) =>
    resolveNumericStatutoryIdForProofRow(item, options) ||
    resolveStatutorySampleDataSaveId(item) ||
    '';

  const buildStatutorySampleDataFetchContext = (primaryItem, resolvedItem, extra = {}) => {
    const item = primaryItem || resolvedItem || {};
    const formNameValue = resolveStatutoryFormNameForDatastore(item, {
      resolvedItem,
      formHeader,
      formFileModalData,
      autofillItem
    });
    const monthFilterValue = resolveMonthFilterForSave(
      item?.dueDate,
      selectedMonth,
      item?.monthFilter ?? item?.MonthFilter ?? item?.monthfilter
    );
    const employees = resolveStatutoryEmployeesForSaveOrder(extra.employees || autofillEmployeesRef.current);
    const rowCount = Number(extra.rowCount) || 0;
    const statutoryDataEmployeeOrder =
      Array.isArray(extra.statutoryDataEmployeeOrder) && extra.statutoryDataEmployeeOrder.length > 0
        ? extra.statutoryDataEmployeeOrder
        : buildStatutoryDataEmployeeOrder(employees, rowCount);
    return {
      formName: formNameValue,
      FormName: formNameValue,
      monthFilter: monthFilterValue,
      MonthFilter: monthFilterValue,
      monthfilter: monthFilterValue,
      employees,
      ...(statutoryDataEmployeeOrder.length > 0 ? { statutoryDataEmployeeOrder } : {}),
      ...(Number(extra.rowIndexOffset) ? { rowIndexOffset: Number(extra.rowIndexOffset) } : {})
    };
  };

  const buildStatutorySampleDataFetchIds = (primaryItem, resolvedItem, options = {}) => {
    const draftIdOpts =
      options.draftIdOpts ||
      (showApprovalColumn ? { preferSiteSubmittedDraft: true } : {});
    const formNorm = baseFormNameKey(
      primaryItem?.formName ||
        primaryItem?.FormName ||
        resolvedItem?.formName ||
        resolvedItem?.FormName ||
        ''
    );
    const uiMonthNorm = statutoryDedupeMonthNorm(primaryItem || resolvedItem, selectedMonth);
    const matchingStatutoryRowIds = (statutoryData || [])
      .filter((row) => {
        if (!/^\d+$/.test(String(row?.id ?? ''))) return false;
        if (formNorm && baseFormNameKey(row?.formName || row?.FormName) !== formNorm) return false;
        if (
          uiMonthNorm !== 'nomonth' &&
          !statutoryMonthMatchesUiFilter(row, uiMonthNorm, selectedMonth)
        ) {
          return false;
        }
        return statutoryLineMetadataMatches(primaryItem || resolvedItem, row);
      })
      .map((row) => String(row.id));
    return uniqueNumericStatutoryIds(
      options.sampleStatutoryId,
      options.draftApiRowId,
      primaryItem?.draftStatutoryRowIdForFile,
      resolvedItem?.draftStatutoryRowIdForFile,
      resolveStatutorySampleDataSaveId(primaryItem),
      resolveStatutorySampleDataSaveId(resolvedItem),
      resolveStatutorySampleDataFetchId(primaryItem, draftIdOpts),
      resolveStatutorySampleDataFetchId(resolvedItem, draftIdOpts),
      ...matchingStatutoryRowIds,
      primaryItem?.id,
      resolvedItem?.id
    );
  };

  /** Approval / status / draft for the UI month only — never reuse another month's statutory row. */
  const resolveStatutoryRowMetaForSelectedMonth = (item) => {
    const emptyMeta = {
      approval: '',
      Approval: '',
      status: '',
      Status: '',
      remarks: '',
      Remarks: '',
      sendForApproval: '',
      SendForApproval: '',
      draftFile: null,
      DraftFile: null,
      draftFileName: null,
      DraftFileName: null,
      draft: '',
      Draft: '',
      submittedDate: '',
      SubmittedDate: '',
      approvedDate: '',
      ApprovedDate: ''
    };
    if (!item) return emptyMeta;

    const uiMonthNorm = statutoryDedupeMonthNorm(
      { monthFilter: selectedMonth, MonthFilter: selectedMonth },
      selectedMonth
    );
    const pickMeta = (row) => ({
      approval: row?.approval ?? row?.Approval ?? '',
      Approval: row?.approval ?? row?.Approval ?? '',
      status: row?.status ?? row?.Status ?? '',
      Status: row?.status ?? row?.Status ?? '',
      remarks: row?.remarks ?? row?.Remarks ?? '',
      Remarks: row?.remarks ?? row?.Remarks ?? '',
      sendForApproval: row?.sendForApproval ?? row?.SendForApproval ?? '',
      SendForApproval: row?.sendForApproval ?? row?.SendForApproval ?? '',
      draftFile: row?.draftFile ?? row?.DraftFile ?? null,
      DraftFile: row?.draftFile ?? row?.DraftFile ?? null,
      draftFileName: row?.draftFileName ?? row?.DraftFileName ?? null,
      DraftFileName: row?.draftFileName ?? row?.DraftFileName ?? null,
      draft: row?.draft ?? row?.Draft ?? '',
      Draft: row?.draft ?? row?.Draft ?? '',
      submittedDate: resolveStatutorySubmittedDateStored(row),
      SubmittedDate: resolveStatutorySubmittedDateStored(row),
      approvedDate:
        row?.approvedDate ?? row?.ApprovedDate ?? row?.approvalDate ?? row?.ApprovalDate ?? '',
      ApprovedDate:
        row?.approvedDate ?? row?.ApprovedDate ?? row?.approvalDate ?? row?.ApprovalDate ?? '',
      modifiedTime: row?.modifiedTime ?? row?.MODIFIEDTIME ?? '',
      MODIFIEDTIME: row?.modifiedTime ?? row?.MODIFIEDTIME ?? ''
    });

    const rowMonthNorm = statutoryDedupeMonthNorm(item, selectedMonth);
    if (/^\d+$/.test(String(item?.id ?? '')) && uiMonthNorm !== 'nomonth' && rowMonthNorm === uiMonthNorm) {
      return pickMeta(item);
    }
    if (uiMonthNorm !== 'nomonth' && rowMonthNorm === uiMonthNorm) {
      const hasWorkflow =
        (item?.draftFile ?? item?.DraftFile) ||
        String(item?.approval ?? item?.Approval ?? '').trim() ||
        String(item?.status ?? item?.Status ?? '').trim() ||
        String(item?.sendForApproval ?? item?.SendForApproval ?? '').trim();
      if (hasWorkflow) return pickMeta(item);
    }

    const formNorm = baseFormNameKey(item?.formName || item?.FormName);
    const sectorNorm = String(item?.sector || item?.Sector || '').trim().toLowerCase();
    const stateNorm = String(item?.state || item?.State || '').trim().toLowerCase();
    const actNorm = String(item?.act || item?.Act || '').trim().toLowerCase();
    const descNorm = String(item?.description || item?.Description || '').trim().toLowerCase();
    const candidates = (statutoryData || []).filter((row) => {
      if (!/^\d+$/.test(String(row?.id ?? ''))) return false;
      if (uiMonthNorm !== 'nomonth' && !statutoryMonthMatchesUiFilter(row, uiMonthNorm, selectedMonth)) {
        return false;
      }
      if (baseFormNameKey(row?.formName || row?.FormName) !== formNorm) return false;
      return statutoryLineMetadataMatches(item, row);
    });
    if (candidates.length > 0) {
      const approvedCandidates = candidates.filter((row) => {
        const aNorm = String(row?.approval ?? row?.Approval ?? row?.status ?? row?.Status ?? '')
          .trim()
          .toLowerCase();
        return aNorm === 'approved' || aNorm === 'approve';
      });
      if (approvedCandidates.length > 0) {
        const bestApproved = [...approvedCandidates].sort(
          (a, b) => statutoryRowRichnessScore(b) - statutoryRowRichnessScore(a)
        )[0];
        return pickMeta(bestApproved);
      }
      const approverDonor = findStatutoryDraftDonorForApproverView(
        item,
        statutoryData,
        resolveSiteDisplayName,
        pickMeta(item)
      );
      if (approverDonor) return pickMeta(approverDonor);
      const best = [...candidates].sort((a, b) => {
        const sentDiff =
          (statutorySendForApprovalIsSent(b) ? 1 : 0) - (statutorySendForApprovalIsSent(a) ? 1 : 0);
        if (sentDiff !== 0) return sentDiff;
        return statutoryRowRichnessScore(b) - statutoryRowRichnessScore(a);
      })[0];
      return pickMeta(best);
    }

    return emptyMeta;
  };

  const buildMonthFilterPayload = (item) => {
    const monthValue = resolveMonthFilterForSave(
      item?.dueDate,
      selectedMonth,
      item?.monthFilter || item?.MonthFilter || item?.monthfilter
    );
    return {
      monthFilter: monthValue,
      MonthFilter: monthValue,
      monthfilter: monthValue
    };
  };

  /** Site/act/form context for approval + Returned table sync (UI site may not be on DB row yet). */
  const buildStatutoryRowSyncPayload = (item) => {
    const resolvedSite = String(
      (typeof resolveSiteDisplayName === 'function'
        ? resolveSiteDisplayName(item, statutoryData)
        : '') ||
        item?.site ||
        item?.Site ||
        item?.siteName ||
        item?.SiteName ||
        siteFromUrl ||
        ''
    ).trim();
    const payload = {
      ...buildMonthFilterPayload(item),
      act: item?.act || item?.Act || null,
      description: item?.description || item?.Description || null,
      formName: item?.formName || item?.FormName || null,
      dueDate: item?.dueDate || item?.DueDate || null
    };
    if (resolvedSite) payload.site = resolvedSite;
    return payload;
  };

  const submitApprovalColumnAction = async (rowItem, decision, rejectRemarks, explicitTargetId = null) => {
    const targetId =
      (explicitTargetId != null && String(explicitTargetId).trim() !== '' ? String(explicitTargetId).trim() : null) ||
      resolveNumericStatutoryIdForProofRow(rowItem);
    if (!targetId) return false;
    const decisionNorm = String(decision || '').trim().toLowerCase();
    const isApproveDecision = decisionNorm === 'approved' || decisionNorm === 'approve';
    const isRejectDecision = decisionNorm === 'rejected' || decisionNorm === 'reject';
    setError('');
    setSuccess('');
    setApprovalUpdatingRowId(targetId);
    const payloadApproval = decision == null || decision === '' ? null : decision;
    const payloadStatus = isApproveDecision ? 'Approved' : isRejectDecision ? 'Rejected' : undefined;
    const approveDateIso = isApproveDecision ? todayStatutoryIsoDate() : '';
    const approvePreserveKey = statutorySubmittedDatePreserveKey(rowItem);
    if (isApproveDecision && approvePreserveKey) {
      setSiteApprovedDates((prev) => ({ ...prev, [approvePreserveKey]: approveDateIso }));
    }
    try {
      const resp = await fetch(`/server/statutoryreg_function/statutory/${targetId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...buildStatutoryRowSyncPayload(rowItem),
          approval: payloadApproval,
          ...(payloadStatus ? { status: payloadStatus } : {}),
          ...(isApproveDecision ? { approvedDate: approveDateIso } : {}),
          ...(isRejectDecision ? { remarks: rejectRemarks } : {}),
          ...(isApproveDecision ? { remarks: null } : {})
        })
      });
      const data = await resp.json().catch(() => ({}));
      if (!resp.ok || data.status !== 'success') {
        if (isApproveDecision && approvePreserveKey) {
          setSiteApprovedDates((prev) => {
            const next = { ...prev };
            delete next[approvePreserveKey];
            return next;
          });
        }
        setError(data.message || 'Failed to update approval.');
        setTimeout(() => setError(''), 5000);
        return false;
      }
      if (isApproveDecision) {
        setStatutoryData((prev) =>
          (prev || []).map((row) => {
            const sameNumeric = String(row?.id ?? '') === String(targetId);
            const sameLine =
              approvePreserveKey &&
              statutorySubmittedDatePreserveKey(row) === approvePreserveKey;
            if (!sameNumeric && !sameLine) return row;
            return {
              ...row,
              approval: payloadApproval,
              Approval: payloadApproval,
              status: payloadStatus,
              Status: payloadStatus,
              approvedDate: approveDateIso,
              ApprovedDate: approveDateIso
            };
          })
        );
      } else if (isRejectDecision) {
        if (approvePreserveKey) {
          setSiteApprovedDates((prev) => {
            const next = { ...prev };
            delete next[approvePreserveKey];
            return next;
          });
        }
      }
      setSuccess(payloadApproval == null ? 'Approval cleared.' : `Approval: ${payloadApproval}.`);
      broadcastStatutoryDataChange({ id: targetId, source: 'approval' });
      silentRefreshStatutoryTable();
      setTimeout(() => setSuccess(''), 2500);
      return true;
    } catch (err) {
      if (isApproveDecision && approvePreserveKey) {
        setSiteApprovedDates((prev) => {
          const next = { ...prev };
          delete next[approvePreserveKey];
          return next;
        });
      }
      setError(err?.message || 'Failed to update approval.');
      setTimeout(() => setError(''), 5000);
      return false;
    } finally {
      setApprovalUpdatingRowId(null);
    }
  };

  const closeRejectRemarksModal = () => {
    setIsRejectRemarksModalOpen(false);
    setRejectRemarksValue('');
    setRejectRemarksTarget(null);
  };

  const submitRejectRemarks = async () => {
    if (!rejectRemarksTarget?.rowItem || !rejectRemarksTarget?.decision) return;
    const trimmedRemarks = String(rejectRemarksValue || '').trim();
    if (!trimmedRemarks) {
      setError('Remarks are required when rejecting.');
      setTimeout(() => setError(''), 5000);
      return;
    }
    const ok = await submitApprovalColumnAction(
      rejectRemarksTarget.rowItem,
      rejectRemarksTarget.decision,
      trimmedRemarks,
      rejectRemarksTarget.targetId
    );
    if (ok) closeRejectRemarksModal();
  };

  const handleApprovalColumnAction = async (rowItem, decision, explicitTargetId = null) => {
    const targetId =
      (explicitTargetId != null && String(explicitTargetId).trim() !== '' ? String(explicitTargetId).trim() : null) ||
      resolveNumericStatutoryIdForProofRow(rowItem);
    if (!targetId) {
      setError('Approval can only be set for saved statutory table rows.');
      setTimeout(() => setError(''), 5000);
      return;
    }
    const decisionNorm = String(decision || '').trim().toLowerCase();
    const isRejectDecision = decisionNorm === 'rejected' || decisionNorm === 'reject';
    if (isRejectDecision) {
      setRejectRemarksTarget({ rowItem, decision, targetId });
      const monthRemarks = resolveStatutoryRowMetaForSelectedMonth(rowItem);
      setRejectRemarksValue(String(monthRemarks?.remarks ?? monthRemarks?.Remarks ?? ''));
      setIsRejectRemarksModalOpen(true);
      return;
    }
    await submitApprovalColumnAction(rowItem, decision, undefined, targetId);
  };

  const handleSendForApprovalColumnAction = async (rowItem, explicitTargetId = null) => {
    const targetId =
      (explicitTargetId != null && String(explicitTargetId).trim() !== '' ? String(explicitTargetId).trim() : null) ||
      resolveNumericStatutoryIdForProofRow(rowItem);
    if (!targetId) {
      setError('Send for approval is only available for saved statutory table rows.');
      setTimeout(() => setError(''), 5000);
      return;
    }
    setError('');
    setSuccess('');
    setSendForApprovalUpdatingRowId(targetId);
    const submitDateIso = todayStatutoryIsoDate();
    const submitDateKey = statutorySubmittedDatePreserveKey(rowItem);
    if (submitDateKey) {
      setSiteSentSubmittedDates((prev) => ({ ...prev, [submitDateKey]: submitDateIso }));
    }
    try {
      const resp = await fetch(`/server/statutoryreg_function/statutory/${targetId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...buildMonthFilterPayload(rowItem),
          SendForApproval: 'Sent',
          sendForApproval: 'Sent',
          submittedDate: submitDateIso,
          // Re-send flow: clear prior approver decision so site sees "Sent" after re-submit.
          approval: null,
          status: 'Pending',
          remarks: null
        })
      });
      const data = await resp.json().catch(() => ({}));
      if (!resp.ok || data.status !== 'success') {
        if (submitDateKey) {
          setSiteSentSubmittedDates((prev) => {
            const next = { ...prev };
            delete next[submitDateKey];
            return next;
          });
        }
        setError(data.message || 'Failed to update send for approval.');
        setTimeout(() => setError(''), 5000);
        return;
      }
      // Optimistic local update so UI reflects Sent even if another fetch is currently running.
      setStatutoryData((prev) =>
        Array.isArray(prev)
          ? (() => {
              const baseForm = baseFormNameKey(rowItem?.formName || rowItem?.FormName);
              const siteNorm = String(
                resolveSiteDisplayName(rowItem, prev) || rowItem?.site || rowItem?.Site || ''
              )
                .trim()
                .toLowerCase();
              const clickedRowId = String(rowItem?.id ?? '');
              const clickedIdentityKey = checklistBulkRowIdentityKey(rowItem);
              return prev.map((row) => {
                const sameId = String(row?.id ?? '') === String(targetId);
                const sameClickedRow = clickedRowId && String(row?.id ?? '') === clickedRowId;
                const sameIdentity =
                  clickedIdentityKey && checklistBulkRowIdentityKey(row) === clickedIdentityKey;
                const sameBaseForm = baseFormNameKey(row?.formName || row?.FormName) === baseForm;
                const rowSiteNorm = String(
                  resolveSiteDisplayName(row, prev) || row?.site || row?.Site || ''
                )
                  .trim()
                  .toLowerCase();
                // Site-view fallback: when visible row is bulk/checklist sibling, mirror Sent to same form in same site.
                const sameSiteFormSibling =
                  !!siteNorm && sameBaseForm && resolvedSitesOverlap(siteNorm, rowSiteNorm);
                if (!sameId && !sameSiteFormSibling && !sameClickedRow && !sameIdentity) return row;
                const targetRow = sameId ? row : prev.find((r) => String(r?.id ?? '') === String(targetId));
                const syncDraftFile = targetRow?.draftFile ?? targetRow?.DraftFile ?? null;
                const syncDraftFileName = targetRow?.draftFileName ?? targetRow?.DraftFileName ?? null;
                return {
                  ...row,
                  sendForApproval: 'Sent',
                  SendForApproval: 'Sent',
                  submittedDate: submitDateIso,
                  SubmittedDate: submitDateIso,
                  modifiedTime: submitDateIso,
                  MODIFIEDTIME: submitDateIso,
                  approval: '',
                  Approval: '',
                  status: 'Pending',
                  Status: 'Pending',
                  remarks: '',
                  Remarks: '',
                  ...(syncDraftFile
                    ? {
                        draftFile: syncDraftFile,
                        DraftFile: syncDraftFile,
                        draftFileName: syncDraftFileName,
                        DraftFileName: syncDraftFileName,
                        draft: targetRow?.draft ?? targetRow?.Draft ?? row.draft ?? 'Draft',
                        Draft: targetRow?.draft ?? targetRow?.Draft ?? row.Draft ?? 'Draft',
                        draftStatutoryRowIdForFile: targetId
                      }
                    : { draftStatutoryRowIdForFile: targetId })
                };
              });
            })()
          : prev
      );
      setSuccess('Marked as sent for approval.');
      broadcastStatutoryDataChange({ id: targetId, source: 'sendForApproval' });
      silentRefreshStatutoryTable();
      setTimeout(() => setSuccess(''), 2500);
    } catch (err) {
      if (submitDateKey) {
        setSiteSentSubmittedDates((prev) => {
          const next = { ...prev };
          delete next[submitDateKey];
          return next;
        });
      }
      setError(err?.message || 'Failed to update send for approval.');
      setTimeout(() => setError(''), 5000);
    } finally {
      setSendForApprovalUpdatingRowId(null);
    }
  };

  const handleInlineProofUpload = async (rowItem, file) => {
    if (!file || rowItem == null) return;
    const formNameTrim = (rowItem.formName || rowItem.FormName || '').trim();
    if (!formNameTrim) {
      setError('Form name is missing; cannot save proof for this row.');
      setTimeout(() => setError(''), 5000);
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      setError('Proof file size must be less than 5MB');
      setTimeout(() => setError(''), 5000);
      return;
    }
    if (!isProofSubmissionDocumentFileName(file.name)) {
      setError('Proof submission must be a PDF or image file.');
      setTimeout(() => setError(''), 5000);
      return;
    }
    setError('');
    setProofUploadingRowId(String(rowItem.id ?? ''));
    try {
      const proofFormData = new FormData();
      proofFormData.append('file', file);

      const proofUploadResp = await fetch('/server/statutoryreg_function/statutory/upload/ProofSubmission', {
        method: 'POST',
        body: proofFormData
      });

      const proofContentType = proofUploadResp.headers.get('content-type') || '';
      let proofUploadData;
      if (proofContentType.includes('application/json')) {
        proofUploadData = await proofUploadResp.json();
      } else {
        const textResponse = await proofUploadResp.text();
        setError(`Proof upload failed: ${textResponse || 'Invalid response'}`);
        setTimeout(() => setError(''), 5000);
        return;
      }

      if (!proofUploadResp.ok || proofUploadData.status !== 'success') {
        setError(proofUploadData.message || 'Proof submission file upload failed');
        setTimeout(() => setError(''), 5000);
        return;
      }

      const uploadedProofId = proofUploadData.fileId ?? proofUploadData.data?.fileId ?? proofUploadData.data?.file_id;
      const uploadedProofName = proofUploadData.fileName ?? proofUploadData.data?.fileName ?? file.name;
      if (uploadedProofId == null || String(uploadedProofId).trim() === '') {
        setError('Proof upload succeeded but server did not return file ID.');
        setTimeout(() => setError(''), 5000);
        return;
      }

      const proofSubmissionFileId = String(uploadedProofId).trim();
      const proofSubmissionFileName =
        uploadedProofName != null && String(uploadedProofName).trim() !== ''
          ? String(uploadedProofName).trim()
          : file.name;

      let targetId = resolveNumericStatutoryIdForProofRow(rowItem);

      if (targetId) {
        const putResp = await fetch(`/server/statutoryreg_function/statutory/${targetId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            ...buildMonthFilterPayload(rowItem),
            proofSubmissionFile: proofSubmissionFileId,
            proofSubmissionFileName
          })
        });
        const putData = await putResp.json().catch(() => ({}));
        if (!putResp.ok || putData.status !== 'success') {
          setError(putData.message || 'Failed to attach proof to statutory record.');
          setTimeout(() => setError(''), 5000);
          return;
        }
      } else {
        const monthFilterValue = resolveMonthFilterForSave(
          rowItem.dueDate,
          selectedMonth,
          rowItem.monthFilter || rowItem.MonthFilter || rowItem.monthfilter
        );
        const formFileId = rowItem.formFile ?? rowItem.FormFile ?? null;
        const formFileNameVal = rowItem.formFileName ?? rowItem.FormFileName ?? null;
        const draftFileId = rowItem.draftFile ?? rowItem.DraftFile ?? null;
        const draftFileNameVal = rowItem.draftFileName ?? rowItem.DraftFileName ?? null;
        const approvalVal = rowItem.approval ?? rowItem.Approval;
        const statusVal = rowItem.status != null && rowItem.status !== '' ? rowItem.status : rowItem.Status;
        const sfaVal = rowItem.sendForApproval ?? rowItem.SendForApproval;
        const remarksVal = rowItem.remarks ?? rowItem.Remarks;
        const payload = {
          act: rowItem.act || rowItem.Act || null,
          description: rowItem.description || rowItem.Description || null,
          sector: rowItem.sector || rowItem.Sector || null,
          state: rowItem.state || rowItem.State || null,
          site: rowItem.site || rowItem.Site || rowItem.siteName || rowItem.SiteName || null,
          formFile: formFileId != null && String(formFileId).trim() !== '' && String(formFileId).trim() !== 'null' ? String(formFileId).trim() : null,
          formFileName: formFileNameVal || null,
          formName: formNameTrim,
          dueDate: rowItem.dueDate || null,
          monthFilter: monthFilterValue,
          MonthFilter: monthFilterValue,
          monthfilter: monthFilterValue,
          autofill: rowItem.autofill || null,
          draft: rowItem.draft || null,
          proofSubmissionFile: proofSubmissionFileId,
          proofSubmissionFileName,
          draftFile: draftFileId != null && String(draftFileId).trim() !== '' && String(draftFileId).trim() !== 'null' ? String(draftFileId).trim() : null,
          draftFileName: draftFileNameVal || null,
          approval: approvalVal != null && String(approvalVal).trim() !== '' ? String(approvalVal).trim() : null,
          status: statusVal != null && String(statusVal).trim() !== '' ? String(statusVal).trim() : null,
          sendForApproval: sfaVal != null && String(sfaVal).trim() !== '' ? String(sfaVal).trim() : null,
          remarks: remarksVal != null && String(remarksVal).trim() !== '' ? String(remarksVal).trim() : null
        };

        const postResp = await fetch('/server/statutoryreg_function/statutory', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
        const postData = await postResp.json().catch(() => ({}));
        if (!postResp.ok || postData.status !== 'success') {
          setError(postData.message || 'Failed to create statutory record with proof.');
          setTimeout(() => setError(''), 5000);
          return;
        }
        targetId = postData.data?.statutory?.id != null ? String(postData.data.statutory.id) : null;
      }

      setSuccess('Proof submission uploaded successfully.');
      broadcastStatutoryDataChange({ id: targetId, source: 'proofUpload' });
      silentRefreshStatutoryTable();
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      console.error('Inline proof upload error:', err);
      setError(`Proof upload failed: ${err.message}`);
      setTimeout(() => setError(''), 5000);
    } finally {
      setProofUploadingRowId(null);
    }
  };
  const handleAutofill = async (item, options = {}) => {
    const viewFileTemplate =
      resolveFormMasterUploadedFileForViewFile(item, {
        formmasterFormFileByMatchKey,
        formFileByFormKey,
        formmasterTemplates
      }) || item;
    const enrichedItem = enrichStatutoryItemWithFormMasterMeta(
      viewFileTemplate,
      formmasterTemplates,
      formmasterFormFileByMatchKey
    );
    const autofillRowItem = {
      ...enrichedItem,
      formFile: viewFileTemplate?.formFile || enrichedItem?.formFile,
      formFileName: viewFileTemplate?.formFileName || enrichedItem?.formFileName,
      isFromFormmaster: !!(viewFileTemplate?.formFile || enrichedItem?.isFromFormmaster),
      formFetchRowId: viewFileTemplate?.formFetchRowId ?? item?.formFetchRowId ?? item?.id
    };
    prefetchStatutoryAutofillData();
    fetchPeopleDataForAutofillDisplay().catch(() => null);
    setIsAutofillMode(true);
    setAutofillItem(autofillRowItem);
    setFormFileLoading(true);
    setError('');
    setIsFormFileModalOpen(true);
    setFormFileModalData({
      fileName: autofillRowItem.formFileName || buildStatutoryFormFileLabel(autofillRowItem) || 'Form',
      fileType: 'excel-form',
      loading: true,
      item: autofillRowItem
    });
    await handleViewFormFile(autofillRowItem, true, options);
  };

  // Build draft workbook from formmaster template + table data (used by Save and by View Draft File generate-and-download)
  const buildDraftWorkbook = (opts) => {
    const {
      currentItem,
      templateWb,
      headersToUse,
      headerRowIndex,
      dataStartIndex,
      tableStartCol: tableStartColOpt,
      parsedFormHeader,
      headerFormData,
      formTableData,
      hasSubColumns,
      formFileName,
      allowTemplateFallback = true,
      sheetName: sheetNameOpt,
      originalHeaderRowIndex: originalHeaderRowIndexOpt,
      singleSheetExport = false
    } = opts;
    const formHeader = parsedFormHeader || null;
    const tableHeaders = headersToUse || [];
    const normalizeHeaderLookup = (txt) =>
      String(txt || '')
        .replace(/\r?\n/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase()
        .replace(/[^a-z0-9 ]/g, '');
    const getRowValueForHeader = (row, header, headerIndex, allHeaders) => {
      if (!row || typeof row !== 'object') return '';
      if (Object.prototype.hasOwnProperty.call(row, header)) return row[header];

      const target = normalizeHeaderLookup(header);
      if (!target) return '';

      const rowKeys = Object.keys(row);
      const exactMatches = rowKeys.filter((k) => normalizeHeaderLookup(k) === target);
      if (exactMatches.length === 1) return row[exactMatches[0]];
      if (exactMatches.length > 1) {
        const sameHeaderOccurIndex =
          allHeaders.slice(0, headerIndex + 1).filter((h) => normalizeHeaderLookup(h) === target).length - 1;
        const pick = exactMatches[Math.min(Math.max(sameHeaderOccurIndex, 0), exactMatches.length - 1)];
        return row[pick];
      }

      const fuzzyMatch = rowKeys.find((k) => {
        const n = normalizeHeaderLookup(k);
        return n && (n.includes(target) || target.includes(n));
      });
      if (fuzzyMatch) return row[fuzzyMatch];
      if (Array.isArray(row) && headerIndex < row.length) return row[headerIndex];
      const vals = Object.values(row);
      if (headerIndex < vals.length && vals[headerIndex] != null && String(vals[headerIndex]).trim() !== '') {
        return vals[headerIndex];
      }
      return '';
    };
    const useFormFileTemplate = templateWb && headerRowIndex >= 0 && dataStartIndex >= 0 && headersToUse.length > 0;
    let effectiveDataStartIndex = dataStartIndex;
    let wb;
    if (useFormFileTemplate) {
      wb = templateWb;
      const sheetParseHints = {
        fileName: formFileName,
        formFileName,
        formName: currentItem?.formName || currentItem?.FormName,
        item: currentItem,
        formHeaderTitle: (parsedFormHeader || formHeader)?.title,
        formHeaderSubtitle: (parsedFormHeader || formHeader)?.subtitle,
        formHeader: parsedFormHeader || formHeader
      };
      const targetSheetName =
        sheetNameOpt && wb.Sheets?.[sheetNameOpt]
          ? sheetNameOpt
          : resolveWorkbookSheetByHint(templateWb, sheetNameOpt, sheetParseHints);
      const ws = wb.Sheets[targetSheetName];
      if (!ws) {
        throw new Error(`Template worksheet not found: ${targetSheetName || sheetNameOpt || 'unknown'}`);
      }
      const sheetIdx = wb.SheetNames.indexOf(targetSheetName);
      if (sheetIdx >= 0) {
        if (!wb.Workbook) wb.Workbook = {};
        wb.Workbook.View = [{ activeTab: sheetIdx, firstSheet: sheetIdx }];
      }
      const writeCellPreserveStyle = (ref, rawValue) => {
        const prev = ws[ref] || {};
        if (rawValue == null || rawValue === '') {
          ws[ref] = { ...prev, t: 's', v: '' };
          return;
        }
        const isNum = typeof rawValue === 'number' || (typeof rawValue === 'string' && /^-?\d+(\.\d+)?$/.test(String(rawValue).trim()));
        if (isNum) {
          ws[ref] = { ...prev, t: 'n', v: Number(rawValue) };
        } else {
          ws[ref] = { ...prev, t: 's', v: String(rawValue) };
        }
      };
      const effectiveFormHeader = parsedFormHeader || formHeader;
      const isFormA = isFormAMusterRollContext(effectiveFormHeader) ||
        /\bform\s*[-"']?\s*a\b/i.test(String(currentItem?.formName || currentItem?.FormName || '')) ||
        /\bma\b.*\bform\b.*\ba\b/i.test(String(formFileName || ''));
      const isRegisterWagesDraft =
        isRegisterOfWagesFormContext(
          effectiveFormHeader,
          currentItem,
          formFileName,
          headersToUse
        ) ||
        isFormXXIIIContext(effectiveFormHeader, currentItem, formFileName) ||
        isStatutoryWageRegisterSaveContext(
          effectiveFormHeader,
          currentItem,
          formFileName,
          headersToUse
        );
      const isApFormXXIIIWageRegister =
        isFormXXIIIContext(effectiveFormHeader, currentItem, formFileName) ||
        /\bform[\s._-]*xxiii\b/i.test(String(formFileName || '').toLowerCase()) ||
        (/\bandhra[\s._-]*pradesh\b/i.test(String(formFileName || '').toLowerCase()) &&
          /register\s+of\s+wages/i.test(
            `${currentItem?.formName || ''} ${effectiveFormHeader?.title || ''} ${effectiveFormHeader?.subtitle || ''}`.toLowerCase()
          ) &&
          !/register\s+of\s+advances?/i.test(String(formFileName || '').toLowerCase()));
      const isFormClraRegisterDraft =
        isFormIRegisterOfFinesContext(currentItem, formFileName, effectiveFormHeader, headersToUse, '') ||
        isFormXAPRegisterOfFinesContext(
          effectiveFormHeader,
          currentItem,
          formFileName,
          '',
          headersToUse
        ) ||
        isFormXXIAPRegisterOfFinesContext(
          effectiveFormHeader,
          currentItem,
          formFileName,
          '',
          headersToUse
        ) ||
        isFormXXAPRegisterOfDeductionsContext(
          effectiveFormHeader,
          currentItem,
          formFileName,
          '',
          headersToUse
        );
      const useSequentialRegisterWagesCols = isRegisterWagesDraft && !isApFormXXIIIWageRegister;
      const useSequentialClraRegisterCols = isFormClraRegisterDraft;
      if (effectiveFormHeader?.fields && effectiveFormHeader.fields.length > 0) {
        for (let r = 0; r < headerRowIndex; r++) {
          for (let c = 0; c < 20; c++) {
            const ref = XLSX.utils.encode_cell({ r, c });
            const cell = ws[ref];
            if (!cell || cell.v == null) continue;
            const cellStr = String(cell.v).trim();
            for (const field of effectiveFormHeader.fields) {
              if (effectiveFormHeader.form12MergedHeaderCell && String(field.key || '').startsWith('form12_header_')) {
                continue;
              }
              if (effectiveFormHeader.form10MergedHeaderCell && String(field.key || '').startsWith('form10_header_')) {
                continue;
              }
              const label = (field.label || '').trim();
              if (!label) continue;
              if (cellStr === label || cellStr.startsWith(label) || label.startsWith(cellStr)) {
                const value = headerFormData[field.key] ?? field.value ?? '';
                const nextRef = XLSX.utils.encode_cell({ r, c: c + 1 });
                writeCellPreserveStyle(nextRef, String(value));
                break;
              }
            }
          }
        }
      }
      if (effectiveFormHeader?.form12MergedHeaderCell) {
        const { r, c } = effectiveFormHeader.form12MergedHeaderCell;
        const vF = String(headerFormData.form12_header_factory ?? '').trim();
        const vC = String(headerFormData.form12_header_contractor ?? '').trim();
        const vR = String(headerFormData.form12_header_registration ?? '').trim();
        const combined = `Name and Address of the Factory: ${vF}\nName and Address of the Contractor: ${vC}\nRegistration No: ${vR}`;
        const ref = XLSX.utils.encode_cell({ r, c });
        writeCellPreserveStyle(ref, combined);
      }
      if (effectiveFormHeader?.form10MergedHeaderCell) {
        const { r, c } = effectiveFormHeader.form10MergedHeaderCell;
        const vF = String(headerFormData.form10_header_factory ?? '').trim();
        const vC = String(headerFormData.form10_header_contractor ?? '').trim();
        const combined = `Name and Address of the Factory: ${vF}\nName and Address of the Contractor: ${vC}`;
        const ref = XLSX.utils.encode_cell({ r, c });
        writeCellPreserveStyle(ref, combined);
      }
      if (effectiveFormHeader?.form10MonthEndingCell) {
        const me = effectiveFormHeader.form10MonthEndingCell;
        const vM = String(headerFormData.form10_header_month_ending ?? '').trim();
        const ref = XLSX.utils.encode_cell({ r: me.r, c: me.c });
        const v =
          me.writeMode === 'full'
            ? (vM ? `Month ending: ${vM}` : 'Month ending: ')
            : vM;
        writeCellPreserveStyle(ref, String(v));
      }
      if (
        isForm14ChildWorkersContext(effectiveFormHeader, currentItem, formFileName, '') &&
        headerFormData &&
        typeof headerFormData === 'object'
      ) {
        for (let r = 0; r < headerRowIndex; r += 1) {
          const labelRef = XLSX.utils.encode_cell({ r, c: 0 });
          const cell = ws[labelRef];
          if (!cell || cell.v == null) continue;
          const label = String(cell.v).trim().replace(/:+$/, '');
          let key = null;
          if (/^name\s+of\s+the\s+factory$/i.test(label)) key = 'form14_header_factory';
          else if (/^place$/i.test(label)) key = 'form14_header_place';
          else if (/^district$/i.test(label)) key = 'form14_header_district';
          if (!key) continue;
          const value = headerFormData[key] ?? '';
          if (value != null && String(value).trim() !== '') {
            writeCellPreserveStyle(XLSX.utils.encode_cell({ r, c: 1 }), String(value));
          }
        }
      }
      if (effectiveFormHeader?.festivalGrid?.approvalProceedings) {
        const ap = effectiveFormHeader.festivalGrid.approvalProceedings;
        const v = headerFormData[ap.key] != null && headerFormData[ap.key] !== ''
          ? headerFormData[ap.key]
          : (ap.initialValue != null ? ap.initialValue : '');
        const writeAt = (r, c) => {
          if (r == null || c == null || c < 0) return;
          const ref = XLSX.utils.encode_cell({ r, c });
          writeCellPreserveStyle(ref, String(v));
        };
        if (ap.labelRow != null && ap.valueCol != null) {
          writeAt(ap.labelRow, ap.valueCol);
        } else {
          searchAp: for (let r = 0; r < headerRowIndex; r++) {
            for (let c = 0; c < 80; c++) {
              const ref = XLSX.utils.encode_cell({ r, c });
              const cell = ws[ref];
              if (!cell || cell.v == null) continue;
              const cellStr = String(cell.v).trim();
              const apLabel = (ap.label || '').trim();
              if (!apLabel) continue;
              if (cellStr === apLabel || cellStr.startsWith(apLabel) || apLabel.startsWith(cellStr)) {
                writeAt(r, c + 1);
                break searchAp;
              }
            }
          }
        }
      }
      if (effectiveFormHeader?.festivalGrid?.keys && Array.isArray(effectiveFormHeader.festivalGrid.slotCols) && effectiveFormHeader.festivalGrid.dataRow != null) {
        const { dataRow, slotCols, keys, initialValues } = effectiveFormHeader.festivalGrid;
        keys.forEach((key, i) => {
          const c = slotCols[i];
          if (c == null || c < 0) return;
          const value =
            headerFormData[key] != null && headerFormData[key] !== ''
              ? headerFormData[key]
              : (Array.isArray(initialValues) && initialValues[i] != null ? initialValues[i] : '');
          const ref = XLSX.utils.encode_cell({ r: dataRow, c });
          writeCellPreserveStyle(ref, String(value));
        });
      }
      const sheetArr = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
      const headerToCol = new Map();
      let registerWagesWriteStartCol = 0;
      const normalizeHeader = (txt) =>
        String(txt || '')
          .replace(/\r?\n/g, ' ')
          .replace(/\s+/g, ' ')
          .trim()
          .toLowerCase();
      const splitHeader = (txt) => {
        const normalized = normalizeHeader(txt);
        if (!normalized) return { main: '', sub: '' };
        if (normalized.includes('_')) {
          const firstUnderscore = normalized.indexOf('_');
          return {
            main: normalized.slice(0, firstUnderscore).trim(),
            sub: normalized.slice(firstUnderscore + 1).trim()
          };
        }
        return { main: normalized, sub: '' };
      };
      const merges = ws['!merges'] || [];
      const getRawCellText = (r, c) => {
        if (r < 0 || c < 0) return '';
        const ref = XLSX.utils.encode_cell({ r, c });
        const cell = ws[ref];
        if (!cell || cell.v == null) return '';
        return String(cell.v).trim();
      };
      const getMergedAwareCellText = (r, c) => {
        const direct = getRawCellText(r, c);
        if (direct) return direct;
        for (let i = 0; i < merges.length; i++) {
          const m = merges[i];
          if (!m || !m.s || !m.e) continue;
          if (r >= m.s.r && r <= m.e.r && c >= m.s.c && c <= m.e.c) {
            const topLeft = getRawCellText(m.s.r, m.s.c);
            if (topLeft) return topLeft;
          }
        }
        return '';
      };

      if (
        isForm14ChildWorkersContext(effectiveFormHeader, currentItem, formFileName, '') &&
        headerRowIndex >= 0
      ) {
        for (let offset = 1; offset <= 4; offset += 1) {
          let markers = 0;
          const probeRow = headerRowIndex + offset;
          for (let c = 0; c < 12; c += 1) {
            const v = String(getMergedAwareCellText(probeRow, c) || '').trim();
            if (/^\d+$/.test(v)) markers += 1;
          }
          if (markers >= 7) {
            effectiveDataStartIndex = Math.max(effectiveDataStartIndex, probeRow + 1);
            break;
          }
        }
      }

      // Form A / TN register: sequential cols; AP Form XXIII uses exact template column map.
      if (isFormA || useSequentialRegisterWagesCols || useSequentialClraRegisterCols) {
        let snoAnchor = null;
        for (let r = 0; r < Math.min(60, sheetArr.length); r++) {
          for (let c = 0; c < 120; c++) {
            const raw = getMergedAwareCellText(r, c);
            if (excelCellLooksLikeSerialHeader(raw)) {
              snoAnchor = { r, c };
              break;
            }
          }
          if (snoAnchor) break;
        }
        const startCol =
          tableStartColOpt != null && Number(tableStartColOpt) >= 0
            ? Number(tableStartColOpt)
            : (snoAnchor?.c != null ? snoAnchor.c : 0);
        if (isFormA) {
          const forcedDataStart = snoAnchor?.r != null ? (snoAnchor.r + 1) : effectiveDataStartIndex;
          effectiveDataStartIndex = forcedDataStart;
        }
        registerWagesWriteStartCol = startCol;
        for (let j = 0; j < headersToUse.length; j++) {
          headerToCol.set(headersToUse[j], startCol + j);
        }
      }
      if (isApFormXXIIIWageRegister) {
        let snoAnchor = null;
        for (let r = 0; r < Math.min(60, sheetArr.length); r++) {
          for (let c = 0; c < 120; c++) {
            const raw = getMergedAwareCellText(r, c);
            if (excelCellLooksLikeSerialHeader(raw)) {
              snoAnchor = { r, c };
              break;
            }
          }
          if (snoAnchor) break;
        }
        const apLayout = buildApShopsRegisterOfWagesExcelLayout(
          ws,
          headersToUse,
          originalHeaderRowIndexOpt != null && originalHeaderRowIndexOpt >= 0
            ? originalHeaderRowIndexOpt
            : headerRowIndex,
          headerRowIndex,
          Number.isFinite(dataStartIndex) && dataStartIndex >= 0
            ? dataStartIndex
            : snoAnchor?.r != null
              ? snoAnchor.r + 1
              : effectiveDataStartIndex
        );
        effectiveDataStartIndex = apLayout.dataStartRow;
        registerWagesWriteStartCol =
          apLayout.tableStartCol != null && apLayout.tableStartCol >= 0
            ? apLayout.tableStartCol
            : snoAnchor?.c != null
              ? snoAnchor.c
              : 0;
        // Parsed headers are in sheet column order (A→N); write sequentially from S.No. column.
        headersToUse.forEach((header, j) => {
          headerToCol.set(header, registerWagesWriteStartCol + j);
        });
        if (headerToCol.size === 0 && headersToUse.length > 0) {
          const startCol =
            tableStartColOpt != null && Number(tableStartColOpt) >= 0
              ? Number(tableStartColOpt)
              : registerWagesWriteStartCol;
          registerWagesWriteStartCol = startCol;
          headersToUse.forEach((header, j) => headerToCol.set(header, startCol + j));
        }
      }

      let tableRowsForWrite = Array.isArray(formTableData) ? formTableData : [];
      const isFormFinesRegisterDraft = isFormClraRegisterDraft;
      if (isApFormXXIIIWageRegister) {
        tableRowsForWrite = filterWageRegisterNilPlaceholderRows(
          filterWageRegisterSubstantiveExportRows(tableRowsForWrite, headersToUse),
          headersToUse
        );
      }

      const maxCols = Math.max(
        (sheetArr[headerRowIndex] || []).length,
        (sheetArr[headerRowIndex + 1] || []).length,
        headersToUse.length,
        20
      );
      if (!isFormA && !useSequentialRegisterWagesCols && !useSequentialClraRegisterCols && !isApFormXXIIIWageRegister) {
        // Prefer exact mapping from (main header + sub header) so grouped headers (Form X) keep the original column alignment.
        for (let c = 0; c < maxCols; c++) {
          const mainHeader = normalizeHeader(getMergedAwareCellText(headerRowIndex, c));
          const subHeader = normalizeHeader(getMergedAwareCellText(headerRowIndex + 1, c));
          const combinedHeader = mainHeader && subHeader ? `${mainHeader}_${subHeader}` : '';
          let bestHeader = null;
          let bestScore = 0;
          for (let j = 0; j < headersToUse.length; j++) {
            const header = normalizeHeader(headersToUse[j] || '');
            if (!header) continue;
            const { main, sub } = splitHeader(header);
            const isCombinedExact = combinedHeader && header === combinedHeader;
            const isMainSubMatch = mainHeader && main === mainHeader && (!sub || (subHeader && sub === subHeader));
            const isHeaderContains = (mainHeader && header.includes(mainHeader)) || (subHeader && header.includes(subHeader));
            if (isCombinedExact || isMainSubMatch || isHeaderContains) {
              const score = isCombinedExact ? 2000 : isMainSubMatch ? 1500 : Math.min(header.length, (combinedHeader || mainHeader || subHeader).length);
              if (score > bestScore) {
                bestScore = score;
                bestHeader = headersToUse[j];
              }
            }
          }
          if (bestHeader != null && !headerToCol.has(bestHeader)) {
            headerToCol.set(bestHeader, c);
          }
        }
        const mappedCols = Array.from(headerToCol.values());
        const fallbackStartCol = mappedCols.length > 0 ? Math.min(...mappedCols) : 0;
        for (let j = 0; j < headersToUse.length; j++) {
          const header = headersToUse[j];
          if (!headerToCol.has(header)) headerToCol.set(header, fallbackStartCol + j);
        }
      }
      if (isApFormXXIIIWageRegister) {
        const clearToRow = effectiveDataStartIndex + Math.max(tableRowsForWrite.length, 24) + 8;
        for (let r = effectiveDataStartIndex; r < clearToRow; r += 1) {
          for (let c = 0; c < maxCols + 4; c += 1) {
            const cellText = getMergedAwareCellText(r, c);
            if (!cellText && tableRowsForWrite.length === 0) continue;
            if (isWageRegisterNilPlaceholderCellValue(cellText) || tableRowsForWrite.length > 0) {
              const ref = XLSX.utils.encode_cell({ r, c });
              writeCellPreserveStyle(ref, '');
            }
          }
        }
      }
      if (isFormFinesRegisterDraft) {
        const clearToRow = effectiveDataStartIndex + Math.max(tableRowsForWrite.length, 4) + 18;
        for (let r = effectiveDataStartIndex; r < clearToRow; r += 1) {
          for (let c = 0; c < maxCols + 8; c += 1) {
            writeCellPreserveStyle(XLSX.utils.encode_cell({ r, c }), '');
          }
        }
      }
      for (let i = 0; i < tableRowsForWrite.length; i++) {
        const row = tableRowsForWrite[i];
        for (let j = 0; j < headersToUse.length; j++) {
          const header = headersToUse[j];
          let value = isApFormXXIIIWageRegister
            ? (() => {
                const direct = getRowValueForHeader(row, header, j, headersToUse);
                if (direct != null && String(direct).trim() !== '' && !isBlankApWageRegisterExportValue(direct, header)) {
                  return direct;
                }
                const semantic = getWageRegisterTemplateCellValue(row, header, i);
                if (semantic != null && String(semantic).trim() !== '' && !isBlankApWageRegisterExportValue(semantic, header)) {
                  return semantic;
                }
                return direct != null && String(direct).trim() !== '' ? direct : semantic;
              })()
            : getRowValueForHeader(row, header, j, headersToUse);
          if (isApFormXXIIIWageRegister && isWageRegisterNilPlaceholderCellValue(value)) value = '';
          if (isApFormXXIIIWageRegister && isBlankApWageRegisterExportValue(value, header)) value = '';
          const colIdx = isApFormXXIIIWageRegister
            ? (headerToCol.has(header) ? headerToCol.get(header) : registerWagesWriteStartCol + j)
            : useSequentialRegisterWagesCols || useSequentialClraRegisterCols || isFormA
              ? registerWagesWriteStartCol + j
              : headerToCol.has(header)
                ? headerToCol.get(header)
                : j;
          const cellRef = XLSX.utils.encode_cell({ r: effectiveDataStartIndex + i, c: colIdx });
          writeCellPreserveStyle(cellRef, value);
        }
      }
      // When imported rows extend beyond the template's original used range,
      // expand !ref so the saved workbook actually includes those appended rows.
      if (Array.isArray(tableRowsForWrite) && tableRowsForWrite.length > 0) {
        const writtenCols =
          useSequentialRegisterWagesCols || useSequentialClraRegisterCols || isFormA
            ? headersToUse.map((_, j) => registerWagesWriteStartCol + j)
            : Array.from(headerToCol.values()).filter((n) => Number.isFinite(n));
        const maxWrittenCol = writtenCols.length > 0
          ? Math.max(...writtenCols)
          : Math.max(0, headersToUse.length - 1);
        const maxWrittenRow = effectiveDataStartIndex + Math.max(tableRowsForWrite.length - 1, 0);
        let range;
        try {
          range = ws['!ref'] ? XLSX.utils.decode_range(ws['!ref']) : null;
        } catch (_) {
          range = null;
        }
        if (!range) {
          range = {
            s: { r: 0, c: 0 },
            e: { r: maxWrittenRow, c: maxWrittenCol }
          };
        } else {
          range.e.r = Math.max(range.e.r, maxWrittenRow);
          range.e.c = Math.max(range.e.c, maxWrittenCol);
        }
        ws['!ref'] = XLSX.utils.encode_range(range);
      }
      // Do not overwrite the header row – keep the original formmaster template layout exactly. Only data rows are filled above.
      if (singleSheetExport || isApFormXXIIIWageRegister) {
        wb = cloneWorkbookSingleSheet(wb, targetSheetName);
      } else if (templateWb?.SheetNames?.length > 1 && sheetNameOpt && targetSheetName) {
        wb = cloneWorkbookSingleSheet(wb, targetSheetName);
      }
    } else {
      if (!allowTemplateFallback) {
        throw new Error('Original form template is required to generate draft.');
      }
      wb = XLSX.utils.book_new();
      const headerRows = [];
      if (formHeader?.title) headerRows.push([formHeader.title]);
      if (formHeader?.subtitle) headerRows.push([formHeader.subtitle]);
      if (formHeader?.reference) headerRows.push([formHeader.reference]);
      if (formHeader?.fields && formHeader.fields.length > 0) {
        headerRows.push([]);
        const headerFieldRow = [];
        const headerValueRow = [];
        formHeader.fields.forEach((field) => {
          headerFieldRow.push(field.label);
          headerValueRow.push(headerFormData[field.key] || field.value || '');
        });
        headerRows.push(headerFieldRow);
        headerRows.push(headerValueRow);
      }
      headerRows.push([]);
      const effectiveTableHeaders = headersToUse.length ? headersToUse : tableHeaders;
      const formNameLowerFallback = (currentItem?.formName || formHeader?.title || '').toString().toLowerCase();
      const isFormUFallback = formNameLowerFallback.includes('form u') || formNameLowerFallback.includes('form u ');
      const headersForRow = isFormUFallback && FORM_U_FORMAT2_HEADERS.length > 0
        ? effectiveTableHeaders.map((_, idx) => FORM_U_FORMAT2_HEADERS[idx] ?? effectiveTableHeaders[idx])
        : effectiveTableHeaders;
      headerRows.push(headersForRow);
      const tableRows = formTableData.map((row) =>
        effectiveTableHeaders.map((header, idx) => {
          const v = getRowValueForHeader(row, header, idx, effectiveTableHeaders);
          return v != null ? v : '';
        })
      );
      const allData = [...headerRows, ...tableRows];
      const ws = XLSX.utils.aoa_to_sheet(allData);
      XLSX.utils.book_append_sheet(wb, ws, 'Sheet1');
    }
    const fileName = formFileName ||
      formHeader?.title?.replace(/[^a-zA-Z0-9]/g, '_') ||
      `Form_${Date.now()}.xlsx`;
    const excelBuffer = XLSX.write(wb, { type: 'array', bookType: 'xlsx' });
    const blob = new Blob([excelBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    return { blob, fileName };
  };

  const extractMappedRowsFromSavedDraft = ({
    draftWorkbook,
    templateHeaders,
    templateHeaderRowIndex,
    templateDataStartIndex,
    tableStartCol = 0,
    hasSubColumns
  }) => {
    if (!draftWorkbook || !Array.isArray(templateHeaders) || templateHeaders.length === 0) return [];
    const parsedDraft = parseExcelForm(draftWorkbook);
    const draftHeaders = Array.isArray(parsedDraft.headers) ? parsedDraft.headers : templateHeaders;
    const draftSheetName = draftWorkbook.SheetNames[0];
    const draftWs = draftWorkbook.Sheets[draftSheetName];
    if (!draftWs) return [];
    const draftRowsRaw = XLSX.utils.sheet_to_json(draftWs, { header: 1, defval: '' });
    const draftDataStart = parsedDraft.dataStartIndex != null && parsedDraft.dataStartIndex >= 0
      ? parsedDraft.dataStartIndex
      : 0;
    const fallbackTargetStart = templateDataStartIndex != null && templateDataStartIndex >= 0
      ? templateDataStartIndex
      : (templateHeaderRowIndex >= 0 ? templateHeaderRowIndex + (hasSubColumns ? 2 : 1) : 0);
    const startIndex = Math.max(0, Math.min(draftDataStart, fallbackTargetStart));
    const startCol =
      parsedDraft.tableStartCol != null && parsedDraft.tableStartCol >= 0
        ? parsedDraft.tableStartCol
        : tableStartCol;
    const draftDataRows = draftRowsRaw.slice(startIndex).filter((row) =>
      Array.isArray(row) &&
      row.slice(startCol, startCol + templateHeaders.length).some((cell) => String(cell ?? '').trim() !== '')
    );
    if (!draftDataRows.length) return [];
    return draftDataRows.map((rowArr, rowIdx) => {
      const rowObj = {};
      for (let i = 0; i < templateHeaders.length; i++) {
        const header = templateHeaders[i];
        let value = rowArr[startCol + i];
        if ((value == null || String(value).trim() === '') && draftHeaders[i] && draftHeaders[i] !== header) {
          value = rowArr[i];
        }
        rowObj[header] = value != null ? value : '';
      }
      if (
        templateHeaders[0] &&
        (rowObj[templateHeaders[0]] == null || String(rowObj[templateHeaders[0]]).trim() === '') &&
        /s\.?\s*no|serial|sl\.?\s*no/i.test(String(templateHeaders[0] || ''))
      ) {
        rowObj[templateHeaders[0]] = rowIdx + 1;
      }
      return rowObj;
    });
  };

  const extractRowMatrixFromSavedDraft = ({
    draftWorkbook,
    templateHeaderRowIndex,
    templateDataStartIndex,
    tableStartCol = 0,
    hasSubColumns
  }) => {
    if (!draftWorkbook) return [];
    const parsedDraft = parseExcelForm(draftWorkbook);
    const draftSheetName = draftWorkbook.SheetNames[0];
    const draftWs = draftWorkbook.Sheets[draftSheetName];
    if (!draftWs) return [];
    const draftRowsRaw = XLSX.utils.sheet_to_json(draftWs, { header: 1, defval: '' });
    const draftDataStart = parsedDraft.dataStartIndex != null && parsedDraft.dataStartIndex >= 0
      ? parsedDraft.dataStartIndex
      : 0;
    const fallbackTargetStart = templateDataStartIndex != null && templateDataStartIndex >= 0
      ? templateDataStartIndex
      : (templateHeaderRowIndex >= 0 ? templateHeaderRowIndex + (hasSubColumns ? 2 : 1) : 0);
    const startIndex = Math.max(0, Math.min(draftDataStart, fallbackTargetStart));
    const startCol =
      parsedDraft.tableStartCol != null && parsedDraft.tableStartCol >= 0
        ? parsedDraft.tableStartCol
        : tableStartCol;
    return draftRowsRaw.slice(startIndex).filter((row) =>
      Array.isArray(row) &&
      row.slice(startCol).some((cell) => String(cell ?? '').trim() !== '')
    );
  };

  const resolveSavedDraftRowsForModal = ({
    workbook,
    parsed,
    tableHeaders,
    tableStartCol = 0
  }) => {
    if (!workbook || !Array.isArray(tableHeaders) || tableHeaders.length === 0) return [];
    const hasSubColumns = parsed?.subColumns && Object.keys(parsed.subColumns || {}).length > 0;
    const rawHeaders = Array.isArray(parsed?.headers) ? parsed.headers : tableHeaders;
    const applyFormIRemap = (rows) => {
      if (
        !isFormIRegisterOfWorkmenContext(
          null,
          parsed?.formHeader?.title || '',
          parsed?.formHeader,
          tableHeaders,
          ''
        )
      ) {
        return rows;
      }
      return padFormIWorkmenRowsForHeaders(
        remapFormARowsByColumnIndex(rows, rawHeaders, tableHeaders),
        tableHeaders
      );
    };
    if (Array.isArray(parsed?.tableData) && parsed.tableData.length > 0) {
      const remapped = applyFormIRemap(
        remapFormARowsByColumnIndex(parsed.tableData, rawHeaders, tableHeaders)
      );
      const filtered = filterStatutoryDraftTableRows(remapped, tableHeaders);
      if (filtered.length > 0) return filtered;
    }
    let rows = extractMappedRowsFromSavedDraft({
      draftWorkbook: workbook,
      templateHeaders: tableHeaders,
      templateHeaderRowIndex: parsed?.headerRowIndex,
      templateDataStartIndex: parsed?.dataStartIndex,
      tableStartCol: parsed?.tableStartCol ?? tableStartCol,
      hasSubColumns
    });
    rows = applyFormIRemap(rows);
    rows = filterStatutoryDraftTableRows(rows, tableHeaders);
    if (rows.length > 0) return rows;
    const matrixRows = extractRowMatrixFromSavedDraft({
      draftWorkbook: workbook,
      templateHeaderRowIndex: parsed?.headerRowIndex,
      templateDataStartIndex: parsed?.dataStartIndex,
      tableStartCol: parsed?.tableStartCol ?? tableStartCol,
      hasSubColumns
    });
    if (!matrixRows.length) return [];
    const startCol = parsed?.tableStartCol ?? tableStartCol ?? 0;
    const matrixAsObjects = matrixRows.map((rowArr, rowIdx) => {
      const obj = {};
      tableHeaders.forEach((h, colIdx) => {
        obj[h] = rowArr[startCol + colIdx] != null ? rowArr[startCol + colIdx] : '';
      });
      if (
        tableHeaders[0] &&
        (obj[tableHeaders[0]] == null || String(obj[tableHeaders[0]]).trim() === '') &&
        /s\.?\s*no|serial|sl\.?\s*no/i.test(String(tableHeaders[0] || ''))
      ) {
        obj[tableHeaders[0]] = rowIdx + 1;
      }
      return obj;
    });
    return filterStatutoryDraftTableRows(applyFormIRemap(matrixAsObjects), tableHeaders);
  };

  const applySavedDraftRowsToModalTable = (
    rows,
    tableHeadersForModal,
    form26Open,
    form11Open,
    item,
    form26AOpen,
    formIFinesOpen,
    form12AdvancesOpen,
    formXXVIIQuarterlyOpen,
    formXAPFinesOpen = false,
    formXXAPDeductionsOpen = false
  ) => {
    if (!Array.isArray(rows) || rows.length === 0) return;
    setFormTableData(
      form26AOpen
        ? applyForm26ANilTableRows(tableHeadersForModal, rows, selectedMonth, item)
        : form26Open
        ? applyForm26NilTableRows(tableHeadersForModal, rows, selectedMonth, item)
        : form11Open
          ? applyForm11NilTableRows(tableHeadersForModal, rows, selectedMonth, item)
          : formXXAPDeductionsOpen
            ? prepareFormXXAPDeductionsExportRows(tableHeadersForModal, rows, selectedMonth, item)
          : formIFinesOpen || formXAPFinesOpen
            ? prepareFormIFinesExportRows(tableHeadersForModal, rows, selectedMonth, item)
            : form12AdvancesOpen
              ? applyForm12AdvancesNilTableRows(tableHeadersForModal, rows, selectedMonth, item)
              : formXXVIIQuarterlyOpen
                ? applyFormXXVIIQuarterlyNilTableRows(tableHeadersForModal, rows, selectedMonth, item)
          : rows
    );
  };

  const buildFormAWorkbookWithTemplateStyles = async ({
    templateArrayBuffer,
    headersToUse,
    mappedData,
    mappedRowMatrix,
    templateFileId,
    parsedFormHeader,
    formFileName,
    headerFormData
  }) => {
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(templateArrayBuffer);
    const worksheet = workbook.worksheets[0];
    if (!worksheet) {
      throw new Error('Template worksheet not found.');
    }
    const normalize = (txt) =>
      String(txt || '')
        .replace(/\r?\n/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase();
    const excelCellValueToString = (val) => {
      if (val == null) return '';
      if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') return String(val);
      if (val instanceof Date) return val.toISOString();
      if (typeof val === 'object') {
        if (Array.isArray(val.richText)) return val.richText.map((rt) => rt?.text || '').join('');
        if (val.text != null) return String(val.text);
        if (val.result != null) return String(val.result);
        if (val.hyperlink != null && val.text != null) return String(val.text);
        return '';
      }
      return '';
    };
    const getRowValueForHeader = (row, header) => {
      if (!row || typeof row !== 'object') return '';
      if (Object.prototype.hasOwnProperty.call(row, header)) return row[header];
      const target = normalize(header);
      if (!target) return '';
      const rowKeys = Object.keys(row);
      const exact = rowKeys.find((k) => normalize(k) === target);
      if (exact) return row[exact];
      const fuzzy = rowKeys.find((k) => {
        const nk = normalize(k);
        return nk && (nk.includes(target) || target.includes(nk));
      });
      return fuzzy ? row[fuzzy] : '';
    };

    let snoAnchor = null;
    const maxScanRows = Math.max(60, worksheet.rowCount + 5);
    const maxScanCols = 140;
    for (let r = 1; r <= maxScanRows; r++) {
      const rowCells = [];
      for (let c = 1; c <= maxScanCols; c++) {
        rowCells.push(excelCellValueToString(worksheet.getCell(r, c)?.value));
      }
      const rowTextLower = rowCells
        .map((v) => String(v || '').trim())
        .filter(Boolean)
        .join(' ')
        .toLowerCase();
      if (!isFormAMusterTableHeaderRowText(rowTextLower)) continue;
      for (let c = 1; c <= maxScanCols; c++) {
        const raw = excelCellValueToString(worksheet.getCell(r, c)?.value);
        const t = normalize(raw);
        if (t && (t === 's.no' || t === 's no' || t.includes('s.no') || t.includes('serial') || t === 'sl.no' || t === 'sl no')) {
          snoAnchor = { r, c };
          break;
        }
      }
      if (snoAnchor) break;
    }
    if (!snoAnchor) {
      for (let r = 1; r <= maxScanRows; r++) {
        for (let c = 1; c <= maxScanCols; c++) {
          const cell = worksheet.getCell(r, c);
          const raw = excelCellValueToString(cell?.value);
          const t = normalize(raw);
          if (t && (t === 's.no' || t === 's no' || t === 'sl.no' || t === 'sl no' || t === 'sr.no' || t === 'sr no')) {
            snoAnchor = { r, c };
            break;
          }
        }
        if (snoAnchor) break;
      }
    }

    const isHeaderFieldLayout = isFormAHeaderFieldLayoutFormHeader(parsedFormHeader);
    const headerValues =
      headerFormData && typeof headerFormData === 'object' ? headerFormData : {};
    const hasHeaderFieldValues = Object.values(headerValues).some((v) => String(v ?? '').trim() !== '');

    if ((isHeaderFieldLayout || !snoAnchor) && hasHeaderFieldValues) {
      writeFormAHeaderFieldsToExcelWorksheet(worksheet, headerValues, parsedFormHeader, {
        excelCellValueToString
      });
      const out = await workbook.xlsx.writeBuffer();
      const fileName = formFileName ||
        parsedFormHeader?.title?.replace(/[^a-zA-Z0-9]/g, '_') ||
        `Form_${Date.now()}.xlsx`;
      const blob = new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      return { blob, fileName };
    }

    if (!snoAnchor) {
      throw new Error('Could not locate Form A table anchor (S.No) in original template.');
    }

    let dataStartRow = snoAnchor.r + 1;
    let seqHits = 0;
    for (let j = 0; j < (headersToUse?.length || 0); j += 1) {
      const t = normalize(excelCellValueToString(worksheet.getCell(snoAnchor.r + 1, snoAnchor.c + j)?.value));
      if (t === String(j + 1)) seqHits += 1;
    }
    if (seqHits >= Math.max(3, Math.floor((headersToUse?.length || 0) * 0.4))) {
      dataStartRow = snoAnchor.r + 2;
    }
    const startRow = dataStartRow;
    const startCol = snoAnchor.c;
    const isStrictFormATemplate = true;
    const useMatrix = Array.isArray(mappedRowMatrix) && mappedRowMatrix.length > 0;
    const cleanedMatrixRows = useMatrix
      ? mappedRowMatrix.filter((row) => {
          if (!Array.isArray(row)) return false;
          const cells = row.map((v) => String(v ?? '').trim()).filter(Boolean);
          if (cells.length === 0) return false;
          if (!isStrictFormATemplate) return true;
          const hasAlpha = cells.some((v) => /[a-z]/i.test(v));
          return hasAlpha;
        })
      : [];
    const cleanedObjectRows = !useMatrix && Array.isArray(mappedData)
      ? mappedData.filter((row) => {
          if (!row || typeof row !== 'object') return false;
          const vals = Object.values(row).map((v) => String(v ?? '').trim()).filter(Boolean);
          if (vals.length === 0) return false;
          if (!isStrictFormATemplate) return true;
          const hasAlpha = vals.some((v) => /[a-z]/i.test(v));
          return hasAlpha;
        })
      : [];
    const totalRows = useMatrix ? cleanedMatrixRows.length : cleanedObjectRows.length;
    for (let i = 0; i < totalRows; i++) {
      const rowObj = cleanedObjectRows[i] || {};
      const rowArr = useMatrix ? (cleanedMatrixRows[i] || []) : null;
      const totalCols = useMatrix ? rowArr.length : headersToUse.length;
      for (let j = 0; j < totalCols; j++) {
        const header = headersToUse[j];
        const value = useMatrix ? rowArr[j] : getRowValueForHeader(rowObj, header);
        const cell = worksheet.getCell(startRow + i, startCol + j);
        if (value == null || value === '') {
          // For strict Form A template, never blank existing cells — keep original header text/layout untouched.
          if (!isStrictFormATemplate) {
            cell.value = '';
          }
        } else if (typeof value === 'number' || (typeof value === 'string' && /^-?\d+(\.\d+)?$/.test(String(value).trim()))) {
          cell.value = Number(value);
        } else {
          cell.value = String(value);
        }
      }
    }

    const out = await workbook.xlsx.writeBuffer();
    const fileName = formFileName ||
      parsedFormHeader?.title?.replace(/[^a-zA-Z0-9]/g, '_') ||
      `Form_${Date.now()}.xlsx`;
    const blob = new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    return { blob, fileName };
  };

  const buildFormUWorkbookWithTemplateStyles = async ({
    templateArrayBuffer,
    headersToUse,
    mappedData,
    mappedRowMatrix,
    parsedFormHeader,
    formFileName
  }) => {
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(templateArrayBuffer);

    const normalize = (txt) =>
      String(txt || '')
        .replace(/\r?\n/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase();
    const excelCellValueToString = (val) => {
      if (val == null) return '';
      if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') return String(val);
      if (val instanceof Date) return val.toISOString();
      if (typeof val === 'object') {
        if (Array.isArray(val.richText)) return val.richText.map((rt) => rt?.text || '').join('');
        if (val.text != null) return String(val.text);
        if (val.result != null) return String(val.result);
        return '';
      }
      return '';
    };
    const findFormUAnchorInWorksheet = (ws) => {
      if (!ws) return null;
      let bestAnchor = null;
      let bestScore = -1;
      const maxScanRows = Math.max(80, (ws.rowCount || 0) + 5);
      for (let r = 1; r <= maxScanRows; r += 1) {
        let rowSrCol = null;
        let rowHasPersonCol = false;
        let keywordHits = 0;
        let textCellCount = 0;
        for (let c = 1; c <= 180; c += 1) {
          const raw = excelCellValueToString(ws.getCell(r, c)?.value);
          const t = normalize(raw);
          if (!t) continue;
          textCellCount += 1;
          if (excelCellLooksLikeSerialHeader(raw)) {
            rowSrCol = c;
          }
          if (/name\s+of\s+the\s+person/.test(t)) {
            rowHasPersonCol = true;
            keywordHits += 20;
          }
          if (/name\s+of\s+the\s+employee|employee\s+identification|employee\s+name/.test(t)) keywordHits += 16;
          if (/\bgender\b|\bsex\b/.test(t)) keywordHits += 4;
          if (/father|spouse/.test(t)) keywordHits += 2;
          if (/date\s+of\s+birth|date\s+of\s+joining|designation/.test(t)) keywordHits += 2;
          if (/present\s+address|permanent\s+address|aadha?r|photo|bank/.test(t)) keywordHits += 1;
        }
        if (rowSrCol == null) continue;
        const score =
          keywordHits +
          (textCellCount * 2) +
          (rowHasPersonCol ? 60 : 0) +
          (rowSrCol <= 3 ? 10 : 0);
        if (score > bestScore) {
          bestScore = score;
          bestAnchor = { r, c: rowSrCol };
        }
      }
      if (!bestAnchor) {
        for (let r = 1; r <= maxScanRows; r += 1) {
          for (let c = 1; c <= 180; c += 1) {
            const raw = excelCellValueToString(ws.getCell(r, c)?.value);
            if (excelCellLooksLikeSerialHeader(raw)) {
              bestAnchor = { r, c };
              break;
            }
          }
          if (bestAnchor) break;
        }
      }
      return bestAnchor ? { ...bestAnchor, score: Math.max(bestScore, 0) } : null;
    };
    // Some Form U templates put the real table on a later worksheet, so score every sheet.
    const sheetCandidates = Array.isArray(workbook.worksheets) ? workbook.worksheets : [];
    let worksheet = sheetCandidates[0] || null;
    let snoAnchor = null;
    let bestAnchorScore = -1;
    for (const ws of sheetCandidates) {
      const candidate = findFormUAnchorInWorksheet(ws);
      if (!candidate) continue;
      if (candidate.score > bestAnchorScore) {
        bestAnchorScore = candidate.score;
        worksheet = ws;
        snoAnchor = { r: candidate.r, c: candidate.c };
      }
    }
    if (!worksheet) throw new Error('Template worksheet not found.');
    const getRowValueForHeader = (row, header) => {
      if (!row || typeof row !== 'object') return '';
      if (Object.prototype.hasOwnProperty.call(row, header)) return row[header];
      const target = normalize(header);
      if (!target) return '';
      const rowKeys = Object.keys(row);
      const exact = rowKeys.find((k) => normalize(k) === target);
      if (exact) return row[exact];
      const fuzzy = rowKeys.find((k) => {
        const nk = normalize(k);
        return nk && (nk.includes(target) || target.includes(nk));
      });
      return fuzzy ? row[fuzzy] : '';
    };
    const pickObjectValue = (row, patterns, fallbackIndex = null) => {
      if (!row || typeof row !== 'object' || Array.isArray(row)) return '';
      const keys = Object.keys(row);
      const norm = (s) => normalize(String(s || '').replace(/[^a-z0-9]/gi, ' '));
      for (let pi = 0; pi < patterns.length; pi++) {
        const p = patterns[pi];
        const hit = keys.find((k) => p.test(norm(k)));
        if (hit) {
          const v = row[hit];
          if (v != null && String(v).trim() !== '') return v;
        }
      }
      if (fallbackIndex != null && fallbackIndex >= 0 && fallbackIndex < keys.length) {
        return row[keys[fallbackIndex]];
      }
      return '';
    };
    const toFormUOrderedValues = (row, rowIndex) => {
      if (Array.isArray(row)) return row;
      const ordered = [
        pickObjectValue(row, [/\bs\.?\s*no\b/, /\bsr\.?\s*no\b/, /serial/], 0),
        pickObjectValue(row, [/name.*employee/, /employee.*name/, /name of the employee/], 1),
        pickObjectValue(row, [/employee.*identification/, /employee.*id/, /emp.*id/], 2),
        pickObjectValue(row, [/\bgender\b/, /\bsex\b/], 3),
        pickObjectValue(row, [/father.*spouse/, /spouse.*father/, /father.*name/, /spouse.*name/], 4),
        pickObjectValue(row, [/date.*birth/, /\bdob\b/], 5),
        pickObjectValue(row, [/date.*joining/, /\bdoj\b/], 6),
        pickObjectValue(row, [/designation/, /position/], 7),
        pickObjectValue(row, [/present.*address/], 8),
        pickObjectValue(row, [/permanent.*address/], 9),
        pickObjectValue(row, [/employee.*aadha?r/, /aadha?r/], 10),
        pickObjectValue(row, [/date.*notice.*pregnancy/, /notice.*pregnancy/], 11),
        pickObjectValue(row, [/date.*notice.*delivery/, /notice.*delivery/], 12),
        pickObjectValue(row, [/date.*proof.*birth/, /proof.*birth/], 13),
        pickObjectValue(row, [/date.*proof.*death/, /proof.*death/], 14),
        pickObjectValue(row, [/period.*wages/, /wages.*period/], 15),
        pickObjectValue(row, [/bank.*a\/?c/, /bank.*account/], 16),
        pickObjectValue(row, [/\bphoto\b/], 17)
      ];
      if (ordered[0] == null || String(ordered[0]).trim() === '') ordered[0] = rowIndex + 1;
      return ordered;
    };
    const toFormUConfidentialOrderedValues = (row, rowIndex) => {
      if (Array.isArray(row)) return row;
      const sno =
        pickObjectValue(row, [/\bs\.?\s*no\b/, /\bsr\.?\s*no\b/, /serial/], 0) || rowIndex + 1;
      const name = pickObjectValue(row, [/name\s+of\s+the\s+person/, /name.*person/], 1);
      return [sno, name];
    };
    if (!snoAnchor) {
      throw new Error('Could not locate Form U table anchor (S.No / Sr. No.) in original template.');
    }

    const headerRow = snoAnchor.r;
    const startCol = snoAnchor.c;
    const headerColMap = new Map();
    for (let c = Math.max(1, startCol - 1); c <= 220; c++) {
      const txt = normalize(excelCellValueToString(worksheet.getCell(headerRow, c)?.value));
      if (txt) headerColMap.set(c, txt);
    }
    const headerTexts = [...headerColMap.values()];
    const isConfidentialFormU =
      headersIndicateFormUConfidential(headersToUse) ||
      headerTexts.some((t) => /name\s+of\s+the\s+person/.test(t));

    let numberingRowBelowHeader = false;
    if (!isConfidentialFormU) {
      let numericMarkers = 0;
      for (let c = startCol; c <= startCol + 12; c++) {
        const v = normalize(excelCellValueToString(worksheet.getCell(headerRow + 1, c)?.value));
        if (/^\d+$/.test(v)) numericMarkers += 1;
      }
      numberingRowBelowHeader = numericMarkers >= 2;
    }
    const startRow = isConfidentialFormU
      ? headerRow + 1
      : numberingRowBelowHeader
        ? headerRow + 2
        : headerRow + 1;
    const resolveFormUColForHeader = (header) => {
      const h = normalize(header);
      if (!h) return null;
      const matchers = [
        { key: 'sno', re: /\bs\.?\s*no\b|serial/ },
        { key: 'name_employee', re: /name\s+of\s+the\s+employee|name\s+of\s+employee/ },
        { key: 'employee_id', re: /employee\s+identification|employee\s+id/ },
        { key: 'gender', re: /\bgender\b/ },
        { key: 'father_spouse', re: /father.*spouse|spouse.*father/ },
        { key: 'dob', re: /date\s+of\s+birth/ },
        { key: 'doj', re: /date\s+of\s+joining/ },
        { key: 'designation', re: /designation/ },
        { key: 'present_address', re: /present\s+address/ },
        { key: 'permanent_address', re: /permanent\s+address/ },
        { key: 'aadhaar', re: /aadha?r/ },
        { key: 'wages_period', re: /period\s+of\s+wages/ },
        { key: 'bank', re: /bank\s*a\/?c/ },
        { key: 'photo', re: /\bphoto\b/ }
      ];
      let targetMatcher = matchers.find((m) => m.re.test(h));
      if (!targetMatcher) return null;
      for (const [col, txt] of headerColMap.entries()) {
        if (targetMatcher.re.test(txt)) return col;
      }
      return null;
    };
    const formUFieldMatchers = isConfidentialFormU
      ? [/\bs\.?\s*no\b|\bsr\.?\s*no\b|serial/, /name\s+of\s+the\s+person/]
      : [
      /\bs\.?\s*no\b|serial/,                              // 0
      /name\s+of\s+the\s+employee|name\s+of\s+employee/,  // 1
      /employee\s+identification|employee\s+id/,          // 2
      /\bgender\b/,                                        // 3
      /father.*spouse|spouse.*father/,                    // 4
      /date\s+of\s+birth/,                                 // 5
      /date\s+of\s+joining/,                               // 6
      /designation/,                                       // 7
      /present\s+address/,                                 // 8
      /permanent\s+address/,                               // 9
      /aadha?r/,                                           // 10
      /notice.*pregnancy|pregnancy.*notice/,              // 11
      /notice.*delivery|delivery.*notice/,                // 12
      /proof.*birth|birth.*proof/,                        // 13
      /proof.*death|death.*proof/,                        // 14
      /period\s+of\s+wages|wages\s+period/,               // 15
      /bank\s*a\/?c|bank\s+account/,                      // 16
      /\bphoto\b/                                          // 17
    ];
    const formUFieldCols = formUFieldMatchers.map((re, idx) => {
      for (const [col, txt] of headerColMap.entries()) {
        if (re.test(txt)) return col;
      }
      return startCol + idx;
    });
    const hasMeaningfulRow = (row) => {
      if (!Array.isArray(row)) return false;
      const cells = row.map((v) => String(v ?? '').trim()).filter(Boolean);
      if (cells.length === 0) return false;
      if (isConfidentialFormU) {
        return cells.some((v) => /[a-z]/i.test(v)) || cells.length >= 1;
      }
      // Ignore pure serial/index-like rows (e.g. "1,2,3,4,5...").
      const alphaCount = cells.filter((v) => /[a-z]/i.test(v)).length;
      if (alphaCount > 0) return true;
      const numericOnly = cells.every((v) => /^-?\d+(\.\d+)?$/.test(v));
      return !numericOnly && cells.length >= 3;
    };
    const matrixRows = Array.isArray(mappedRowMatrix)
      ? mappedRowMatrix.filter((row) => hasMeaningfulRow(row))
      : [];
    const mapRowValues = isConfidentialFormU ? toFormUConfidentialOrderedValues : toFormUOrderedValues;
    const mappedArrayRows = Array.isArray(mappedData)
      ? mappedData
          .map((row, idx) => mapRowValues(row, idx))
          .filter((row) => hasMeaningfulRow(row))
      : [];
    const useMatrix = matrixRows.length > 0 || mappedArrayRows.length > 0;
    const isMeaningfulObjectRow = (row) => {
      if (!row || typeof row !== 'object' || Array.isArray(row)) return false;
      const vals = Object.values(row).map((v) => String(v ?? '').trim()).filter(Boolean);
      if (vals.length === 0) return false;
      const hasAlpha = vals.some((v) => /[a-z]/i.test(v));
      if (hasAlpha) return true;
      const numericOnly = vals.every((v) => /^-?\d+(\.\d+)?$/.test(v));
      return !numericOnly;
    };
    const matrixSource = matrixRows.length > 0 ? matrixRows : mappedArrayRows;
    const totalRows = matrixSource.length;

    const writableCols = (isConfidentialFormU ? formUFieldCols.slice(0, 2) : formUFieldCols).filter(
      (c) => Number.isFinite(c) && c > 0
    );
    const tableColMin = writableCols.length > 0 ? Math.min(startCol, ...writableCols) : startCol;
    let tableColMax = writableCols.length > 0 ? Math.max(...writableCols) : startCol + 1;
    for (let c = tableColMin; c <= tableColMax + 4; c++) {
      const bodyCell = worksheet.getCell(startRow, c);
      const b = bodyCell?.border;
      if (b && (b.left?.style || b.right?.style || b.top?.style || b.bottom?.style)) {
        tableColMax = Math.max(tableColMax, c);
      }
    }

    const isFormUFooterRow = (r) => {
      for (let c = 1; c <= Math.max(30, tableColMax + 4); c++) {
        const t = normalize(excelCellValueToString(worksheet.getCell(r, c)?.value));
        if (!t) continue;
        if (/^date\s*:?$/.test(t) || /^place\s*:?$/.test(t)) return true;
        if (/signature of the manager|authorised person with seal|cc to/i.test(t)) return true;
      }
      return false;
    };

    const countTemplateFormUDataRows = () => {
      let rows = 0;
      for (let r = startRow; r <= startRow + 150; r++) {
        if (isFormUFooterRow(r)) break;
        rows += 1;
      }
      return Math.max(rows, 1);
    };

    const copyFormUDataRowStyle = (fromRowNum, toRowNum) => {
      const fromRow = worksheet.getRow(fromRowNum);
      const toRow = worksheet.getRow(toRowNum);
      if (fromRow.height) toRow.height = fromRow.height;
      for (let c = tableColMin; c <= tableColMax; c++) {
        const src = worksheet.getCell(fromRowNum, c);
        const dst = worksheet.getCell(toRowNum, c);
        if (!src?.style) continue;
        try {
          dst.style = JSON.parse(JSON.stringify(src.style));
        } catch (_) {
          dst.style = { ...src.style };
        }
      }
    };

    const templateDataRows = countTemplateFormUDataRows();
    const rowsToInsert = Math.max(0, totalRows - templateDataRows);
    if (rowsToInsert > 0) {
      const anchorRow = startRow + templateDataRows - 1;
      if (typeof worksheet.duplicateRow === 'function') {
        worksheet.duplicateRow(anchorRow, rowsToInsert, true);
      } else {
        for (let k = 0; k < rowsToInsert; k++) {
          const insertAt = startRow + templateDataRows;
          worksheet.insertRow(insertAt, []);
          copyFormUDataRowStyle(anchorRow, insertAt);
        }
      }
    }

    for (let i = 0; i < totalRows; i++) {
      const rowArr = matrixSource[i] || [];
      const totalCols = rowArr.length;
      const targetRow = startRow + i;
      writableCols.forEach((col) => {
        worksheet.getCell(targetRow, col).value = null;
      });
      for (let j = 0; j < totalCols; j++) {
        let value = rowArr[j];
        if (value == null || value === '') continue;
        const targetCol = j < formUFieldCols.length ? formUFieldCols[j] : (startCol + j);
        const cell = worksheet.getCell(targetRow, targetCol);
        if ((targetCol === formUFieldCols[0] || j === 0) && (typeof value === 'number' || (typeof value === 'string' && /^-?\d+(\.\d+)?$/.test(String(value).trim())))) {
          cell.value = Number(value);
        } else {
          cell.value = String(value);
        }
      }
    }

    const out = await workbook.xlsx.writeBuffer();
    const fileName = formFileName ||
      parsedFormHeader?.title?.replace(/[^a-zA-Z0-9]/g, '_') ||
      `Form_${Date.now()}.xlsx`;
    const blob = new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    return { blob, fileName };
  };

  const buildForm12WorkbookWithTemplateStyles = async ({
    templateArrayBuffer,
    mappedData,
    mappedRowMatrix,
    headersToUse,
    parsedHeaderRowIndex,
    parsedDataStartIndex,
    parsedTableStartCol,
    parsedFormHeader,
    formFileName,
    headerFormData
  }) => {
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(templateArrayBuffer);

    const normalize = (txt) =>
      String(txt || '')
        .replace(/\r?\n/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase();
    const excelCellValueToString = (val) => {
      if (val == null) return '';
      if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') return String(val);
      if (val instanceof Date) return val.toISOString();
      if (typeof val === 'object') {
        if (Array.isArray(val.richText)) return val.richText.map((rt) => rt?.text || '').join('');
        if (val.text != null) return String(val.text);
        if (val.result != null) return String(val.result);
      }
      return '';
    };

    const findForm12AnchorInWorksheet = (ws) => {
      if (!ws) return null;
      let bestAnchor = null;
      let bestScore = -1;
      const maxScanRows = Math.max(80, (ws.rowCount || 0) + 5);
      const maxScanCols = 220;
      const sheetName = normalize(ws?.name || ws?.sheetName || '');
      const titleHint = normalize(
        `${parsedFormHeader?.title || ''} ${parsedFormHeader?.subtitle || ''} ${formFileName || ''}`
      );
      for (let r = 1; r <= maxScanRows; r++) {
        let rowSrCol = null;
        let textCellCount = 0;
        let keywordHits = 0;
        for (let c = 1; c <= maxScanCols; c++) {
          const raw = excelCellValueToString(ws.getCell(r, c)?.value);
          const t = normalize(raw);
          if (!t) continue;
          textCellCount += 1;
          if (excelCellLooksLikeSerialHeader(raw)) {
            rowSrCol = c;
          }
          if (/register\s+of\s+advances?\s+of\s+wages/.test(t)) keywordHits += 40;
          if (/\bform\s*[-"']?\s*(12|xii)\b/.test(t)) keywordHits += 25;
          if (/advance/.test(t)) keywordHits += 5;
          if (/\bwage/.test(t) || /\bwages/.test(t)) keywordHits += 5;
          if (/loan|deduction|amount|balance|paid|repayment|installment/.test(t)) keywordHits += 1;
        }
        if (rowSrCol == null) continue;
        let score = keywordHits + (textCellCount * 2) + (rowSrCol <= 3 ? 10 : 0);
        if (sheetName && titleHint && (sheetName.includes(titleHint) || titleHint.includes(sheetName))) {
          score += 20;
        } else if (sheetName && (/xii|12|advance|wage/.test(sheetName))) {
          score += 8;
        }
        if (score > bestScore) {
          bestScore = score;
          bestAnchor = { r, c: rowSrCol };
        }
      }
      if (!bestAnchor) {
        for (let r = 1; r <= maxScanRows; r += 1) {
          for (let c = 1; c <= maxScanCols; c += 1) {
            const raw = excelCellValueToString(ws.getCell(r, c)?.value);
            if (excelCellLooksLikeSerialHeader(raw)) {
              bestAnchor = { r, c };
              break;
            }
          }
          if (bestAnchor) break;
        }
      }
      return bestAnchor ? { ...bestAnchor, score: Math.max(bestScore, 0) } : null;
    };

    const sheetCandidates = Array.isArray(workbook.worksheets) ? workbook.worksheets : [];
    let worksheet = sheetCandidates[0] || null;
    let snoAnchor = null;
    let bestAnchorScore = -1;
    for (const ws of sheetCandidates) {
      const candidate = findForm12AnchorInWorksheet(ws);
      if (!candidate) continue;
      if (candidate.score > bestAnchorScore) {
        bestAnchorScore = candidate.score;
        worksheet = ws;
        snoAnchor = { r: candidate.r, c: candidate.c };
      }
    }
    if (!worksheet) throw new Error('Template worksheet not found.');
    if (
      !snoAnchor &&
      parsedHeaderRowIndex != null &&
      parsedHeaderRowIndex >= 0
    ) {
      const headerRow1 = parsedHeaderRowIndex + 1;
      let col1 =
        parsedTableStartCol != null && parsedTableStartCol >= 0
          ? parsedTableStartCol + 1
          : 1;
      for (let c = 1; c <= 220; c++) {
        const raw = excelCellValueToString(worksheet.getCell(headerRow1, c)?.value);
        if (excelCellLooksLikeSerialHeader(raw)) {
          col1 = c;
          break;
        }
      }
      snoAnchor = { r: headerRow1, c: col1 };
    }
    if (!snoAnchor) throw new Error('Could not locate Form 12 table anchor (S.No).');

    const headerRow = snoAnchor.r;
    const startCol = snoAnchor.c;
    const nextRowValues = [];
    for (let c = startCol; c <= startCol + 40; c++) {
      nextRowValues.push(normalize(excelCellValueToString(worksheet.getCell(headerRow + 1, c)?.value)));
    }
    const numericMarkers = nextRowValues.filter((v) => /^\d+$/.test(v)).length;
    let startRow = numericMarkers >= 4 ? (headerRow + 2) : (headerRow + 1);
    if (parsedDataStartIndex != null && parsedDataStartIndex >= 0) {
      startRow = parsedDataStartIndex + 1;
    }

    const orderedHeaders = Array.isArray(headersToUse) && headersToUse.length > 0
      ? headersToUse
      : FORM_12_ALIGNMENT_HEADERS;
    const sourceHeaders = [...orderedHeaders];
    const templateHeaderCols = [];
    let blankRun = 0;
    for (let c = startCol; c <= 260; c++) {
      const txt = normalize(excelCellValueToString(worksheet.getCell(headerRow, c)?.value));
      if (txt) {
        templateHeaderCols.push(c);
        blankRun = 0;
      } else if (templateHeaderCols.length > 0) {
        blankRun += 1;
        if (blankRun >= 8) break;
      }
    }
    const templateHeaderLabels = templateHeaderCols.map((c) =>
      excelCellValueToString(worksheet.getCell(headerRow, c)?.value).trim()
    );
    const resolveTemplateHeaderLabel = (idx) => {
      let label = templateHeaderLabels[idx] || '';
      const normLabel = normalize(label);
      if (!label || /^\d+$/.test(normLabel)) {
        if (sourceHeaders[idx]) label = sourceHeaders[idx];
      }
      if (!label || /^\d+$/.test(normalize(label))) {
        const above = excelCellValueToString(worksheet.getCell(headerRow - 1, templateHeaderCols[idx])?.value).trim();
        if (above && !/^\d+$/.test(normalize(above))) label = above;
      }
      return label;
    };
    const fieldCols = templateHeaderCols.length > 0
      ? [...templateHeaderCols]
      : sourceHeaders.map((_, idx) => startCol + idx);
    const headerNormKey = (h) => normalize(String(h || '').replace(/[^a-z0-9]/gi, ' '));
    const form12HeaderAliasBucket = (norm) => {
      if (!norm) return '';
      if (/^s\.?\s*no|serial\s*number|sl\.?\s*no/.test(norm)) return 'sno';
      if (/bank/.test(norm) && (/account|ifsc|branch|financial|a c|ac no/.test(norm))) return 'bank';
      if (/^photo/.test(norm)) return 'photo';
      if (/mobile/.test(norm)) return 'mobile';
      if (/e\s*mail|email/.test(norm)) return 'email';
      if (/specimen|signature|thumb/.test(norm)) return 'signature';
      if (/date.*exit/.test(norm)) return 'dateexit';
      if (/reason.*exit/.test(norm)) return 'reasonexit';
      if (/remark/.test(norm)) return 'remarks';
      if (/480.*day|completion.*480/.test(norm)) return '480days';
      if (/made permanent|permanent/.test(norm)) return 'permanent';
      if (/period.*suspension|suspension/.test(norm)) return 'suspension';
      if (/esic|esi/.test(norm)) return 'esic';
      return norm;
    };
    const getRowValueForHeader = (row, header, headerIndex) => {
      if (!row || typeof row !== 'object' || Array.isArray(row)) return '';
      if (header && Object.prototype.hasOwnProperty.call(row, header)) {
        const direct = row[header];
        if (direct != null && String(direct).trim() !== '') return direct;
      }
      if (headerIndex != null && headerIndex >= 0 && sourceHeaders[headerIndex]) {
        const sourceKey = sourceHeaders[headerIndex];
        if (Object.prototype.hasOwnProperty.call(row, sourceKey)) {
          const sourceVal = row[sourceKey];
          if (sourceVal != null && String(sourceVal).trim() !== '') return sourceVal;
        }
      }
      const target = headerNormKey(header);
      if (!target) return '';
      const targetAlias = form12HeaderAliasBucket(target);
      const rowKeys = Object.keys(row);
      const exact = rowKeys.find((k) => headerNormKey(k) === target);
      if (exact && row[exact] != null && String(row[exact]).trim() !== '') return row[exact];
      if (targetAlias) {
        const aliasMatch = rowKeys.find((k) => form12HeaderAliasBucket(headerNormKey(k)) === targetAlias);
        if (aliasMatch && row[aliasMatch] != null && String(row[aliasMatch]).trim() !== '') return row[aliasMatch];
      }
      const fuzzy = rowKeys.find((k) => {
        const nk = headerNormKey(k);
        return nk && (nk.includes(target) || target.includes(nk));
      });
      if (fuzzy && row[fuzzy] != null && String(row[fuzzy]).trim() !== '') return row[fuzzy];
      if (headerIndex != null && headerIndex >= 0) {
        const vals = Object.values(row);
        if (vals[headerIndex] != null && String(vals[headerIndex]).trim() !== '') {
          return vals[headerIndex];
        }
      }
      return '';
    };
    const toForm12OrderedValues = (row, rowIndex) => {
      if (Array.isArray(row)) {
        const out = [...row];
        if (out[0] != null) {
          const s0 = String(out[0]).trim();
          const m = s0.match(/^(\d+)\s+(.+)$/);
          if (m && (!out[1] || String(out[1]).trim() === '')) {
            out[0] = m[1];
            out[1] = m[2];
          }
        }
        if (out[0] == null || String(out[0]).trim() === '') out[0] = rowIndex + 1;
        const colCount = Math.max(fieldCols.length, sourceHeaders.length, out.length);
        return Array.from({ length: colCount }, (_, idx) => out[idx] ?? '');
      }
      const colCount = Math.max(fieldCols.length, sourceHeaders.length, templateHeaderLabels.length);
      const out = Array.from({ length: colCount }, (_, idx) => {
        const templateLabel = resolveTemplateHeaderLabel(idx);
        const sourceLabel = sourceHeaders[idx] || '';
        let val = templateLabel ? getRowValueForHeader(row, templateLabel, idx) : '';
        if (val === '' && sourceLabel && sourceLabel !== templateLabel) {
          val = getRowValueForHeader(row, sourceLabel, idx);
        }
        return val != null ? val : '';
      });
      if (out[0] == null || String(out[0]).trim() === '') out[0] = rowIndex + 1;
      return out;
    };

    const rowLooksMeaningful = (row) => {
      if (Array.isArray(row)) {
        const cells = row.map((v) => String(v ?? '').trim()).filter(Boolean);
        if (cells.length === 0) return false;
        return cells.some((v) => /[a-z]/i.test(v)) || !cells.every((v) => /^-?\d+(\.\d+)?$/.test(v));
      }
      if (row && typeof row === 'object') {
        const vals = Object.values(row).map((v) => String(v ?? '').trim()).filter(Boolean);
        if (vals.length === 0) return false;
        return vals.some((v) => /[a-z]/i.test(v)) || !vals.every((v) => /^-?\d+(\.\d+)?$/.test(v));
      }
      return false;
    };
    const sourcePrimary = Array.isArray(mappedData) && mappedData.length > 0 ? mappedData : (Array.isArray(mappedRowMatrix) ? mappedRowMatrix : []);
    const sourceRows = sourcePrimary
      .filter((row) => rowLooksMeaningful(row))
      .map((row, idx) => {
        const out = toForm12OrderedValues(row, idx);
        if (out[0] == null || String(out[0]).trim() === '') out[0] = idx + 1;
        return out;
      });

    const writableCols = fieldCols;
    for (let i = 0; i < sourceRows.length; i++) {
      const row = sourceRows[i];
      // Clear existing template sample row values so every employee row follows the same model alignment.
      for (let wc = 0; wc < writableCols.length; wc++) {
        const clearCell = worksheet.getCell(startRow + i, writableCols[wc]);
        clearCell.value = '';
      }
      for (let j = 0; j < row.length && j < writableCols.length; j++) {
        const value = row[j];
        if (value == null || value === '') continue;
        const targetCol = j < fieldCols.length ? fieldCols[j] : (startCol + j);
        const cell = worksheet.getCell(startRow + i, targetCol);
        if ((j === 0) && (typeof value === 'number' || (typeof value === 'string' && /^-?\d+(\.\d+)?$/.test(String(value).trim())))) {
          cell.value = Number(value);
        } else {
          cell.value = String(value);
        }
        // Keep Form 12 data rows normal-weight (template sample row can be bold).
        cell.font = { ...(cell.font || {}), bold: false };
        cell.alignment = { ...(cell.alignment || {}), horizontal: 'left' };
      }
    }

    writeForm10Form12HeaderFieldsToExcelJsWorksheet(worksheet, headerFormData, parsedFormHeader);

    const out = await workbook.xlsx.writeBuffer();
    const fileName = formFileName ||
      parsedFormHeader?.title?.replace(/[^a-zA-Z0-9]/g, '_') ||
      `Form_${Date.now()}.xlsx`;
    const blob = new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    return { blob, fileName };
  };

  const buildFormJWorkbookWithTemplateStyles = async ({
    templateArrayBuffer,
    mappedData,
    mappedRowMatrix,
    headersToUse,
    parsedHeaderRowIndex,
    parsedDataStartIndex,
    parsedFormHeader,
    formFileName
  }) => {
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(templateArrayBuffer);
    const worksheet = workbook.worksheets[0];
    if (!worksheet) throw new Error('Template worksheet not found.');

    const normalize = (txt) =>
      String(txt || '')
        .replace(/\r?\n/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase();
    const excelCellValueToString = (val) => {
      if (val == null) return '';
      if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') return String(val);
      if (val instanceof Date) return val.toISOString();
      if (typeof val === 'object') {
        if (Array.isArray(val.richText)) return val.richText.map((rt) => rt?.text || '').join('');
        if (val.text != null) return String(val.text);
        if (val.result != null) return String(val.result);
      }
      return '';
    };

    const maxScanRows = Math.max(120, worksheet.rowCount + 10);
    const maxScanCols = 80;

    const rowHasFormJRegisterHeader = (r) => {
      let hasEmployee = false;
      let hasSexOrAge = false;
      for (let c = 1; c <= maxScanCols; c++) {
        const t = normalize(excelCellValueToString(worksheet.getCell(r, c)?.value));
        if (!t) continue;
        if (
          /name\s+of\s+the\s+employee/.test(t) ||
          (t.includes('employee') && t.includes('establishment'))
        ) {
          hasEmployee = true;
        }
        if (t === 'sex' || /\bsex\b/.test(t) || t === 'age' || /\bage\b/.test(t)) {
          hasSexOrAge = true;
        }
      }
      return hasEmployee && hasSexOrAge;
    };

    const findNumberedMarkerBelow = (headerR) => {
      for (let r = headerR + 1; r <= Math.min(headerR + 3, maxScanRows); r++) {
        let startCol = -1;
        let seq = 0;
        let expect = 1;
        for (let c = 1; c <= maxScanCols; c++) {
          const t = normalize(excelCellValueToString(worksheet.getCell(r, c)?.value));
          if (!/^(\d{1,2})$/.test(t)) continue;
          const n = parseInt(t, 10);
          if (n === expect) {
            if (startCol < 0) startCol = c;
            seq = expect;
            expect += 1;
          }
        }
        if (seq >= 8) return { markerRow: r, startCol };
      }
      return null;
    };

    let headerRow = -1;
    let startCol = 1;
    let startRow = -1;

    for (let r = 1; r <= maxScanRows; r++) {
      if (!rowHasFormJRegisterHeader(r)) continue;
      headerRow = r;
      for (let c = 1; c <= maxScanCols; c++) {
        const t = normalize(excelCellValueToString(worksheet.getCell(r, c)?.value));
        if (
          /name\s+of\s+the\s+employee/.test(t) ||
          (t.includes('employee') && t.includes('establishment'))
        ) {
          startCol = c;
          break;
        }
      }
      if (startCol < 1) {
        for (let c = 1; c <= maxScanCols; c++) {
          const t = normalize(excelCellValueToString(worksheet.getCell(r, c)?.value));
          if (t) {
            startCol = c;
            break;
          }
        }
      }
      const marker = findNumberedMarkerBelow(r);
      if (marker && marker.startCol > 0) startCol = marker.startCol;
      startRow = marker ? marker.markerRow + 1 : r + 1;
      break;
    }

    if (headerRow < 1) {
      for (let r = 1; r <= maxScanRows; r++) {
        for (let c = 1; c <= maxScanCols; c++) {
          const t = normalize(excelCellValueToString(worksheet.getCell(r, c)?.value));
          if (t && (t === 's.no' || t === 's no' || t.includes('s.no') || t.includes('serial'))) {
            headerRow = r;
            startCol = c;
            const marker = findNumberedMarkerBelow(r);
            startRow = marker ? marker.markerRow + 1 : (r + 1);
            break;
          }
        }
        if (headerRow > 0) break;
      }
    }

    if (headerRow < 1 && parsedHeaderRowIndex != null && parsedHeaderRowIndex >= 0) {
      headerRow = parsedHeaderRowIndex + 1;
      startCol = 1;
      for (let c = 1; c <= maxScanCols; c++) {
        const t = normalize(excelCellValueToString(worksheet.getCell(headerRow, c)?.value));
        if (t) {
          startCol = c;
          break;
        }
      }
      const marker = findNumberedMarkerBelow(headerRow);
      if (marker && marker.startCol > 0) startCol = marker.startCol;
      startRow =
        parsedDataStartIndex != null && parsedDataStartIndex >= 0
          ? parsedDataStartIndex + 1
          : marker
            ? marker.markerRow + 1
            : headerRow + 1;
    }

    if (headerRow < 1 || startRow < 1) {
      throw new Error(
        'Could not locate Form J table (Register of Employment — Name of the employee / Sex / Age headers) in original template.'
      );
    }

    const templateHeaderCols = [];
    let blankRun = 0;
    for (let c = startCol; c <= startCol + 24; c++) {
      const txt = normalize(excelCellValueToString(worksheet.getCell(headerRow, c)?.value));
      if (txt) {
        templateHeaderCols.push(c);
        blankRun = 0;
      } else if (templateHeaderCols.length > 0) {
        blankRun += 1;
        if (blankRun >= 4) break;
      }
    }
    if (templateHeaderCols.length < 4) {
      const marker = findNumberedMarkerBelow(headerRow);
      const markerRow = marker ? marker.markerRow : headerRow + 1;
      const colsFromNumbers = [];
      for (let c = startCol; c <= startCol + 24; c++) {
        const t = normalize(excelCellValueToString(worksheet.getCell(markerRow, c)?.value));
        if (/^(\d{1,2})$/.test(t)) colsFromNumbers.push(c);
      }
      if (colsFromNumbers.length >= 8) {
        templateHeaderCols.length = 0;
        templateHeaderCols.push(...colsFromNumbers);
      }
    }

    const templateHeaderLabels = templateHeaderCols.map((col) =>
      String(excelCellValueToString(worksheet.getCell(headerRow, col)?.value) || '').trim()
    );
    const orderedHeaders =
      Array.isArray(headersToUse) && headersToUse.length > 0
        ? headersToUse
        : templateHeaderLabels.filter(Boolean);
    const colCount = Math.max(
      templateHeaderCols.length,
      orderedHeaders.length,
      12
    );
    const effectiveHeaders =
      orderedHeaders.length > 0
        ? orderedHeaders.slice(0, colCount)
        : templateHeaderLabels.filter(Boolean);
    const fieldCols = Array.from({ length: colCount }, (_, idx) =>
      templateHeaderCols[idx] != null ? templateHeaderCols[idx] : startCol + idx
    );

    const formJFieldMatchers = [
      /name\s+of\s+the\s+employee|employee.*establishment|name.*employee/,
      /\bsex\b/,
      /\bage\b/,
      /employment\s+commences|time.*commences|commences/,
      /employment\s+ceases|time.*ceases|ceases/,
      /rest\s+interval/,
      /hours\s+worked.*sunday|sunday.*monday|monday.*tuesday|wednesday/,
      /hours\s+worked.*thursday|thursday.*friday|saturday/,
      /date\s+on\s+which\s+over|over.?hours\s+worked\s+during\s+the\s+week/,
      /date\s+on\s+extent|extent\s+of\s+time\s+work/,
      /overtime\s+worked\s+during\s+the\s+week/,
      /extent\s+of\s+overtime\s+worked\s+previously/
    ];

    const pickObjectValue = (row, patterns, fallbackIndex = null) => {
      if (!row || typeof row !== 'object' || Array.isArray(row)) return '';
      const keys = Object.keys(row);
      const normKey = (s) => normalize(String(s || '').replace(/[^a-z0-9]/gi, ' '));
      for (let pi = 0; pi < patterns.length; pi++) {
        const hit = keys.find((k) => patterns[pi].test(normKey(k)));
        if (hit) {
          const v = row[hit];
          if (v != null && String(v).trim() !== '') return v;
        }
      }
      if (fallbackIndex != null && fallbackIndex >= 0 && fallbackIndex < keys.length) {
        return row[keys[fallbackIndex]];
      }
      return '';
    };

    const getRowValueForHeader = (row, header) => {
      if (!row || typeof row !== 'object' || Array.isArray(row)) return '';
      if (Object.prototype.hasOwnProperty.call(row, header)) return row[header];
      const target = normalize(String(header || '').replace(/[^a-z0-9]/gi, ' '));
      if (!target) return '';
      const rowKeys = Object.keys(row);
      const exact = rowKeys.find((k) => normalize(String(k || '').replace(/[^a-z0-9]/gi, ' ')) === target);
      if (exact) return row[exact];
      const fuzzy = rowKeys.find((k) => {
        const nk = normalize(String(k || '').replace(/[^a-z0-9]/gi, ' '));
        return nk && (nk.includes(target) || target.includes(nk));
      });
      return fuzzy ? row[fuzzy] : '';
    };
    const toFormJOrderedValues = (row) => {
      if (Array.isArray(row)) {
        return effectiveHeaders.map((_, idx) => row[idx] ?? '');
      }
      return effectiveHeaders.map((header, idx) => {
        const direct = getRowValueForHeader(row, header);
        if (direct != null && String(direct).trim() !== '') return direct;
        const matchers = idx < formJFieldMatchers.length ? [formJFieldMatchers[idx]] : [];
        if (matchers.length > 0) return pickObjectValue(row, matchers, idx);
        return pickObjectValue(row, formJFieldMatchers, idx);
      });
    };

    const rowLooksMeaningful = (row) => {
      if (Array.isArray(row)) {
        const cells = row.map((v) => String(v ?? '').trim()).filter(Boolean);
        if (cells.length === 0) return false;
        return cells.some((v) => /[a-z]/i.test(v)) || !cells.every((v) => /^-?\d+(\.\d+)?$/.test(v));
      }
      if (row && typeof row === 'object') {
        const vals = Object.values(row).map((v) => String(v ?? '').trim()).filter(Boolean);
        if (vals.length === 0) return false;
        return vals.some((v) => /[a-z]/i.test(v)) || !vals.every((v) => /^-?\d+(\.\d+)?$/.test(v));
      }
      return false;
    };
    const sourcePrimary = Array.isArray(mappedData) && mappedData.length > 0
      ? mappedData
      : (Array.isArray(mappedRowMatrix) ? mappedRowMatrix : []);
    const sourceRows = sourcePrimary
      .filter((row) => rowLooksMeaningful(row))
      .map((row) => toFormJOrderedValues(row));

    const writableCols = fieldCols.slice(0, effectiveHeaders.length);
    const lastTableCol = writableCols.length > 0 ? Math.max(...writableCols) : startCol + colCount - 1;

    const copyFormJDataRowStyle = (fromRowNum, toRowNum) => {
      const fromRow = worksheet.getRow(fromRowNum);
      const toRow = worksheet.getRow(toRowNum);
      if (fromRow.height) toRow.height = fromRow.height;
      for (let c = startCol; c <= lastTableCol; c++) {
        const src = worksheet.getCell(fromRowNum, c);
        const dst = worksheet.getCell(toRowNum, c);
        if (!src?.style) continue;
        try {
          dst.style = JSON.parse(JSON.stringify(src.style));
        } catch (_) {
          dst.style = { ...src.style };
        }
      }
    };

    const countExistingFormJDataRows = () => {
      let count = 0;
      let blankStreak = 0;
      for (let r = startRow; r < startRow + 120; r++) {
        let hasCell = false;
        for (let wi = 0; wi < writableCols.length; wi++) {
          const v = String(excelCellValueToString(worksheet.getCell(r, writableCols[wi])?.value) || '').trim();
          if (v) hasCell = true;
        }
        if (hasCell) {
          count += 1;
          blankStreak = 0;
        } else if (count > 0) {
          blankStreak += 1;
          if (blankStreak >= 2) break;
        }
      }
      return Math.max(count, 1);
    };

    const templateDataRows = countExistingFormJDataRows();
    const rowsToInsert = Math.max(0, sourceRows.length - templateDataRows);
    if (rowsToInsert > 0) {
      if (typeof worksheet.duplicateRow === 'function') {
        const anchorRow = startRow + templateDataRows - 1;
        worksheet.duplicateRow(anchorRow, rowsToInsert, true);
      } else {
        for (let k = 0; k < rowsToInsert; k++) {
          worksheet.insertRow(startRow + 1, []);
          copyFormJDataRowStyle(startRow, startRow + 1);
        }
      }
    }

    for (let i = 0; i < sourceRows.length; i++) {
      const row = sourceRows[i];
      const targetRow = startRow + i;
      for (let wc = 0; wc < writableCols.length; wc++) {
        worksheet.getCell(targetRow, writableCols[wc]).value = '';
      }
      for (let c = lastTableCol + 1; c <= lastTableCol + 40; c++) {
        const spill = worksheet.getCell(targetRow, c);
        if (spill.value != null && spill.value !== '') spill.value = null;
      }
      const maxWriteCols = Math.min(row.length, writableCols.length);
      for (let j = 0; j < maxWriteCols; j++) {
        const value = row[j];
        if (value == null || value === '') continue;
        worksheet.getCell(targetRow, writableCols[j]).value = String(value);
      }
    }

    const out = await workbook.xlsx.writeBuffer();
    const fileName = formFileName ||
      parsedFormHeader?.title?.replace(/[^a-zA-Z0-9]/g, '_') ||
      `Form_${Date.now()}.xlsx`;
    const blob = new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    return { blob, fileName };
  };

  /** Form K — Register of Employment (hotel/restaurant/theatre): preserve template + numbered "Hours worked on" columns. */
  const buildFormKWorkbookWithTemplateStyles = async ({
    templateArrayBuffer,
    mappedData,
    mappedRowMatrix,
    headersToUse,
    parsedHeaderRowIndex,
    parsedDataStartIndex,
    parsedFormHeader,
    formFileName,
    sheetNameHint = '',
    filterNilPlaceholderRows = false
  }) => {
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(templateArrayBuffer);
    let worksheet = workbook.worksheets[0];
    if (sheetNameHint) {
      const hintNorm = String(sheetNameHint).trim().toLowerCase();
      const hinted =
        workbook.getWorksheet(sheetNameHint) ||
        workbook.worksheets.find((ws) => String(ws?.name || '') === String(sheetNameHint)) ||
        workbook.worksheets.find((ws) => String(ws?.name || '').trim().toLowerCase() === hintNorm);
      if (hinted) worksheet = hinted;
    }
    if (!worksheet) throw new Error('Template worksheet not found.');

    const normalize = (txt) =>
      String(txt || '')
        .replace(/\r?\n/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase()
        .replace(/[^a-z0-9 ]/g, '');
    const excelCellValueToString = (val) => {
      if (val == null) return '';
      if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') return String(val);
      if (val instanceof Date) return val.toISOString();
      if (typeof val === 'object') {
        if (Array.isArray(val.richText)) return val.richText.map((rt) => rt?.text || '').join('');
        if (val.text != null) return String(val.text);
        if (val.result != null) return String(val.result);
      }
      return '';
    };

    const maxScanCols = 45;
    let headerRow = parsedHeaderRowIndex != null && parsedHeaderRowIndex >= 0 ? (parsedHeaderRowIndex + 1) : -1;

    if (headerRow < 1) {
      for (let r = 1; r <= 30; r++) {
        let hasEmployeeCol = false;
        let hasSerialCol = false;
        for (let c = 1; c <= maxScanCols; c++) {
          const t = normalize(excelCellValueToString(worksheet.getCell(r, c)?.value));
          if (/name\s+of\s+the\s+employee/.test(t) || /employee.*establishment/.test(t)) {
            hasEmployeeCol = true;
          }
          if (/^s\.?\s*no\.?$/.test(t) || /^sr\.?\s*no\.?$/.test(t) || /^sl\.?\s*no\.?$/.test(t)) {
            hasSerialCol = true;
          }
        }
        if (hasEmployeeCol && hasSerialCol) {
          headerRow = r;
          break;
        }
      }
    }
    if (headerRow < 1) {
      for (let r = 1; r <= 30; r++) {
        for (let c = 1; c <= maxScanCols; c++) {
          const t = normalize(excelCellValueToString(worksheet.getCell(r, c)?.value));
          if (/name\s+of\s+the\s+employee/.test(t) && /establishment/.test(t)) {
            headerRow = r;
            break;
          }
        }
        if (headerRow > 0) break;
      }
    }
    if (headerRow < 1) throw new Error('Could not locate Form K table header row in template.');

    let tableStartCol = 2;
    for (let c = 1; c <= maxScanCols; c++) {
      const n = normalize(excelCellValueToString(worksheet.getCell(headerRow, c)?.value));
      if (
        /name\s+of\s+the\s+employee/.test(n) ||
        n === 'sex' ||
        n === 'age' ||
        /employment\s+commence/.test(n) ||
        /hours\s+worked\s+on/.test(n)
      ) {
        tableStartCol = c;
        break;
      }
    }

    const specColByKey = new Map();
    const assignSpecCol = (specKey, col) => {
      const writeCol = Math.max(col, tableStartCol);
      if (!specColByKey.has(specKey)) specColByKey.set(specKey, writeCol);
    };
    for (let c = 1; c <= maxScanCols; c++) {
      const raw = excelCellValueToString(worksheet.getCell(headerRow, c)?.value);
      const n = normalize(raw);
      if (!n) continue;
      if (/name\s+of\s+the\s+employee/.test(n) || /employee.*establishment/.test(n)) assignSpecCol('name', c);
      else if (n === 'sex') assignSpecCol('sex', c);
      else if (n === 'age') assignSpecCol('age', c);
      else if (/employment\s+commence/.test(n)) assignSpecCol('commence', c);
      else if (/employment\s+cease/.test(n)) assignSpecCol('cease', c);
      else if (/rest\s+interval/.test(n)) assignSpecCol('rest', c);
      else if (/total\s+hours/.test(n)) assignSpecCol('total_hours', c);
      else if (/extent\s+of\s+overtime/.test(n) && !/days\s+on/.test(n)) assignSpecCol('overtime', c);
      else if (/days\s+on\s+which/.test(n)) assignSpecCol('overtime_days', c);
    }

    let hoursBandStart = -1;
    let hoursBandEnd = -1;
    for (let c = 1; c <= maxScanCols; c++) {
      const n = normalize(excelCellValueToString(worksheet.getCell(headerRow, c)?.value));
      if (
        /hours\s+worked\s+on/.test(n) ||
        ((/dates|attendance/.test(n) || /\bp\s*present\b/.test(n)) &&
          !/commence|cease/.test(n))
      ) {
        if (hoursBandStart < 0) hoursBandStart = Math.max(c, tableStartCol);
        hoursBandEnd = c;
      }
    }
    const numberedColByKey = new Map();
    let numberedSubRow = -1;
    const dayNumberScanFrom = hoursBandStart > 0 ? hoursBandStart : Math.max(tableStartCol + 6, 8);
    for (let r = headerRow; r <= headerRow + 3; r++) {
      const cols = new Map();
      for (let c = dayNumberScanFrom; c <= maxScanCols; c++) {
        const raw = String(excelCellValueToString(worksheet.getCell(r, c)?.value) || '').trim();
        if (!/^\d{1,2}$/.test(raw)) continue;
        const num = parseInt(raw, 10);
        if (num < 1 || num > 31) continue;
        cols.set(num, c);
      }
      if (cols.size >= 2 && cols.size >= numberedColByKey.size) {
        numberedColByKey.clear();
        cols.forEach((col, num) => numberedColByKey.set(num, col));
        numberedSubRow = r;
      }
    }
    numberedColByKey.forEach((col, num) => specColByKey.set(`hours_${num}`, col));
    const sortedDayCols = [...numberedColByKey.entries()].sort((a, b) => a[0] - b[0]);
    if (sortedDayCols.length >= 1) {
      let colStep = 1;
      if (sortedDayCols.length >= 2) {
        colStep = sortedDayCols[1][1] - sortedDayCols[0][1];
        if (!Number.isFinite(colStep) || colStep <= 0) colStep = 1;
      }
      const [anchorDay, anchorCol] = sortedDayCols[0];
      for (let d = 1; d <= 31; d += 1) {
        if (!specColByKey.has(`hours_${d}`)) {
          const knownCol = numberedColByKey.get(d);
          specColByKey.set(`hours_${d}`, knownCol != null ? knownCol : anchorCol + (d - anchorDay) * colStep);
        }
      }
    }

    const formKFallbackCols = [
      ['name', tableStartCol],
      ['sex', tableStartCol + 1],
      ['age', tableStartCol + 2],
      ['commence', tableStartCol + 3],
      ['cease', tableStartCol + 4],
      ['rest', tableStartCol + 5]
    ];
    formKFallbackCols.forEach(([key, col]) => {
      if (!specColByKey.has(key)) specColByKey.set(key, col);
    });
    if (numberedColByKey.size === 0) {
      const hoursBase = hoursBandStart > 0 ? hoursBandStart : tableStartCol + 6;
      for (let d = 1; d <= 31; d += 1) {
        if (!specColByKey.has(`hours_${d}`)) specColByKey.set(`hours_${d}`, hoursBase + (d - 1));
      }
    }

    const parsedStart = parsedDataStartIndex != null && parsedDataStartIndex >= 0 ? (parsedDataStartIndex + 1) : 0;
    let dataStartRow = headerRow + 1;
    if (numberedSubRow > headerRow) dataStartRow = numberedSubRow + 1;
    // AP Form XXII: parser dataStartIndex is the first body row; day-number sub-row must not push data down.
    if (parsedStart > headerRow) dataStartRow = parsedStart;
    dataStartRow = Math.max(dataStartRow, headerRow + 1);

    const hdrs = Array.isArray(headersToUse) ? headersToUse : [];
    const specKeyToHeaderIndices = new Map();
    for (let hi = 0; hi < hdrs.length; hi++) {
      const specKey = FORM_K_HEADER_TO_SPEC_KEY(hdrs[hi]);
      if (!specKey) continue;
      if (!specKeyToHeaderIndices.has(specKey)) specKeyToHeaderIndices.set(specKey, []);
      specKeyToHeaderIndices.get(specKey).push(hi);
    }
    const dayHeadersFromGrid = [];
    for (let hi = 0; hi < hdrs.length; hi += 1) {
      const specKey = FORM_K_HEADER_TO_SPEC_KEY(hdrs[hi]);
      if (!specKey || !/^hours_\d+$/.test(specKey)) continue;
      dayHeadersFromGrid.push({
        hi,
        specKey,
        day: parseInt(specKey.replace('hours_', ''), 10)
      });
    }
    if (dayHeadersFromGrid.length > 0) {
      dayHeadersFromGrid.sort((a, b) => a.day - b.day);
      const dayColStart =
        (sortedDayCols.length > 0 ? sortedDayCols[0][1] : null) ??
        (hoursBandStart > 0 ? hoursBandStart : null) ??
        (specColByKey.get('rest') != null ? specColByKey.get('rest') + 1 : null) ??
        (specColByKey.get('cease') != null ? specColByKey.get('cease') + 1 : null) ??
        tableStartCol + 6;
      let dayColStep = 1;
      if (sortedDayCols.length >= 2) {
        dayColStep = sortedDayCols[1][1] - sortedDayCols[0][1];
        if (!Number.isFinite(dayColStep) || dayColStep <= 0) dayColStep = 1;
      } else if (dayHeadersFromGrid.length >= 2) {
        dayColStep = dayHeadersFromGrid[1].hi - dayHeadersFromGrid[0].hi;
        if (!Number.isFinite(dayColStep) || dayColStep <= 0) dayColStep = 1;
      }
      dayHeadersFromGrid.forEach(({ specKey, day }, idx) => {
        const mappedCol =
          numberedColByKey.get(day) ??
          specColByKey.get(specKey) ??
          dayColStart + idx * dayColStep;
        specColByKey.set(specKey, mappedCol);
      });
    }

    const rowLooksMeaningful = (row) => {
      if (Array.isArray(row)) return row.some((v) => String(v ?? '').trim() !== '');
      if (row && typeof row === 'object') return Object.values(row).some((v) => String(v ?? '').trim() !== '');
      return false;
    };
    const formKSpecFallbackPatterns = {
      name: [/name\s+of\s+the\s+employee/i, /employee.*establishment/i, /employee\s+name/i, /^name$/i],
      sex: [/^sex$/i, /gender/i],
      age: [/^age$/i],
      commence: [/employment\s+commence/i],
      cease: [/employment\s+cease/i],
      rest: [/rest\s+interval/i]
    };
    const getValueForSpecKey = (row, specKey, indices) => {
      if (Array.isArray(row)) {
        if (indices && indices.length > 0) {
          for (const hi of indices) {
            const v = row[hi];
            if (v != null && String(v).trim() !== '') return v;
          }
        }
        if (specKey === 'name' && row[0] != null && String(row[0]).trim() !== '') return row[0];
        return '';
      }
      if (!row || typeof row !== 'object') return '';
      if (indices && indices.length > 0) {
        for (const hi of indices) {
          const h = hdrs[hi];
          const v = row?.[h];
          if (v != null && String(v).trim() !== '') return v;
        }
      }
      const patterns = formKSpecFallbackPatterns[specKey];
      if (patterns) {
        for (const key of Object.keys(row)) {
          const nk = String(key || '').toLowerCase().replace(/\s+/g, ' ');
          if (patterns.some((p) => p.test(nk))) {
            const v = row[key];
            if (v != null && String(v).trim() !== '') return v;
          }
        }
      }
      if (/^hours_\d+$/.test(specKey)) {
        const dayNum = specKey.replace('hours_', '');
        for (const key of Object.keys(row)) {
          const rawKey = String(key || '').trim();
          if (!rawKey) continue;
          if (FORM_K_HEADER_TO_SPEC_KEY(rawKey) === specKey) {
            const v = row[key];
            if (v != null && String(v).trim() !== '') return v;
          }
          if (rawKey === dayNum || new RegExp(`_${dayNum}$`).test(rawKey)) {
            const v = row[key];
            if (v != null && String(v).trim() !== '') return v;
          }
        }
      }
      return '';
    };

    const sourcePrimary = Array.isArray(mappedData) && mappedData.length > 0
      ? mappedData
      : (Array.isArray(mappedRowMatrix) ? mappedRowMatrix : []);
    const hdrsForNil = Array.isArray(headersToUse) ? headersToUse : [];
    const sourceRows = (filterNilPlaceholderRows
      ? filterWageRegisterSubstantiveExportRows(
          filterWageRegisterNilPlaceholderRows(sourcePrimary, hdrsForNil),
          hdrsForNil
        )
      : sourcePrimary
    ).filter((row) => rowLooksMeaningful(row) && !isWageRegisterNilPlaceholderRow(row, hdrsForNil));

    const writeCols = Array.from(new Set(specColByKey.values())).filter((n) => Number.isFinite(n));
    const minCol = writeCols.length > 0 ? Math.min(...writeCols) : tableStartCol;
    const maxCol = writeCols.length > 0 ? Math.max(...writeCols) : tableStartCol + 9;

    let snoCol = -1;
    for (let c = 1; c <= maxScanCols; c++) {
      const n = normalize(excelCellValueToString(worksheet.getCell(headerRow, c)?.value));
      if (/^s\.?\s*no\.?$/.test(n) || n === 'sno' || /^sr\.?\s*no\.?$/.test(n) || /^sl\.?\s*no\.?$/.test(n)) {
        snoCol = c;
        break;
      }
    }

    const rowHasTableBorder = (r) => {
      for (let c = minCol; c <= maxCol; c++) {
        const b = worksheet.getCell(r, c)?.border;
        if (b && (b.top?.style || b.bottom?.style || b.left?.style || b.right?.style)) return true;
      }
      return false;
    };
    let templateBodyRows = 0;
    for (let r = dataStartRow; r < dataStartRow + 24; r++) {
      if (rowHasTableBorder(r)) templateBodyRows += 1;
      else if (templateBodyRows > 0) break;
    }
    if (templateBodyRows < 1) templateBodyRows = 2;
    const extraRowsNeeded = Math.max(0, sourceRows.length - templateBodyRows);
    if (extraRowsNeeded > 0 && typeof worksheet.duplicateRow === 'function') {
      try {
        worksheet.duplicateRow(dataStartRow + templateBodyRows - 1, extraRowsNeeded, true);
      } catch (dupErr) {
        console.warn('Form K: could not duplicate template rows for extra employees', dupErr);
      }
    }

    for (let i = 0; i < Math.min(sourceRows.length + 40, 200); i++) {
      for (let c = minCol; c <= maxCol; c++) {
        const clearCell = worksheet.getCell(dataStartRow + i, c);
        const current = clearCell?.value;
        if (current && typeof current === 'object' && Object.prototype.hasOwnProperty.call(current, 'formula')) continue;
        clearCell.value = '';
      }
      if (tableStartCol > 1) {
        const strayCell = worksheet.getCell(dataStartRow + i, tableStartCol - 1);
        const strayVal = strayCell?.value;
        if (strayVal != null && strayVal !== '' && !(typeof strayVal === 'object' && Object.prototype.hasOwnProperty.call(strayVal, 'formula'))) {
          strayCell.value = '';
        }
      }
    }

    for (let i = 0; i < sourceRows.length; i++) {
      const row = sourceRows[i] || [];
      if (snoCol > 0) {
        worksheet.getCell(dataStartRow + i, snoCol).value = i + 1;
      }
      for (const [specKey, col] of specColByKey.entries()) {
        const indices = specKeyToHeaderIndices.get(specKey);
        const value = getValueForSpecKey(row, specKey, indices);
        if (value == null || value === '') continue;
        if (isWageRegisterNilPlaceholderCellValue(value)) continue;
        const cell = worksheet.getCell(dataStartRow + i, col);
        if (specKey === 'name' || specKey === 'sex') {
          cell.value = String(value);
        } else if (/^hours_\d+$/.test(specKey)) {
          cell.value = String(value).trim();
        } else if (
          specKey === 'age' &&
          (typeof value === 'number' || (typeof value === 'string' && /^\d{1,3}$/.test(String(value).trim())))
        ) {
          const ageNum = parseInt(String(value).trim(), 10);
          cell.value = Number.isFinite(ageNum) && ageNum <= 120 ? ageNum : String(value);
        } else if (typeof value === 'number' || (typeof value === 'string' && /^-?\d+(\.\d+)?$/.test(String(value).trim()))) {
          cell.value = Number(value);
        } else {
          cell.value = String(value);
        }
      }
    }

    const out = await workbook.xlsx.writeBuffer();
    const fileName = formFileName ||
      parsedFormHeader?.title?.replace(/[^a-zA-Z0-9]/g, '_') ||
      `Form_${Date.now()}.xlsx`;
    const blob = new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    return { blob, fileName };
  };

  /** Form II Maharashtra — UI starts at Sl.No. (col A); export writes from template Sl.No. column onward. */
  const buildFormIIWorkbookWithTemplateStyles = async ({
    templateArrayBuffer,
    mappedData,
    mappedRowMatrix,
    headersToUse,
    parsedHeaderRowIndex,
    parsedDataStartIndex,
    parsedFormHeader,
    formFileName
  }) => {
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(templateArrayBuffer);
    const worksheet = workbook.worksheets[0];
    if (!worksheet) throw new Error('Template worksheet not found.');

    const normalize = (txt) =>
      String(txt || '')
        .replace(/\r?\n/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase()
        .replace(/[^a-z0-9 ]/g, '');
    const excelCellValueToString = (val) => {
      if (val == null) return '';
      if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') return String(val);
      if (val instanceof Date) return val.toISOString();
      if (typeof val === 'object') {
        if (Array.isArray(val.richText)) return val.richText.map((rt) => rt?.text || '').join('');
        if (val.text != null) return String(val.text);
        if (val.result != null) return String(val.result);
      }
      return '';
    };

    const dataHdrs = normalizeFormIIMaharashtraTableHeaders(
      Array.isArray(headersToUse) ? headersToUse : []
    );

    let headerRow = parsedHeaderRowIndex != null && parsedHeaderRowIndex >= 0 ? (parsedHeaderRowIndex + 1) : -1;
    let dataStartCol = 3;
    const maxScanCols = 80;

    const findSlNoCol = (r) => {
      for (let c = 1; c <= maxScanCols; c++) {
        const t = normalize(excelCellValueToString(worksheet.getCell(r, c)?.value));
        if (t === 'slno' || t === 'sno' || /^sl\.?\s*no\.?$/.test(t) || (t.includes('sl') && t.includes('no'))) {
          return c;
        }
      }
      return -1;
    };

    if (headerRow < 1) {
      for (let r = 1; r <= 40; r++) {
        const slCol = findSlNoCol(r);
        if (slCol > 0) {
          headerRow = r;
          dataStartCol = slCol;
          break;
        }
      }
    } else {
      const slCol = findSlNoCol(headerRow);
      if (slCol > 0) dataStartCol = slCol;
    }
    if (headerRow < 1) throw new Error('Could not locate Form II table header row in template.');

    let dataStartRow = parsedDataStartIndex != null && parsedDataStartIndex >= 0
      ? (parsedDataStartIndex + 1)
      : (headerRow + 1);

    const headerToCol = new Map();
    for (let j = 0; j < dataHdrs.length; j++) {
      headerToCol.set(dataHdrs[j], dataStartCol + j);
    }

    const rowLooksMeaningful = (row) => {
      if (Array.isArray(row)) return row.some((v) => String(v ?? '').trim() !== '');
      if (row && typeof row === 'object') {
        return Object.entries(row).some(([k, v]) => !isFormIILegacySpacerHeader(k) && String(v ?? '').trim() !== '');
      }
      return false;
    };
    const getValueForHeader = (row, header, dataIndex) => {
      if (!row || typeof row !== 'object') return '';
      if (Object.prototype.hasOwnProperty.call(row, header)) return row[header];
      if (Array.isArray(row) && dataIndex >= 0) return row[dataIndex] ?? '';
      const nk = normalize(header);
      for (const key of Object.keys(row)) {
        if (isFormIILegacySpacerHeader(key)) continue;
        if (normalize(key) === nk) return row[key];
      }
      return '';
    };

    const sourcePrimary = Array.isArray(mappedData) && mappedData.length > 0
      ? mappedData
      : (Array.isArray(mappedRowMatrix) ? mappedRowMatrix : []);
    const sourceRows = sourcePrimary.filter((row) => rowLooksMeaningful(row));

    const lastCol = dataStartCol + Math.max(dataHdrs.length - 1, 0);
    for (let i = 0; i < Math.min(sourceRows.length + 40, 200); i++) {
      for (let c = 1; c < dataStartCol; c++) {
        const clearCell = worksheet.getCell(dataStartRow + i, c);
        const cur = clearCell?.value;
        if (cur && typeof cur === 'object' && Object.prototype.hasOwnProperty.call(cur, 'formula')) continue;
        clearCell.value = '';
      }
      for (let c = dataStartCol; c <= lastCol + 2; c++) {
        const clearCell = worksheet.getCell(dataStartRow + i, c);
        const cur = clearCell?.value;
        if (cur && typeof cur === 'object' && Object.prototype.hasOwnProperty.call(cur, 'formula')) continue;
        clearCell.value = '';
      }
    }

    for (let i = 0; i < sourceRows.length; i++) {
      const row = sourceRows[i] || {};
      for (let j = 0; j < dataHdrs.length; j++) {
        const header = dataHdrs[j];
        const value = getValueForHeader(row, header, j);
        if (value == null || value === '') continue;
        const cell = worksheet.getCell(dataStartRow + i, dataStartCol + j);
        if (
          j === 0 &&
          (typeof value === 'number' || (typeof value === 'string' && /^-?\d+(\.\d+)?$/.test(String(value).trim())))
        ) {
          cell.value = Number(value);
        } else {
          cell.value = String(value);
        }
      }
    }

    const out = await workbook.xlsx.writeBuffer();
    const fileName = formFileName ||
      parsedFormHeader?.title?.replace(/[^a-zA-Z0-9]/g, '_') ||
      `Form_${Date.now()}.xlsx`;
    const blob = new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    return { blob, fileName };
  };

  const buildForm10WorkbookWithTemplateStyles = async ({
    templateArrayBuffer,
    mappedData,
    mappedRowMatrix,
    headersToUse,
    parsedHeaderRowIndex,
    parsedDataStartIndex,
    parsedFormHeader,
    formFileName,
    headerFormData
  }) => {
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(templateArrayBuffer);
    const worksheet = workbook.worksheets[0];
    if (!worksheet) throw new Error('Template worksheet not found.');

    const normalize = (txt) =>
      String(txt || '')
        .replace(/\r?\n/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase();
    const excelCellValueToString = (val) => {
      if (val == null) return '';
      if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') return String(val);
      if (val instanceof Date) return val.toISOString();
      if (typeof val === 'object') {
        if (Array.isArray(val.richText)) return val.richText.map((rt) => rt?.text || '').join('');
        if (val.text != null) return String(val.text);
        if (val.result != null) return String(val.result);
      }
      return '';
    };

    const maxScanRows = Math.max(120, worksheet.rowCount + 10);
    const maxScanCols = 260;
    let headerRow = parsedHeaderRowIndex != null && parsedHeaderRowIndex >= 0 ? (parsedHeaderRowIndex + 1) : -1;
    if (headerRow < 1) throw new Error('Could not locate Form 10 header row from parser.');
    let startCol = 1;
    for (let c = 1; c <= maxScanCols; c++) {
      const t = normalize(excelCellValueToString(worksheet.getCell(headerRow, c)?.value));
      if (t) {
        startCol = c;
        break;
      }
    }

    // Prefer numeric marker row (1..N) near header for exact template column model.
    let markerRow = (parsedDataStartIndex != null && parsedDataStartIndex > 0) ? parsedDataStartIndex : -1;
    let markerCols = [];
    for (let r = Math.max(headerRow, markerRow > 0 ? markerRow - 1 : headerRow); r <= Math.min(headerRow + 5, maxScanRows); r++) {
      const cols = [];
      for (let c = startCol; c <= maxScanCols; c++) {
        const t = normalize(excelCellValueToString(worksheet.getCell(r, c)?.value));
        if (/^\d+$/.test(t)) cols.push(c);
      }
      if (cols.length > markerCols.length) {
        markerCols = cols;
        markerRow = r;
      }
    }
    const dataStartRow =
      parsedDataStartIndex != null && parsedDataStartIndex >= 0
        ? (parsedDataStartIndex + 1)
        : (markerCols.length >= 5 && markerRow > 0 ? (markerRow + 1) : (headerRow + 1));
    const orderedCols = markerCols.length >= 5
      ? markerCols
      : Array.from({ length: Math.max(12, Array.isArray(headersToUse) ? headersToUse.length : 12) }, (_, i) => startCol + i);

    const sourceHeaders = Array.isArray(headersToUse) && headersToUse.length > 0 ? [...headersToUse] : [];
    const templateHeaderLabels = orderedCols.map((col) =>
      String(excelCellValueToString(worksheet.getCell(headerRow, col)?.value) || '').trim()
    );
    const resolveTemplateHeaderLabel = (idx) => {
      let label = templateHeaderLabels[idx] || '';
      const normLabel = normalize(label);
      if (!label || /^\d+$/.test(normLabel)) {
        if (sourceHeaders[idx]) label = sourceHeaders[idx];
      }
      if (!label || /^\d+$/.test(normalize(label))) {
        const above = excelCellValueToString(worksheet.getCell(headerRow - 1, orderedCols[idx])?.value).trim();
        if (above && !/^\d+$/.test(normalize(above))) label = above;
      }
      return label;
    };
    const headerNormKey = (h) => normalize(String(h || '').replace(/[^a-z0-9]/gi, ' '));
    const form10HeaderAliasBucket = (norm) => {
      if (!norm) return '';
      if (/number\s+in\s+register|register\s+number/.test(norm)) return 'register';
      if (/employee\s+name|^name$/.test(norm)) return 'name';
      if (/department/.test(norm)) return 'department';
      if (/dates?\s+on\s+which.*overtime.*payment|overtime.*payment.*made/.test(norm)) return 'otpaydate';
      if (/date\s+of\s+which\s+overtime/.test(norm)) return 'otworkeddate';
      if (
        (/date.*overtime|overtime.*date/.test(norm) || /date\s+on\s+which/.test(norm)) &&
        !/payment/.test(norm) &&
        !/rate/.test(norm)
      ) {
        return 'otworkeddate';
      }
      if (/extent.*overtime|overtime.*occasion/.test(norm)) return 'otextent';
      if (/total\s+overtime|overtime\s+worked.*production/.test(norm)) return 'ottotal';
      if (/normal\s+hours/.test(norm)) return 'normalhours';
      if (/normal\s+rate/.test(norm)) return 'normalrate';
      if (/overtime\s+rate/.test(norm)) return 'otrate';
      if (/normal\s+earnings/.test(norm)) return 'normalearnings';
      if (/overtime\s+earnings/.test(norm)) return 'otearnings';
      if (/cash\s+equivalent|advantage.*concession/.test(norm)) return 'cashequiv';
      if (/total\s+earnings/.test(norm)) return 'totalearnings';
      return norm;
    };
    const getRowValueForHeader = (rowObj, header, headerIndex) => {
      if (!rowObj || typeof rowObj !== 'object' || Array.isArray(rowObj)) return '';
      const isPlaceholder = (v) => /^enter\s+/i.test(String(v ?? '').trim());
      const pickVal = (v) => {
        if (v == null || String(v).trim() === '' || isPlaceholder(v)) return '';
        return v;
      };
      if (header && Object.prototype.hasOwnProperty.call(rowObj, header)) {
        const direct = pickVal(rowObj[header]);
        if (direct !== '') return direct;
      }
      if (headerIndex != null && headerIndex >= 0 && sourceHeaders[headerIndex]) {
        const sourceKey = sourceHeaders[headerIndex];
        if (Object.prototype.hasOwnProperty.call(rowObj, sourceKey)) {
          const sourceVal = pickVal(rowObj[sourceKey]);
          if (sourceVal !== '') return sourceVal;
        }
      }
      const target = headerNormKey(header);
      if (!target) return '';
      const targetAlias = form10HeaderAliasBucket(target);
      const rowKeys = Object.keys(rowObj);
      const exact = rowKeys.find((k) => headerNormKey(k) === target);
      if (exact) {
        const v = pickVal(rowObj[exact]);
        if (v !== '') return v;
      }
      if (targetAlias) {
        const aliasMatches = rowKeys.filter(
          (k) => form10HeaderAliasBucket(headerNormKey(k)) === targetAlias
        );
        for (let ai = 0; ai < aliasMatches.length; ai += 1) {
          const v = pickVal(rowObj[aliasMatches[ai]]);
          if (v !== '') return v;
        }
      }
      const fuzzy = rowKeys.find((k) => {
        const nk = headerNormKey(k);
        return nk && (nk.includes(target) || target.includes(nk));
      });
      if (fuzzy) {
        const v = pickVal(rowObj[fuzzy]);
        if (v !== '') return v;
      }
      if (headerIndex != null && headerIndex >= 0) {
        const vals = Object.values(rowObj);
        const v = pickVal(vals[headerIndex]);
        if (v !== '') return v;
      }
      return '';
    };
    const toForm10OrderedValues = (row, rowIndex) => {
      if (Array.isArray(row)) {
        const out = [...row];
        const first = String(out[0] ?? '').trim();
        const m = first.match(/^(\d+)\s+(.+)$/);
        if (m && (!out[1] || String(out[1]).trim() === '')) {
          out[0] = m[1];
          out[1] = m[2];
        }
        if (out[0] == null || String(out[0]).trim() === '') out[0] = rowIndex + 1;
        const colCount = Math.max(orderedCols.length, sourceHeaders.length, out.length);
        return Array.from({ length: colCount }, (_, idx) => out[idx] ?? '');
      }
      const colCount = Math.max(orderedCols.length, sourceHeaders.length, templateHeaderLabels.length);
      const out = Array.from({ length: colCount }, (_, idx) => {
        const templateLabel = resolveTemplateHeaderLabel(idx);
        const sourceLabel = sourceHeaders[idx] || '';
        let val = templateLabel ? getRowValueForHeader(row, templateLabel, idx) : '';
        if (val === '' && sourceLabel && sourceLabel !== templateLabel) {
          val = getRowValueForHeader(row, sourceLabel, idx);
        }
        return val != null ? val : '';
      });
      if (out[0] == null || String(out[0]).trim() === '') out[0] = rowIndex + 1;
      return out;
    };

    const rowLooksMeaningful = (row) => {
      if (Array.isArray(row)) {
        const vals = row.map((v) => String(v ?? '').trim()).filter(Boolean);
        if (vals.length === 0) return false;
        return vals.some((v) => /[a-z]/i.test(v)) || !vals.every((v) => /^-?\d+(\.\d+)?$/.test(v));
      }
      if (row && typeof row === 'object') {
        const vals = Object.values(row).map((v) => String(v ?? '').trim()).filter(Boolean);
        if (vals.length === 0) return false;
        return vals.some((v) => /[a-z]/i.test(v)) || !vals.every((v) => /^-?\d+(\.\d+)?$/.test(v));
      }
      return false;
    };

    const sourcePrimary = Array.isArray(mappedData) && mappedData.length > 0
      ? mappedData
      : (Array.isArray(mappedRowMatrix) ? mappedRowMatrix : []);
    const sourceRows = sourcePrimary
      .filter((row) => rowLooksMeaningful(row))
      .map((row, idx) => toForm10OrderedValues(row, idx));

    // Remove stale sample data above/below model row while keeping header and numeric marker row intact.
    const isNumericMarkerTemplateRow = (r) => {
      if (!markerCols || markerCols.length < 5) return false;
      let numericHits = 0;
      for (let i = 0; i < markerCols.length; i++) {
        const v = normalize(excelCellValueToString(worksheet.getCell(r, markerCols[i])?.value));
        if (/^\d+$/.test(v)) numericHits++;
      }
      return numericHits >= Math.max(5, Math.floor(markerCols.length * 0.6));
    };
    const clearFromRow = Math.max(1, dataStartRow);
    const clearToRow = Math.min(maxScanRows, Math.max(dataStartRow + sourceRows.length + 30, clearFromRow + 30));
    for (let r = clearFromRow; r <= clearToRow; r++) {
      if (isNumericMarkerTemplateRow(r)) continue;
      for (let j = 0; j < orderedCols.length; j++) {
        worksheet.getCell(r, orderedCols[j]).value = '';
      }
    }

    for (let i = 0; i < sourceRows.length; i++) {
      const row = sourceRows[i] || [];
      let maxVisualLines = 1;
      // Clear model row cells first so previous sample values do not leak into next rows.
      for (let j = 0; j < orderedCols.length; j++) {
        worksheet.getCell(dataStartRow + i, orderedCols[j]).value = '';
      }
      for (let j = 0; j < orderedCols.length; j++) {
        const value = row[j];
        if (value == null || value === '') continue;
        const cell = worksheet.getCell(dataStartRow + i, orderedCols[j]);
        if (j === 0 && (typeof value === 'number' || (typeof value === 'string' && /^-?\d+(\.\d+)?$/.test(String(value).trim())))) {
          cell.value = Number(value);
        } else {
          const text = String(value);
          cell.value = text;
          cell.alignment = { ...(cell.alignment || {}), wrapText: true, vertical: 'top' };
          const approxCharsPerLine = 22;
          const visualLines = Math.max(1, Math.ceil(text.length / approxCharsPerLine));
          if (visualLines > maxVisualLines) maxVisualLines = visualLines;
        }
      }
      // Auto-expand row height for long sentence cells so content is fully visible.
      const targetRow = worksheet.getRow(dataStartRow + i);
      const baseHeight = 18;
      targetRow.height = Math.max(baseHeight, Math.min(120, baseHeight * maxVisualLines));
    }

    writeForm10Form12HeaderFieldsToExcelJsWorksheet(worksheet, headerFormData, parsedFormHeader);

    const out = await workbook.xlsx.writeBuffer();
    const fileName = formFileName ||
      parsedFormHeader?.title?.replace(/[^a-zA-Z0-9]/g, '_') ||
      `Form_${Date.now()}.xlsx`;
    const blob = new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    return { blob, fileName };
  };

  /** Form 11 (ESIC Accident Book): preserve template grid + numeric column marker row (1..N). */
