        if (/present\s+address/.test(joined) && /permanent\s+address/.test(joined) && /worker\s+identity/.test(joined)) {
          return true;
        }
        if (/name\s+of\s+the\s+worker/.test(joined) && /present\s+address/.test(joined)) return true;
        return false;
